def _db():
    con = sqlite3.connect(DB_PATH, timeout=15)
    con.row_factory = sqlite3.Row
    try:
        if os.path.exists(WORKSHEET_CONTENT_DB_PATH):
            con.execute("ATTACH DATABASE ? AS wscontent",(WORKSHEET_CONTENT_DB_PATH,))
            con.execute("DROP VIEW IF EXISTS temp.worksheet_item_templates")
            con.execute("DROP VIEW IF EXISTS temp.worksheet_blueprints")
            con.execute("CREATE TEMP VIEW worksheet_item_templates AS SELECT * FROM wscontent.worksheet_item_templates")
            con.execute("CREATE TEMP VIEW worksheet_blueprints AS SELECT * FROM wscontent.worksheet_blueprints")
    except Exception:
        pass
    return con


