def _math_y1_allowed_sk(topic, sk_code):
    pats=MATH_Y1_TOPIC_SK.get(topic)
    if not pats:
        return False
    return any(sk_code == p or (p.endswith('.') and sk_code.startswith(p)) for p in pats)

