def _textbook_auto_standards_ready(s):
    """True when textbook mode must bypass every manual SK/SP selector."""
    if not str(s.get('rph_mode') or '').startswith('fast_textbook'):
        return False
    # Normal textbook skill lesson: exact page mapping already committed SP(s).
    if s.get('sp_code') or s.get('bi_main_sp_code') or s.get('selected_sp_codes'):
        return True
    # Language Awareness/grammar: SOW intentionally has no explicit 4-skill LS.
    return bool(s.get('textbook_no_explicit_skill_ls'))

def _continue_after_rph_time(cid, ss):
    """Continue after time without losing committed curriculum selection."""
    if ss.get('task') == 'worksheet' and (ss.get('sp_code') or ss.get('selected_sp_codes') or _textbook_auto_standards_ready(ss)):
        return _rph_session_question(cid)
    if ss.get('assessment_mode') == 'summative':
        return _rph_session_question(cid)
    if _textbook_auto_standards_ready(ss):
        return _rph_session_question(cid)
    if str(ss.get('rph_mode') or '').startswith('fast_textbook'):
        # Fail closed: never expose unrelated whole-unit/year SK/SP in textbook mode.
        return send(cid,'⚠️ Muka surat ini belum mempunyai SK/SP verified yang boleh diisi automatik. Sila pilih muka surat lain.',[[{'text':'📖 Masukkan Muka Surat Lain','callback_data':'fast_use_textbook'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    if ss.get('task') == 'rph' and ss.get('rph_mode') == 'fast':
        if not _prepare_fast_rph_content(ss):
            ss['rph_mode']='fast_custom'
            ss['assessment_mode']='formative'
            ss.pop('topic',None); ss.pop('subtopic',None)
            send(cid,'📘 <b>RPT verified belum tersedia untuk pilihan ini.</b>\n\nPilih Unit/Tajuk yang telah disahkan. Selepas itu cikgu boleh pilih SK dan SP berkaitan tanpa mengulang Tahun/Subjek.',[])
            return show_topics(cid,0)
        return _rph_session_question(cid)
    return show_curriculum_sk(cid, ss)

def _textbook_page_rows(year_label, subject):
    """Return verified textbook page ranges for one year/form + subject."""
    con=_db()
    try:
        rows=con.execute("""SELECT id,year_label,subject,topic,book_title,publisher,edition,page_start,page_end,activity_ref,source_url
                            FROM textbook_references
                            WHERE year_label=? AND subject=? AND verified=1
                              AND page_start IS NOT NULL AND page_end IS NOT NULL
                            ORDER BY book_title,page_start,page_end,id""",(year_label,subject)).fetchall()
        return [dict(r) for r in rows]
    finally:
        con.close()


def _textbook_page_lookup(year_label, subject, page_no):
    try: page_no=int(page_no)
    except Exception: return None
    for r in _textbook_page_rows(year_label,subject):
        try:
            if int(r.get('page_start')) <= page_no <= int(r.get('page_end')):
                return r
        except Exception:
            continue
    return None


def _ensure_textbook_page_sp_map_schema(con):
    """Ensure page mapping can store the same SP on one page for different SOW lessons.

    Older DBs used uniqueness without lesson_no/focus, which could silently block a
    legitimate second lesson on the same textbook page. Migration is transactional and
    preserves all existing rows/IDs.
    """
    con.execute("""CREATE TABLE IF NOT EXISTS textbook_page_sp_map(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        year_label TEXT NOT NULL, subject TEXT NOT NULL,
        book_title TEXT NOT NULL DEFAULT '', unit_title TEXT NOT NULL DEFAULT '',
        page_start INTEGER NOT NULL, page_end INTEGER NOT NULL,
        lesson_no TEXT NOT NULL DEFAULT '', focus TEXT NOT NULL DEFAULT '',
        sp_code TEXT NOT NULL, role TEXT NOT NULL DEFAULT '',
        source_url TEXT NOT NULL DEFAULT '', verified INTEGER NOT NULL DEFAULT 0,
        checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(year_label,subject,book_title,page_start,page_end,lesson_no,focus,sp_code,role)
    )""")
    schema_row=con.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name='textbook_page_sp_map'").fetchone()
    schema=(schema_row[0] if schema_row else '') or ''
    old_unique='UNIQUE(year_label,subject,book_title,page_start,page_end,sp_code,role)'
    if old_unique.replace(' ','') not in schema.replace(' ',''):
        return
    con.execute('SAVEPOINT migrate_page_sp_schema')
    try:
        con.execute('ALTER TABLE textbook_page_sp_map RENAME TO textbook_page_sp_map_old')
        con.execute("""CREATE TABLE textbook_page_sp_map(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            year_label TEXT NOT NULL, subject TEXT NOT NULL,
            book_title TEXT NOT NULL DEFAULT '', unit_title TEXT NOT NULL DEFAULT '',
            page_start INTEGER NOT NULL, page_end INTEGER NOT NULL,
            lesson_no TEXT NOT NULL DEFAULT '', focus TEXT NOT NULL DEFAULT '',
            sp_code TEXT NOT NULL, role TEXT NOT NULL DEFAULT '',
            source_url TEXT NOT NULL DEFAULT '', verified INTEGER NOT NULL DEFAULT 0,
            checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(year_label,subject,book_title,page_start,page_end,lesson_no,focus,sp_code,role)
        )""")
        con.execute("""INSERT INTO textbook_page_sp_map(
            id,year_label,subject,book_title,unit_title,page_start,page_end,lesson_no,focus,
            sp_code,role,source_url,verified,checked_at)
            SELECT id,year_label,subject,book_title,unit_title,page_start,page_end,lesson_no,focus,
                   sp_code,role,source_url,verified,checked_at
            FROM textbook_page_sp_map_old""")
        con.execute('DROP TABLE textbook_page_sp_map_old')
        con.execute('RELEASE SAVEPOINT migrate_page_sp_schema')
    except Exception:
        con.execute('ROLLBACK TO SAVEPOINT migrate_page_sp_schema')
        con.execute('RELEASE SAVEPOINT migrate_page_sp_schema')
        raise


def _ensure_textbook_page_lesson_map_schema(con):
    """Ensure verified page-level SOW metadata exists independently of SK/SP."""
    con.execute("""CREATE TABLE IF NOT EXISTS textbook_page_lesson_map(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        year_label TEXT NOT NULL, subject TEXT NOT NULL,
        book_title TEXT NOT NULL DEFAULT '', unit_title TEXT NOT NULL DEFAULT '',
        page_start INTEGER NOT NULL, page_end INTEGER NOT NULL,
        lesson_no TEXT NOT NULL DEFAULT '', focus TEXT NOT NULL DEFAULT '',
        content_topic TEXT NOT NULL DEFAULT '', language_focus TEXT NOT NULL DEFAULT '',
        activity_ref TEXT NOT NULL DEFAULT '', source_url TEXT NOT NULL DEFAULT '',
        verified INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '',
        checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(year_label,subject,book_title,page_start,page_end,lesson_no,focus)
    )""")
    con.execute("CREATE INDEX IF NOT EXISTS idx_page_lesson_lookup ON textbook_page_lesson_map(year_label,subject,page_start,page_end,verified)")


def _textbook_exact_page_lessons(year_label, subject, page_no, book_title=''):
    try: page_no=int(page_no)
    except Exception: return []
    con=_db()
    try:
        _ensure_textbook_page_lesson_map_schema(con)
        args=[year_label,subject,page_no,page_no]
        sql="""SELECT * FROM textbook_page_lesson_map
                 WHERE year_label=? AND subject=? AND verified=1
                   AND page_start<=? AND page_end>=?"""
        if book_title:
            sql += " AND (book_title=? OR book_title='')"
            args.append(book_title)
        sql += " ORDER BY id"
        return [dict(r) for r in con.execute(sql,args).fetchall()]
    finally:
        con.close()


def _apply_textbook_page_lesson_context(s, page_no, lesson_no='', focus=''):
    rows=_textbook_exact_page_lessons(s.get('year',''),s.get('subject',''),page_no,s.get('textbook_book_title',''))
    if not rows: return None
    lesson_no=str(lesson_no or '').strip(); focus0=str(focus or '').strip().lower()
    row=None
    for r in rows:
        if lesson_no and str(r.get('lesson_no') or '').strip()==lesson_no:
            if not focus0 or str(r.get('focus') or '').strip().lower()==focus0:
                row=r; break
    if row is None and focus0:
        row=next((r for r in rows if str(r.get('focus') or '').strip().lower()==focus0),None)
    if row is None: row=rows[0]
    s['textbook_lesson_no']=str(row.get('lesson_no') or s.get('textbook_lesson_no') or '')
    s['textbook_page_focus']=str(row.get('focus') or s.get('textbook_page_focus') or '')
    s['textbook_content_topic']=str(row.get('content_topic') or '')
    s['textbook_language_focus']=str(row.get('language_focus') or '')
    s['textbook_activity_ref']=str(row.get('activity_ref') or '')
    s['textbook_page_start']=row.get('page_start'); s['textbook_page_end']=row.get('page_end')
    if str(row.get('unit_title') or '').strip(): s['topic']=str(row.get('unit_title')).strip()
    content=str(row.get('content_topic') or '').strip()
    s['subtopic']=content or f'Muka surat {int(page_no)}'
    return row


def _textbook_exact_page_standards(year_label, subject, page_no, book_title=''):
    """Return only page-level SK/SP mappings explicitly verified from SOW/RPT.

    Important: this never falls back to all standards in the unit.
    """
    try: page_no=int(page_no)
    except Exception: return []
    con=_db()
    try:
        _ensure_textbook_page_sp_map_schema(con)
        args=[year_label,subject,page_no,page_no]
        sql="""SELECT p.*,c.sk_code,c.sk_text,c.sp_text
                 FROM textbook_page_sp_map p
                 JOIN curriculum_standards c
                   ON c.year_label=p.year_label AND c.subject=p.subject
                  AND c.sp_code=p.sp_code AND c.verified=1
                 WHERE p.year_label=? AND p.subject=? AND p.verified=1
                   AND p.page_start<=? AND p.page_end>=?"""
        if book_title:
            sql += " AND (p.book_title=? OR p.book_title='')"
            args.append(book_title)
        sql += " ORDER BY CASE p.role WHEN 'main' THEN 0 WHEN 'complementary' THEN 1 ELSE 2 END,p.id"
        return [dict(r) for r in con.execute(sql,args).fetchall()]
    finally:
        con.close()


def _group_textbook_page_standards(rows):
    """Group exact page mappings by the real SOW lesson/focus.

    Some textbook pages legitimately appear in more than one lesson/focus.
    Never mix Main from one lesson with Complementary from another.
    """
    groups=[]; index={}
    for r in (rows or []):
        key=(str(r.get('lesson_no') or '').strip(), str(r.get('focus') or '').strip())
        if key not in index:
            index[key]=len(groups)
            groups.append({'lesson_no':key[0],'focus':key[1],'rows':[]})
        groups[index[key]]['rows'].append(r)
    return groups


def _textbook_page_focus_groups(standard_rows, lesson_rows):
    """Merge verified SK/SP groups with SOW lesson metadata for one page.

    This keeps Language Awareness visible when the same textbook page is also
    used by a four-skill lesson. Language Awareness intentionally carries no
    invented four-skill LS.
    """
    std_groups=_group_textbook_page_standards(standard_rows)
    std_by_key={(str(g.get('lesson_no') or '').strip(), str(g.get('focus') or '').strip().lower()):g for g in std_groups}
    groups=[]; seen=set()
    for lm in (lesson_rows or []):
        lesson=str(lm.get('lesson_no') or '').strip()
        focus=str(lm.get('focus') or '').strip()
        key=(lesson,focus.lower())
        if key in seen: continue
        seen.add(key)
        sg=std_by_key.get(key)
        if sg:
            groups.append({'lesson_no':lesson,'focus':focus,'rows':sg.get('rows') or [],'kind':'standards'})
        elif 'language awareness' in focus.lower():
            groups.append({'lesson_no':lesson,'focus':focus,'rows':[],'kind':'language_awareness'})
    for sg in std_groups:
        lesson=str(sg.get('lesson_no') or '').strip(); focus=str(sg.get('focus') or '').strip()
        key=(lesson,focus.lower())
        if key not in seen:
            groups.append({'lesson_no':lesson,'focus':focus,'rows':sg.get('rows') or [],'kind':'standards'})
            seen.add(key)
    return groups


def _clear_textbook_standard_state(s):
    """Prevent a previous textbook selection leaking SK/SP into a new page/focus."""
    for k in ('sp_code','sp_text','sk_code','sk_text','selected_sp_codes','selected_sk_codes',
              'bi_main_row','bi_main_sp_code','bi_main_sp_text','bi_comp_row','bi_comp_sp_code',
              'bi_comp_sp_text','textbook_no_explicit_skill_ls','textbook_standards_source'):
        s.pop(k,None)


def _start_textbook_language_awareness(cid, s, page_no, lesson_no='', focus='Language Awareness'):
    _clear_textbook_standard_state(s)
    row=_apply_textbook_page_lesson_context(s,page_no,lesson_no,focus)
    if not row:
        return send(cid,'⚠️ Metadata Language Awareness verified tidak dapat dipadankan. Sila pilih muka surat lain.',[[{'text':'📖 Masukkan Muka Surat Lain','callback_data':'fast_use_textbook'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    lang=str(s.get('textbook_language_focus') or '').strip()
    s['textbook_standards_source']='SOW/textbook page metadata; no explicit four-skill LS for this Language Awareness lesson'
    s['textbook_no_explicit_skill_ls']=True
    send(cid,f"📖 <b>{html.escape(str(s.get('topic') or ''))}</b> • muka surat <b>{int(page_no)}</b>\n\n🎯 Fokus: <b>{html.escape(str(row.get('focus') or 'Language Awareness'))}</b>\n🗣️ Grammar: <b>{html.escape(lang or 'rujuk halaman buku teks')}</b>\n\nℹ️ SOW tidak menetapkan Main/Complementary Learning Standard empat kemahiran secara eksplisit untuk lesson ini. CikguLaju <b>tidak akan meminta cikgu pilih SK/SP</b> dan tidak akan mencipta SP palsu. RPH akan terus menggunakan kandungan/grammar halaman ini.")
    return start_rph_session(cid)


def _textbook_page_match_message(s, rows, page_no):
    """Build the short confirmation shown after an exact page mapping is chosen."""
    if not rows: return ''
    main=next((r for r in rows if str(r.get('role') or '').lower()=='main'), rows[0])
    comp=next((r for r in rows if str(r.get('role') or '').lower()=='complementary'), None)
    lines=[
        '✅ <b>Padanan tepat muka surat ditemui</b>', '',
        f"📘 Buku: <b>{html.escape(str(s.get('textbook_book_title') or ''))}</b>",
        f"📖 Muka surat: <b>{int(page_no)}</b>",
        f"🏷️ Unit/Tajuk: <b>{html.escape(str(s.get('topic') or ''))}</b>"
    ]
    focus=str(rows[0].get('focus') or '').strip()
    if focus: lines.append(f"🎯 Fokus: <b>{html.escape(focus)}</b>")
    content=str(s.get('textbook_content_topic') or '').strip()
    lang=str(s.get('textbook_language_focus') or '').strip()
    if content: lines.append(f"🧩 Kandungan halaman: <b>{html.escape(content)}</b>")
    if lang: lines.append(f"🗣️ Bahasa/Grammar: <b>{html.escape(lang)}</b>")
    lines.append(f"✅ Main: <b>{html.escape(str(main.get('sk_code') or ''))} / {html.escape(str(main.get('sp_code') or ''))}</b> — {html.escape(str(main.get('sp_text') or ''))}")
    if comp:
        lines.append(f"➕ Complementary: <b>{html.escape(str(comp.get('sk_code') or ''))} / {html.escape(str(comp.get('sp_code') or ''))}</b> — {html.escape(str(comp.get('sp_text') or ''))}")
    lines += ['', 'SK/SP telah diisi automatik berdasarkan muka surat — tiada menu pemilihan SK/SP. Teruskan maklumat sesi RPH.']
    return '\n'.join(lines)


def _commit_textbook_page_standards(s, rows):
    """Commit exact page standards directly into RPH state; no extra SK/SP menu."""
    if not rows: return False
    selected=[]; seen=set()
    for r in rows:
        code=str(r.get('sp_code') or '').strip()
        if not code or code in seen: continue
        seen.add(code)
        selected.append({
            'sp_code':code,'sp_text':str(r.get('sp_text') or ''),
            'sk_code':str(r.get('sk_code') or ''),'sk_text':str(r.get('sk_text') or '')
        })
    if not selected: return False
    if _is_english_subject(s):
        main_row=next((r for r in rows if str(r.get('role') or '').lower()=='main'), rows[0])
        main={
            'sp_code':str(main_row.get('sp_code') or ''),'sp_text':str(main_row.get('sp_text') or ''),
            'sk_code':str(main_row.get('sk_code') or ''),'sk_text':str(main_row.get('sk_text') or '')
        }
        comp_row=next((r for r in rows if str(r.get('role') or '').lower()=='complementary'), None)
        s['bi_main_row']=main
        s['bi_main_sp_code']=main['sp_code']; s['bi_main_sp_text']=main['sp_text']
        if comp_row:
            comp={
                'sp_code':str(comp_row.get('sp_code') or ''),'sp_text':str(comp_row.get('sp_text') or ''),
                'sk_code':str(comp_row.get('sk_code') or ''),'sk_text':str(comp_row.get('sk_text') or '')
            }
            _commit_bi_standards(s,comp)
        else:
            _commit_multi_sp(s,[main])
        if len(selected) > 2 or not comp_row:
            _commit_multi_sp(s,selected)
            s['bi_main_row']=main
            s['bi_main_sp_code']=main['sp_code']; s['bi_main_sp_text']=main['sp_text']
            if comp_row:
                s['bi_comp_row']=comp
                s['bi_comp_sp_code']=comp['sp_code']; s['bi_comp_sp_text']=comp['sp_text']
    else:
        _commit_multi_sp(s,selected)
    s['textbook_page_focus']=str(rows[0].get('focus') or '')
    s['textbook_lesson_no']=str(rows[0].get('lesson_no') or '')
    return True


def _fast_rph_source_choice(cid):
    s=state.setdefault(cid,{})
    sub=html.escape(str(s.get('subject') or ''))
    yr=html.escape(str(s.get('year') or ''))
    kb=[[{'text':'✨ Guna Cadangan RPT','callback_data':'fast_use_rpt'}]]
    if _textbook_page_rows(s.get('year',''),s.get('subject','')):
        kb.append([{'text':'📖 Ikut Muka Surat Buku Teks','callback_data':'fast_use_textbook'}])
    kb.extend([
        [{'text':'✏️ Pilih Tajuk Sendiri','callback_data':'fast_choose_topic'}],
        [{'text':'🏠 Menu Utama','callback_data':'home'}]
    ])
    send(cid, f'⚡ <b>RPH Pantas — {sub} {yr}</b>\n\nPilih sumber kandungan RPH: ikut RPT, ikut muka surat buku teks, atau pilih sendiri tajuk dan standard.', kb)


