# ===== v23.86 TEMPORARY BETA AUTO PACK =====
def _temporary_auto_pack_v2386(cid):
    """Best-effort Bahan Pantas: send every component that can be built.

    One missing component never aborts the package. Progress represents real stages,
    while user-facing missing copy uses 'Belum tersedia / Dalam pembinaan'.
    """
    ss=state.setdefault(cid,{})
    required=('year','subject','topic','sk_code','sp_code')
    if any(not str(ss.get(k) or '').strip() for k in required):
        return send(cid,'⚠️ Konteks kurikulum belum lengkap. Sila pilih semula Tahun/Tingkatan, subjek dan SK/SP.',
                    [[{'text':'Sediakan Bahan PdP','callback_data':'quick'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    with _runtime_lock:
        if cid in _processing_chats:
            return send(cid,'⏳ <b>Bahan masih sedang disediakan.</b>')
        _processing_chats.add(cid)
    pmid=None; paths=[]; status={}
    try:
        pmid=_generation_progress_start(cid,'Sediakan Bahan PdP — menyediakan semua bahan')
        _generation_progress_update(cid,pmid,10,'Menyemak Tahun/Tingkatan, subjek dan SK/SP...','Bahan Pantas')

        # RPH — independent component
        _generation_progress_update(cid,pmid,25,'Menyediakan RPH...','Bahan Pantas')
        try:
            rph_ctx=dict(ss); rph_ctx['task']='rph'
            rph_result=_inject_worksheet_differentiation_into_rph(_local_rph_text(rph_ctx))
            if not rph_result: raise RuntimeError('RPH bank returned empty result')
            pth=create_pdf_file(rph_ctx,rph_result,str(cid)+'_quick_rph'); paths.append(pth)
            send_document(cid,pth,'📘 RPH CikguLaju'); status['📘 RPH']='dihantar'
        except Exception as e:
            print('v23.86 auto-pack RPH:',repr(e),flush=True); status['📘 RPH']='🚧 Dalam pembinaan'

        # BBM — independent component
        _generation_progress_update(cid,pmid,50,'Menyediakan BBM...','Bahan Pantas')
        try:
            bbm_ctx=dict(ss); bbm_ctx['task']='bbm'; bbm_ctx['bbm_variation_seed']=secrets.token_hex(6)
            pth=create_bbm_flashcards_pdf(bbm_ctx,cid); paths.append(pth)
            send_document(cid,pth,'🎨 BBM CikguLaju - sedia untuk cetak'); status['🎨 BBM']='dihantar'
        except Exception as e:
            print('v23.86 auto-pack BBM:',repr(e),flush=True); status['🎨 BBM']='🚧 Dalam pembinaan'

        # Worksheet — independent component
        _generation_progress_update(cid,pmid,70,'Menyediakan worksheet...','Bahan Pantas')
        try:
            ws_ctx=dict(ss); ws_ctx['task']='worksheet'; ws_ctx.setdefault('worksheet_questions',8); ws_ctx['difficulty']='all4'; ws_ctx['worksheet_pack_4levels']=True
            ws_results=_generate_four_level_worksheets(ws_ctx)
            if not ws_results: raise RuntimeError('Worksheet bank returned empty result')
            pth=create_four_level_worksheet_pdf(ws_ctx,ws_results,cid); paths.append(pth)
            send_document(cid,pth,'📝 Worksheet CikguLaju'); status['📝 Worksheet']='dihantar'
        except Exception as e:
            print('v23.86 auto-pack worksheet:',repr(e),flush=True); status['📝 Worksheet']='🚧 Dalam pembinaan'

        # Audio is source-locked: expose it only when the selected BOT_READY
        # lesson already carries a verified reference. Never infer a track.
        _generation_progress_update(cid,pmid,85,'Menyemak audio dan media berkaitan...','Bahan Pantas')
        if ss.get('audio_status')=='VERIFIED_AUDIO' and ss.get('audio_reference'):
            try:
                audio_sent=_eng12_send_verified_audio(cid,ss.get('audio_reference'))
                status['🔊 Audio / Media']='dihantar' if audio_sent else '🚧 Audio verified ada tetapi fail audio belum berjaya dihantar'
            except Exception as e:
                print('v25.01 verified audio:',repr(e),flush=True)
                status['🔊 Audio / Media']='🚧 Rujukan verified ada, penghantaran gagal'
        else:
            status['🔊 Audio / Media']='🚧 Belum ada audio verified untuk lesson ini'

        _generation_progress_update(cid,pmid,95,'Menyusun status semua bahan...','Bahan Pantas')
        _generation_progress_update(cid,pmid,100,'Selesai. Semua bahan yang ada telah dihantar.','Bahan Pantas')
        lines=['✅ <b>Penyediaan Bahan PdP selesai — 100%</b>','']
        for name,val in status.items():
            prefix='✅ ' if val=='dihantar' else ''
            lines.append(f'{name} — {prefix}{val}')
        lines += ['','Bahan yang tersedia telah dihantar. Bahan lain sedang dilengkapkan dalam bank CikguLaju.']
        send(cid,'\n'.join(lines),[[{'text':'📚 Sediakan Bahan Lagi','callback_data':'quick'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    except Exception as e:
        print('v23.86 auto-pack outer error:',repr(e),flush=True)
        if pmid:
            try: _generation_progress_update(cid,pmid,100,'Proses selesai dengan sebahagian bahan.','Bahan Pantas')
            except Exception: pass
        send(cid,'⚠️ Proses selesai, tetapi sebahagian bahan masih dalam pembinaan. Bahan yang sempat disediakan kekal dihantar.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    finally:
        for pth in paths:
            try:
                if pth and os.path.exists(pth): os.remove(pth)
            except Exception: pass
        with _runtime_lock:
            _processing_chats.discard(cid)


