def _fast_school_week_index(date_text, state_name=''):
    """Indeks minggu PdP 2026 berasaskan kumpulan negeri dan cuti penggal KPM."""
    try:
        dt=datetime.strptime(str(date_text),'%d/%m/%Y').date()
        if dt.year != 2026:
            first=datetime(dt.year,1,1).date()
            return max(0, ((dt-first).days)//7)
        group_a=state_name in GROUP_A_STATES
        start=datetime(2026,1,11 if group_a else 12).date()
        # Cuti penggal utama. Cuti perayaan/negeri akan menjadi lapisan kalendar berasingan.
        if group_a:
            breaks=[(datetime(2026,3,20).date(),datetime(2026,3,28).date()),
                    (datetime(2026,5,22).date(),datetime(2026,6,6).date()),
                    (datetime(2026,8,28).date(),datetime(2026,9,5).date())]
        else:
            breaks=[(datetime(2026,3,21).date(),datetime(2026,3,29).date()),
                    (datetime(2026,5,23).date(),datetime(2026,6,7).date()),
                    (datetime(2026,8,29).date(),datetime(2026,9,6).date())]
        if dt < start: return 0
        days=(dt-start).days
        for a,b in breaks:
            if dt>a:
                days-=max(0,(min(dt,b)-a).days+1)
        return max(0,days//7)
    except Exception:
        return 0

def _prepare_fast_rph_content(s):
    """Pilih fokus daripada rangka RPT setahun, kemudian padankan standard mengikut tempoh."""
    year_label=s.get('year',''); subject=s.get('subject','')
    try:
        p=_teacher_profile(s.get('_cid') or 0) if s.get('_cid') else None
    except Exception:
        p=None
    state_name=(p or {}).get('state_name') or s.get('state_name') or ''
    rpt=_rpt_rows(year_label,subject,'',state_name) or []
    if not rpt:
        return False
    wk=_fast_school_week_index(s.get('rph_date'),state_name)
    # Agihkan rangka kandungan sepanjang kira-kira 40 minggu PdP; topik boleh merentasi beberapa minggu.
    idx=min(len(rpt)-1, int((wk * len(rpt))/40)) if rpt else 0
    row=rpt[idx]
    s['rpt_week_index']=wk+1
    s['rpt_content_index']=idx
    s['topic']=row.get('topic') or 'Fokus Mingguan'
    # Keep the unit/topic itself as the visible focus. Do not expose the old
    # placeholder "Fokus Mingguan" inside the generated RPH.
    s['subtopic']=str(row.get('subtopic') or row.get('skill_focus') or '').strip()
    opts=curriculum_sk_options(s) or []
    if not opts: return False
    s['curr_sk_options']=opts
    wanted_sp=[]
    for full in row.get('sp') or []:
        code=str(full).split(' ',1)[0].strip()
        if code: wanted_sp.append(code)
    allsp=[]
    for sk in opts:
        for o in curriculum_sp_options(s,sk.get('sk_code')) or []:
            if o not in allsp: allsp.append(o)
    if not allsp: return False
    ordered=[o for o in allsp if str(o.get('sp_code') or '') in wanted_sp] or allsp
    dur=int(s.get('rph_duration_minutes') or 30)
    if _is_english_subject(s):
        main=ordered[0]
        comp=next((o for o in ordered[1:] if _bi_skill_name(o.get('sp_code')) != _bi_skill_name(main.get('sp_code'))), ordered[1] if len(ordered)>1 else ordered[0])
        s['bi_main_row']=main; s['bi_main_sp_code']=str(main.get('sp_code') or ''); s['bi_main_sp_text']=str(main.get('sp_text') or '')
        _commit_bi_standards(s,comp)
    else:
        max_sp=1 if dur<40 else (2 if dur<70 else (3 if dur<100 else 4))
        selected=ordered[:max_sp]
        s['multi_sp_options']=ordered
        s['selected_sp_codes']=[str(o.get('sp_code') or '') for o in selected]
        _commit_multi_sp(s,selected)
        # v23.84: preserve the subject-specific RPT hierarchy. SK/SP remain attached
        # as standards and must not overwrite Tema/Unit/Topic chosen from the verified RPT.
        if selected and str(selected[0].get('sk_text') or '').strip():
            s['curriculum_skill_title']=str(selected[0].get('sk_text') or '').strip()
    return True

