def callback(cid, d):
    if d == 'admin_panel':
        return _admin_panel(cid)
    if d.startswith('admin_list|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
        parts=d.split('|')
        kind=parts[1] if len(parts)>1 else 'all'
        try: page=int(parts[2]) if len(parts)>2 else 0
        except Exception: page=0
        return _admin_list(cid,kind,page)
    if d.startswith('admin_user|'):
        return _admin_user_card(cid,d.split('|',1)[1])
    if d.startswith('admin_pending|'):
        try: rid=int(d.split('|',1)[1])
        except Exception: return _admin_panel(cid)
        return _admin_pending_card(cid,rid)
    if d.startswith('admin_approve|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
        try: rid=int(d.split('|',1)[1])
        except Exception: return _admin_panel(cid)
        req=_payment_request(rid)
        if not req:
            return send(cid,'⚠️ Rekod bayaran tidak ditemui.')
        if req['status']!='pending':
            return _admin_pending_card(cid,rid)
        target=str(req['chat_id'])
        until=_activate_access(target,30,cid,'Payment RM5.00 approved from Admin Panel',payment_reference=f'payment-request:{rid}',amount_rm=5.00)
        _mark_payment_request(rid,'approved',cid,'Approved and activated 30 days')
        send(cid,f'✅ <b>BAYARAN DISAHKAN</b>\\n\\nPengguna <code>{target}</code> telah diaktifkan 30 hari sehingga <b>{until.strftime("%d/%m/%Y")}</b>.',
             [[{'text':'⏳ Pending Seterusnya','callback_data':'admin_list|pending|0'}],
              [{'text':'🛠️ Admin Panel','callback_data':'admin_panel'}]])
        try:
            send(target,f'✅ <b>CIKGULAJU TELAH DIAKTIFKAN</b>\\n\\nBayaran RM5.00 telah disahkan. Akses cikgu aktif selama <b>30 hari</b> sehingga <b>{until.strftime("%d/%m/%Y")}</b>.',
                 [[{'text':'✨ Jana Bahan','callback_data':'quick'}],[{'text':'👤 Akaun Saya','callback_data':'account'}]])
        except Exception:
            pass
        return
    if d.startswith('admin_reject|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
        try: rid=int(d.split('|',1)[1])
        except Exception: return _admin_panel(cid)
        req=_payment_request(rid)
        if not req: return send(cid,'⚠️ Rekod bayaran tidak ditemui.')
        _mark_payment_request(rid,'rejected',cid,'Rejected from Admin Panel')
        try:
            send(req['chat_id'],'❌ <b>Bayaran belum dapat disahkan.</b>\\n\\nSila semak bayaran RM5.00 dan hantar semula bukti/resit yang jelas.',
                 [[{'text':'💳 Papar QR Bayaran','callback_data':'subscribe_500'}]])
        except Exception:
            pass
        return _admin_list(cid,'pending',0)
    if d.startswith('admin_deactivate|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
        target=d.split('|',1)[1]
        _deactivate_access(target,cid,'Deactivated from Admin Panel')
        send(cid,f'🔒 Akses pengguna <code>{target}</code> telah dinyahaktifkan.',
             [[{'text':'👤 Lihat Pengguna','callback_data':f'admin_user|{target}'},
               {'text':'🛠️ Admin Panel','callback_data':'admin_panel'}]])
        try: send(target,'🔒 <b>Akses CikguLaju telah dinyahaktifkan.</b>')
        except Exception: pass
        return
    if d.startswith('admin_activate30|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Butang ini hanya boleh digunakan oleh admin CikguLaju.')
        target=d.split('|',1)[1].strip()
        if not re.fullmatch(r'-?\d+',target):
            return send(cid,'⚠️ Telegram ID pengguna tidak sah.')
        until=_activate_access(target,30,cid,'Payment RM5.00 verified by admin button',payment_reference=f'payment-request:{rid}',amount_rm=5.00)
        con=_db()
        try:
            pr=con.execute("SELECT id FROM payment_requests WHERE chat_id=? AND status='pending' ORDER BY id DESC LIMIT 1",(target,)).fetchone()
        finally:
            con.close()
        if pr: _mark_payment_request(pr['id'],'approved',cid,'Approved via quick activate button')
        send(cid,f'✅ <b>AKSES DIAKTIFKAN</b>\n\nPengguna: <code>{target}</code>\nTempoh: <b>30 hari</b>\nAktif sehingga: <b>{until.strftime("%d/%m/%Y")}</b>',
             [[{'text':'🔎 Semak Status','callback_data':f'admin_status|{target}'}]])
