# v23.104-READY-MATERIAL-STORAGE
# Additive only: existing DB files remain untouched. Future shards declare their family/tables
# in cikgulaju_shard_manifest + cikgulaju_shard_tables and are discovered automatically.
_SHARD_REGISTRY_CACHE = {}
_SHARD_ENGINE_ENABLED = os.getenv('CIKGULAJU_DB_SHARDS','1').strip().lower() not in ('0','false','no','off')
_SHARD_SAFE_IDENT = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

def _shard_qident(name):
    name=str(name or '')
    if not _SHARD_SAFE_IDENT.match(name):
        raise ValueError('Unsafe SQLite identifier: '+repr(name))
    return '"'+name+'"'

def _read_shard_manifest(path):
    """Return normalized manifest or None. Opening a shard never mutates it."""
    try:
        uri='file:'+os.path.abspath(path).replace('\\','/')+'?mode=ro'
        c=sqlite3.connect(uri, uri=True, timeout=5)
        c.row_factory=sqlite3.Row
        names={r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        if 'cikgulaju_shard_manifest' not in names:
            c.close(); return None
        r=c.execute("SELECT * FROM cikgulaju_shard_manifest WHERE enabled=1 ORDER BY sequence_no DESC LIMIT 1").fetchone()
        if not r:
            c.close(); return None
        d=dict(r)
        tabs=[]
        if 'cikgulaju_shard_tables' in names:
            for t in c.execute("SELECT * FROM cikgulaju_shard_tables WHERE enabled=1 ORDER BY table_name"):
                tabs.append(dict(t))
        c.close()
        d['tables']=tabs
        d['path']=os.path.abspath(path)
        return d
    except Exception as e:
        print('Shard manifest ignored:', os.path.basename(str(path)), repr(e), flush=True)
        return None

def _discover_db_shards(family, base_path=None):
    """Discover all enabled additive shards for a logical DB family.

    Results are cached for the life of the process. A normal redeploy/restart after uploading
    a new DB refreshes the registry automatically, so app.py does not need to change.
    """
    family=str(family or '').strip().lower()
    base_abs=os.path.abspath(base_path) if base_path else ''
    cache_key=(family, os.path.dirname(base_abs) if base_abs else os.path.dirname(os.path.abspath(__file__)))
    if cache_key in _SHARD_REGISTRY_CACHE:
        return list(_SHARD_REGISTRY_CACHE[cache_key])
    if not _SHARD_ENGINE_ENABLED:
        _SHARD_REGISTRY_CACHE[cache_key]=[]; return []
    root=cache_key[1]
    found=[]
    try:
        names=sorted(x for x in os.listdir(root) if x.lower().endswith('.db'))
    except Exception:
        names=[]
    for name in names:
        path=os.path.abspath(os.path.join(root,name))
        if base_abs and path==base_abs: continue
        m=_read_shard_manifest(path)
        if not m: continue
        if str(m.get('family') or '').strip().lower()!=family: continue
        found.append(m)
    found.sort(key=lambda x:(int(x.get('sequence_no') or 0), os.path.basename(x['path']).lower()))
    _SHARD_REGISTRY_CACHE[cache_key]=found
    return list(found)

def _table_columns(con, schema, table):
    try:
        return [str(r[1]) for r in con.execute('PRAGMA '+_shard_qident(schema)+'.table_info('+_shard_qident(table)+')')]
    except Exception:
        return []

def _create_shard_union_view(con, table, sources, merge_mode='append', key_columns=''):
    """Create a connection-local TEMP view that shadows the base table for reads only."""
    if not _SHARD_SAFE_IDENT.match(str(table or '')): return False
    valid=[]
    base_cols=None
    for schema,priority in sources:
        cols=_table_columns(con,schema,table)
        if not cols: continue
        if base_cols is None: base_cols=cols
        if cols!=base_cols:
            print('Shard table schema mismatch ignored:',table,schema,flush=True); continue
        valid.append((schema,int(priority)))
    if len(valid)<2 and not (valid and valid[0][0] != 'main'):
        return False
    qtable=_shard_qident(table)
    try: con.execute('DROP VIEW IF EXISTS temp.'+qtable)
    except Exception: pass
    mode=str(merge_mode or 'append').strip().lower()
    selects=['SELECT '+','.join(_shard_qident(c) for c in base_cols)+' FROM '+_shard_qident(sc)+'.'+qtable for sc,_ in valid]
    if mode=='distinct':
        sql=' UNION '.join(selects)
    elif mode=='overlay':
        keys=[x.strip() for x in str(key_columns or '').split(',') if x.strip()]
        if not keys or any(k not in base_cols or not _SHARD_SAFE_IDENT.match(k) for k in keys):
            print('Shard overlay missing/invalid key_columns; using append:',table,flush=True)
            sql=' UNION ALL '.join(selects)
        else:
            pieces=[]
            for sc,prio in valid:
                cols=','.join(_shard_qident(c) for c in base_cols)
                pieces.append('SELECT '+cols+','+str(int(prio))+' AS __shard_priority FROM '+_shard_qident(sc)+'.'+qtable)
            keys_sql=','.join(_shard_qident(k) for k in keys)
            cols_sql=','.join(_shard_qident(c) for c in base_cols)
            sql=('SELECT '+cols_sql+' FROM (SELECT '+cols_sql+', ROW_NUMBER() OVER (PARTITION BY '+keys_sql+
                 ' ORDER BY __shard_priority DESC) AS __rn FROM ('+' UNION ALL '.join(pieces)+')) WHERE __rn=1')
    else:
        sql=' UNION ALL '.join(selects)
    con.execute('CREATE TEMP VIEW '+qtable+' AS '+sql)
    return True

def _open_sharded_db(base_path, family, timeout=15):
    """Open a logical DB plus all manifest-driven additive shards for that family."""
    con=sqlite3.connect(base_path, timeout=timeout)
    con.row_factory=sqlite3.Row
    manifests=_discover_db_shards(family, base_path)
    attached=[]
    declarations={}
    for i,m in enumerate(manifests,1):
        alias='shard_'+str(i)
        try:
            con.execute('ATTACH DATABASE ? AS '+_shard_qident(alias),(m['path'],))
            attached.append((alias,int(m.get('priority') or m.get('sequence_no') or i),m))
            for t in m.get('tables') or []:
                tn=str(t.get('table_name') or '').strip()
                if not _SHARD_SAFE_IDENT.match(tn): continue
                declarations.setdefault(tn,[]).append((alias,int(t.get('priority') or m.get('priority') or m.get('sequence_no') or i),t))
        except Exception as e:
            print('Shard attach ignored:',os.path.basename(m.get('path','')),repr(e),flush=True)
    for tn,items in declarations.items():
        sources=[]
        # Base table participates if present.
        if _table_columns(con,'main',tn): sources.append(('main',0))
        for alias,prio,t in items:
            if _table_columns(con,alias,tn): sources.append((alias,prio))
        if not sources: continue
        # Highest-priority declaration determines merge policy.
        chosen=sorted(items,key=lambda x:x[1],reverse=True)[0][2]
        try:
            _create_shard_union_view(con,tn,sources,chosen.get('merge_mode','append'),chosen.get('key_columns',''))
        except Exception as e:
            print('Shard union view ignored:',tn,repr(e),flush=True)
    return con

def _db_shard_status():
    """Small diagnostic snapshot for logs/admin QA; no DB contents are exposed."""
    families={
      'curriculum': DB_PATH,
      'worksheet_content': globals().get('WORKSHEET_CONTENT_DB_PATH',''),
      'visuals': globals().get('VISUAL_DB_PATH',''),
      'header_footer_primary': globals().get('HF_PRIMARY_DB',''),
      'header_footer_secondary': globals().get('HF_SECONDARY_DB',''),
    }
    out={}
    for fam,bp in families.items():
        if bp: out[fam]=[os.path.basename(x['path']) for x in _discover_db_shards(fam,bp)]
    return out

