def _bbm_assets_for_state(s):
    con=_db()
    try:
        topic=str(s.get('topic','')).strip()
        row=con.execute('SELECT vocabulary,asset_keys,preferred_templates FROM bbm_topic_mapping WHERE year_label=? AND subject=? AND topic=? LIMIT 1',(s.get('year',''),s.get('subject',''),topic)).fetchone()
        if not row and '—' in topic:
            clean=topic.split('—',1)[1].strip()
            row=con.execute('SELECT vocabulary,asset_keys,preferred_templates FROM bbm_topic_mapping WHERE year_label=? AND subject=? AND topic=? LIMIT 1',(s.get('year',''),s.get('subject',''),clean)).fetchone()
        if not row: return []
        keys=[x.strip() for x in str(row['asset_keys']).split(',') if x.strip()]
        if not keys: return []
        q=','.join('?'*len(keys))
        rows=con.execute(f'SELECT asset_key,label,svg_source FROM bbm_illustrations WHERE asset_key IN ({q})',keys).fetchall()
        by={r['asset_key']:dict(r) for r in rows}
        return [by[k] for k in keys if k in by]
    finally:
        con.close()




# v23.79 — dual-palette visual policy. Semantic mapping is shared; only render palette changes.
def _shared_visual_palette_v2379(surface='bbm', color_required=False):
    if color_required:
        return 'color'
    return 'black_white' if str(surface).lower()=='worksheet' else 'color'

def _shared_visual_render_key_v2379(asset_key, surface='bbm', color_required=False):
    palette=_shared_visual_palette_v2379(surface,color_required)
    suffix='__COLOR' if palette=='color' else '__BW'
    return str(asset_key)+suffix

# v23.78 — Shared Semantic Visual Asset Engine
def _shared_visual_assets_for_state(s, limit=9):
    """v23.81 additive-shard semantic lookup.

    Works directly from v23.76 without modifying/replacing any existing DB.
    New visual shards carry their own concepts, lexicon and semantic terms.
    """
    year=str(s.get('year') or s.get('year_label') or '').strip()
    subject=str(s.get('subject') or '').strip()
    topic=str(s.get('topic') or '').strip()
    sp_text=str(s.get('sp_text') or s.get('learning_standard') or '').strip()
    is_en=subject.lower() in ('bahasa inggeris','english')
    lang='en' if is_en else 'ms'
    search=(topic+' '+sp_text).lower()
    # Preserve meaningful curriculum terms; drop generic function words.
    stop={'the','and','with','for','from','that','this','range','support','a','an','of','to','in','on',
          'dan','dengan','untuk','daripada','yang','ini','itu','secara','pada','kepada','murid'}
    tokens=[x for x in re.findall(r"[a-zA-ZÀ-ÿ0-9]+",search) if len(x)>=2 and x not in stop]
    # Add subject-domain anchors, but at lower semantic importance.
    if subject=='Matematik': tokens += ['math']
    elif subject=='Sains': tokens += ['science']
    elif is_en: tokens += ['language']
    elif subject=='Bahasa Melayu': tokens += ['language']
    # Topic aliases common in primary curriculum.
    aliases={
        'free time':['free','time','play','sport','read','music'],
        'masa lapang':['free','time','play','sport','read'],
        'food':['food','fruit','vegetable','drink'],
        'makanan':['food','fruit','vegetable','drink'],
        'animals':['animal'], 'haiwan':['animal'],
        'weather':['weather'], 'cuaca':['weather'],
        'transport':['transport'], 'pengangkutan':['transport'],
        'school':['school'], 'sekolah':['school'],
        'home':['home'], 'rumah':['home'],
        'body':['body'], 'anggota badan':['body'],
    }
    lowtopic=topic.lower()
    for k,vals in aliases.items():
        if k in lowtopic: tokens += vals

    scored={}
    for path in _visual_db_paths_v2380()[1:]:
        try:
            con=sqlite3.connect(path,timeout=10); con.row_factory=sqlite3.Row
            # Ignore legacy/additive shards that do not contain the production semantic schema.
            names={r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if not {'visual_concepts','visual_assets','visual_subject_lexicon'}.issubset(names):
                con.close(); continue
            concepts=con.execute("SELECT concept_key,category,bm_label,en_label,semantic_tags FROM visual_concepts WHERE approved=1").fetchall()
            term_rows={}
            if 'visual_semantic_terms' in names:
                for r in con.execute("SELECT concept_key,term,language_code,weight FROM visual_semantic_terms"):
                    term_rows.setdefault(r['concept_key'],[]).append((str(r['term']).lower(),r['language_code'],float(r['weight'])))
            lex={}
            for r in con.execute("""SELECT concept_key,display_label FROM visual_subject_lexicon
                                    WHERE approved=1 AND subject=? AND language_code IN (?, 'neutral')""",(subject,lang)):
                lex.setdefault(r['concept_key'],r['display_label'])
            for r in concepts:
                ck=r['concept_key']
                label=lex.get(ck) or (r['en_label'] if is_en else r['bm_label'])
                tags=str(r['semantic_tags'] or '').lower()
                score=0.0
                for tok in set(tokens):
                    if tok in tags: score += 1.2
                    if tok in str(label).lower(): score += 3.5
                    for term,tlang,w in term_rows.get(ck,()):
                        if tok==term and (tlang in (lang,'neutral')): score += w
                # Domain boost prevents unrelated but lexically similar concepts.
                if subject=='Matematik' and 'math' in tags: score += 2.0
                if subject=='Sains' and 'science' in tags: score += 2.0
                if score>0:
                    old=scored.get(ck)
                    item={'asset_key':ck,'concept_key':ck,'label':label,'score':score,'variant_no':1}
                    if old is None or score>old['score']: scored[ck]=item
            con.close()
        except Exception:
            try: con.close()
            except Exception: pass

    out=sorted(scored.values(), key=lambda x:(-x['score'],x['concept_key']))
    # Diversity: avoid nine cards from one narrow family when topic is broad.
    return out[:int(limit)]

def _bbm_curriculum_rows_for_state(s, limit=6):
    """Return actual curriculum-mapped BBM rows for the selected verified SP/topic."""
    subject=str(s.get('subject') or '').strip()
    year=str(s.get('year') or s.get('year_label') or '').strip()
    topic=str(s.get('topic') or '').strip()
    sp_code=str(s.get('sp_code') or '').strip()
    sp_text=str(s.get('sp_text') or s.get('learning_standard') or '').strip()
    if not subject:
        return []
    con=_db()
    try:
        params=[subject]
        where=["cs.subject=?","cs.verified=1","m.verified=1","b.verified=1","b.active=1"]
        if year:
            where.append("cs.year_label=?"); params.append(year)
        if sp_code:
            where.append("cs.sp_code=?"); params.append(sp_code)
        elif topic:
            where.append("cs.topic=?"); params.append(topic)
        sql=("SELECT b.id,b.category,b.focus_keywords,b.bbm_name,b.usage_example,b.resource_type,"
             "MAX(m.match_score) map_score "
             "FROM rph_bbm_curriculum_map m "
             "JOIN curriculum_standards cs ON cs.id=m.curriculum_standard_id "
             "JOIN rph_bbm_variants b ON b.id=m.bbm_variant_id "
             "WHERE "+' AND '.join(where)+
             " GROUP BY b.id ORDER BY map_score DESC,b.id ASC LIMIT 24")
        rows=con.execute(sql,params).fetchall()
        # v23.76 curriculum lock: BBM must remain tied to the selected verified SP.
        # Never fall back to a generic subject bank; that could produce age-appropriate
        # looking material that does not actually teach the chosen SK/SP.
        if sp_code and not rows:
            return []
        # Legacy/non-SP entry points may use an exact verified topic/year mapping only.
        if not rows and topic and not sp_code:
            rows=con.execute(
                """SELECT b.id,b.category,b.focus_keywords,b.bbm_name,b.usage_example,b.resource_type,
                          MAX(m.match_score) map_score
                   FROM rph_bbm_curriculum_map m
                   JOIN curriculum_standards cs ON cs.id=m.curriculum_standard_id
                   JOIN rph_bbm_variants b ON b.id=m.bbm_variant_id
                   WHERE cs.subject=? AND cs.year_label=? AND cs.topic=?
                     AND cs.verified=1 AND m.verified=1 AND b.verified=1 AND b.active=1
                   GROUP BY b.id ORDER BY map_score DESC,b.id ASC LIMIT 24""",
                (subject,year,topic)).fetchall()
    finally:
        con.close()

    focus=' '.join([topic,sp_text]).lower()
    scored=[]
    for r in rows:
        kws=[x.strip().lower() for x in re.split(r'[,|;/]+',str(r['focus_keywords'] or '')) if x.strip()]
        lexical=sum(3 for k in kws if k in focus)
        cat=str(r['category'] or '').lower()
        if cat and cat in focus: lexical+=2
        scored.append((float(r['map_score'] or 0)+lexical,r))
    scored.sort(key=lambda x:x[0],reverse=True)

    # v23.76 quality/diversity: mapped quality cards score highest, but repeated BBM
    # generation for the same verified SP rotates among similarly strong candidates.
    # This stays deterministic per variation_seed and never crosses the selected SP.
    import random as _bbm_random
    _seed=str(s.get('bbm_variation_seed') or s.get('variation_seed') or '0')
    _rng=_bbm_random.Random(_seed+'|'+subject+'|'+year+'|'+sp_code+'|'+topic)
    buckets={}
    for sc,r in scored:
        buckets.setdefault(round(float(sc),1),[]).append((sc,r))
    scored=[]
    for k in sorted(buckets, reverse=True):
        grp=buckets[k]
        _rng.shuffle(grp)
        scored.extend(grp)

    selected=[]; seen=set()
    for _,r in scored:
        base=re.sub(r'\s*\+\s*(kad arahan ringkas|lembaran rekod|kad semak rakan)$','',
                    str(r['bbm_name'] or ''),flags=re.I).strip().lower()
        if base in seen: continue
        seen.add(base); selected.append(dict(r))
        if len(selected)>=max(3,min(int(limit or 6),6)): break
    # If only related variants are available, fill to at least 3 where possible.
    if len(selected)<3:
        chosen={r['id'] for r in selected}
        for _,r in scored:
            if r['id'] in chosen: continue
            selected.append(dict(r)); chosen.add(r['id'])
            if len(selected)>=3: break
    return selected


def create_bbm_flashcards_pdf(s, cid):
    """v23.81 BBM visual-production engine.

    - exact verified SP remains the curriculum lock;
    - BBM uses COLOR production assets from additive visual shards;
    - English BBM is English-only;
    - Stage 1 is visual/low-text and directly printable;
    - no runtime AI/API.
    """
    rows=_bbm_curriculum_rows_for_state(s,6)
    if not rows:
        raise RuntimeError('Tiada BBM curriculum-mapped untuk SP/tajuk ini.')

    from reportlab.pdfgen import canvas
    from reportlab.lib.pagesizes import A4
    from reportlab.pdfbase.pdfmetrics import stringWidth
    from reportlab.lib.utils import ImageReader
    from io import BytesIO

    subject=str(s.get('subject') or '').strip()
    year=str(s.get('year') or s.get('year_label') or '').strip()
    topic=str(s.get('topic') or '').strip()
    sp_code=str(s.get('sp_code') or '').strip()
    sp_text=str(s.get('sp_text') or s.get('learning_standard') or '').strip()
    is_en=subject.lower() in ('bahasa inggeris','english')
    is_stage1=year in ('Tahun 1','Tahun 2','Tahun 3')

    path=os.path.join(tempfile.gettempdir(),f'cikgulaju_bbm_{cid}_{int(time.time())}.pdf')
    c=canvas.Canvas(path,pagesize=A4); W,H=A4; margin=28

    def wrap(text,font,size,maxw):
        out=[]; line=''
        for w in str(text or '').split():
            t=(line+' '+w).strip()
            if stringWidth(t,font,size)<=maxw: line=t
            else:
                if line: out.append(line)
                line=w
        if line: out.append(line)
        return out

    def text_lines(text,x,y,maxw,size=9,bold=False,max_lines=6,leading=None):
        font='Helvetica-Bold' if bold else 'Helvetica'; leading=leading or size*1.25
        c.setFont(font,size)
        for ln in wrap(text,font,size,maxw)[:max_lines]:
            c.drawString(x,y,ln); y-=leading
        return y

    def head(title):
        c.setFont('Helvetica-Bold',14); c.drawString(margin,H-22,title)
        c.setFont('Helvetica',8.2)
        c.drawString(margin,H-35,(f'{subject} • {year} • {topic} • SP {sp_code}')[:110])

    def foot(label):
        c.setFont('Helvetica',7)
        c.drawString(margin,12,'Cut on the dashed lines.' if is_en else 'Potong pada garisan putus-putus.')
        c.drawRightString(W-margin,12,label)

    def card(x,y,w,h):
        c.setDash(3,2); c.rect(x,y,w,h); c.setDash()

    def draw_fallback(kind,cx,cy,scale=1.0):
        """Small local fallback only if no production shard asset exists."""
        k=str(kind or '').lower()
        c.setLineWidth(1.5)
        if 'ball' in k:
            c.circle(cx,cy,24*scale); c.arc(cx-18*scale,cy-24*scale,cx+18*scale,cy+24*scale,65,50)
        elif 'read' in k or 'book' in k:
            c.rect(cx-32*scale,cy-22*scale,30*scale,44*scale); c.rect(cx+2*scale,cy-22*scale,30*scale,44*scale)
        elif 'run' in k:
            c.circle(cx,cy+25*scale,7*scale); c.line(cx,cy+18*scale,cx-4*scale,cy-5*scale)
            c.line(cx-4*scale,cy+8*scale,cx-22*scale,cy); c.line(cx-4*scale,cy-5*scale,cx+20*scale,cy-20*scale)
        else:
            c.circle(cx,cy,24*scale); c.line(cx-20*scale,cy-25*scale,cx+20*scale,cy-25*scale)

    def draw_asset(item,cx,cy,maxw,maxh,variant=1):
        ck=str(item.get('concept_key') or item.get('asset_key') or '')
        if ck:
            a=_production_visual_asset_v2380(ck,'bbm',variant,False)
            if a and a.get('image_blob'):
                try:
                    ir=ImageReader(BytesIO(a['image_blob']))
                    iw,ih=ir.getSize()
                    scale=min(maxw/float(iw),maxh/float(ih))
                    dw,dh=iw*scale,ih*scale
                    c.drawImage(ir,cx-dw/2,cy-dh/2,dw,dh,mask='auto',preserveAspectRatio=True)
                    return True
                except Exception:
                    pass
        # v23.83 quality lock: never substitute primitive icon/symbol art.
        # A missing approved cartoon/line-art asset stays blank and is excluded upstream.
        return False

    assets=[]
    try:
        assets=_shared_visual_assets_for_state(s,12) or []
    except Exception:
        assets=[]
    # v23.83: BBM/worksheet visual quality gate. Do not use legacy symbol/icon assets.
    approved_assets=[]
    for _it in assets:
        _ck=str(_it.get('concept_key') or _it.get('asset_key') or '')
        if _ck and _production_visual_asset_v2380(_ck,'bbm',int(_it.get('variant_no') or 1),False):
            approved_assets.append(_it)
    assets=approved_assets

    # v23.83: no icon/symbol fallback. If quality artwork is unavailable, fail safely.
    focus=(topic+' '+sp_text).lower()
    phonics=is_en and any(k in focus for k in ('phoneme','sound','pronunciation','reproduce'))

    # PAGE 1 — actual BBM cards, not suggestions.
    head('CikguLaju BBM • Teaching Picture & Word Cards' if is_en else 'CikguLaju BBM • Kad Pengajaran Gambar & Perkataan')
    if assets:
        gap=7; cw=(W-2*margin-2*gap)/3; ch=170
        for i,item in enumerate(assets[:9]):
            rr=i//3; col=i%3; x=margin+col*(cw+gap); y=H-48-(rr+1)*ch-rr*gap
            card(x,y,cw,ch)
            draw_asset(item,x+cw/2,y+98,cw-10,124,1)
            label=str(item.get('label') or item.get('concept_key') or '').strip()
            c.setFont('Helvetica-Bold',15 if is_stage1 else 12)
            c.drawCentredString(x+cw/2,y+18,label[:24])
        foot('CikguLaju • colour BBM • original local asset bank' if not is_en else
             'CikguLaju • colour BBM • original local asset bank')
        c.showPage()
    else:
        # Higher-level SP can legitimately use text/evidence cards, but they must be usable material.
        gap=10; cw=(W-2*margin-gap)/2; ch=220
        for i,r in enumerate(rows[:6]):
            rr=i//2; col=i%2; x=margin+col*(cw+gap); y=H-55-(rr+1)*ch-rr*gap
            card(x,y,cw,ch)
            title=str(r.get('bbm_name') or ('Task Card' if is_en else 'Kad Tugasan'))
            text_lines(title,x+10,y+ch-22,cw-20,10,True,3,12)
            c.setFont('Helvetica-Bold',8); c.drawString(x+10,y+ch-66,'EVIDENCE / RESPONSE' if is_en else 'BUKTI / RESPONS')
            yy=y+ch-84
            for _ in range(6): c.line(x+10,yy,x+cw-10,yy); yy-=22
        foot('CikguLaju • curriculum-mapped task cards'); c.showPage()

    # PAGE 2 — skill-specific manipulation.
    if phonics:
        head('CikguLaju BBM • Listen • Match • Say')
        c.setFont('Helvetica-Bold',10.5)
        c.drawString(margin,H-58,'Teacher says the target sound. Pupils listen, point, decide, then say the word.')
        # Verified local curriculum mapping for Year 2 Unit 5 Free Time lesson: /u/.
        _target_sound='/u/' if (year=='Tahun 2' and 'free time' in topic.lower() and sp_code=='1.1.1') else ''
        c.setFont('Helvetica-Bold',10); c.drawString(margin,H-82,'TARGET SOUND')
        c.rect(margin,H-150,110,52); c.setFont('Helvetica-Bold',24)
        c.drawCentredString(margin+55,H-132,_target_sound if _target_sound else 'CHECK SOW')
        if not _target_sound:
            c.setFont('Helvetica',7.5); c.drawString(margin+125,H-126,'Use only after the lesson target phoneme is verified.')
        y0=H-188; cw=(W-2*margin-10)/2; ch=118
        for i,item in enumerate(assets[:6]):
            rr=i//2; col=i%2; x=margin+col*(cw+10); y=y0-(rr+1)*ch-rr*8
            card(x,y,cw,ch)
            draw_asset(item,x+62,y+62,112,100,1)
            label=str(item.get('label') or '').strip()
            c.setFont('Helvetica-Bold',13); c.drawString(x+105,y+70,label[:18])
            c.setFont('Helvetica',9); c.drawString(x+105,y+48,'Listen and decide: YES / NO')
            c.circle(x+126,y+26,7); c.drawString(x+138,y+23,'YES')
            c.circle(x+198,y+26,7); c.drawString(x+210,y+23,'NO')
        foot('CikguLaju • English-only phonics material'); c.showPage()
    else:
        head('CikguLaju BBM • Activity Cards' if is_en else 'CikguLaju BBM • Kad Aktiviti')
        gap=10; cw=(W-2*margin-gap)/2; ch=220
        verbs=(['MATCH','SORT','ORDER','EXPLAIN','CHECK','APPLY'] if is_en else
               ['PADANKAN','KELASKAN','SUSUN','TERANGKAN','SEMAK','APLIKASI'])
        for i,r in enumerate(rows[:6]):
            rr=i//2; col=i%2; x=margin+col*(cw+gap); y=H-55-(rr+1)*ch-rr*gap
            card(x,y,cw,ch)
            text_lines(verbs[i%len(verbs)],x+10,y+ch-22,cw-20,11,True,1,12)
            nm=str(r.get('bbm_name') or '')
            text_lines(nm,x+10,y+ch-50,cw-20,9,True,3,11)
            prompt=('Use the visual cards to complete the task for this learning standard.' if is_en else
                    'Gunakan kad visual untuk melengkapkan tugasan bagi Standard Pembelajaran ini.')
            text_lines(prompt,x+10,y+ch-95,cw-20,8.5,False,4,11)
            yy=y+72
            c.setFont('Helvetica-Bold',8); c.drawString(x+10,yy+18,'MY ANSWER' if is_en else 'JAWAPAN SAYA')
            for _ in range(3): c.line(x+10,yy,x+cw-10,yy); yy-=18
        foot('CikguLaju • print, cut & use'); c.showPage()

    # PAGE 3 — explicit, material-specific teacher instructions.
    head('CikguLaju BBM • How to Use This Material' if is_en else 'CikguLaju BBM • Cara Menggunakan Bahan Ini')
    if is_en:
        sections=[
          ('PREPARATION','Print in colour on A4 paper. Cut the cards along the dashed lines. Keep the picture-and-word cards together for teaching.'),
          ('TEACHER ACTION','Show one card at a time. Say the target word clearly. For phonics, model the verified target sound first, then say the word naturally.'),
          ('PUPIL ACTION','Look, listen and repeat. Next, point to or hold up the correct picture when the teacher says a word or target sound.'),
          ('MATCHING / ASSESSMENT RULE','When assessing picture-to-word matching, use picture-only cards and separate word cards. Never show the answer word on the picture being tested.'),
          ('ACTIVITY VARIATION','Shuffle the cards. Ask pupils to sort by sound or activity, play Find the Card, or work in pairs to say and identify cards.'),
          ('SUCCESS CRITERIA','Pupil recognises the target sound, identifies the correct picture, reproduces the sound, and says the target word with decreasing support.')
        ]
    else:
        sections=[
          ('PERSEDIAAN','Cetak berwarna pada kertas A4. Potong kad mengikut garisan putus-putus. Gunakan kad gambar dan perkataan bersama untuk pengajaran.'),
          ('TINDAKAN GURU','Tunjukkan satu kad pada satu masa dan sebut perkataan sasaran dengan jelas. Beri satu contoh sebelum murid mencuba.'),
          ('TINDAKAN MURID','Lihat, dengar dan sebut semula. Kemudian tunjuk atau angkat gambar yang betul apabila guru menyebut perkataan.'),
          ('PERATURAN PADANAN / PENTAKSIRAN','Untuk aktiviti padanan gambar-perkataan, gunakan kad gambar tanpa label dan kad perkataan berasingan. Jangan paparkan jawapan pada gambar.'),
          ('VARIASI AKTIVITI','Kocok kad, buat aktiviti Cari Kad, pengelasan, padanan atau aktiviti berpasangan mengikut kemahiran SP.'),
          ('KRITERIA KEJAYAAN','Murid mengenal pasti visual sasaran dan memberi respons yang betul dengan semakin kurang bimbingan.')
        ]
    yy=H-62
    for title,body in sections:
        c.setFont('Helvetica-Bold',9.5); c.drawString(margin,yy,title); yy-=14
        yy=text_lines(body,margin,yy,W-2*margin,8.6,False,4,11)-9
    c.setFont('Helvetica-Bold',9); c.drawString(margin,yy,'LEARNING STANDARD' if is_en else 'STANDARD PEMBELAJARAN'); yy-=14
    text_lines(sp_text,margin,yy,W-2*margin,8.5,False,4,11)
    foot('CikguLaju • explicit-use guide • database/local only'); c.showPage()
    c.save()
    return path

def seed_topic_database():
    con = _db()
    try:
        rows=[]
        for year_label, subjects_map in TOPICS.items():
            for subject, topics in subjects_map.items():
                for topic in topics:
                    subs = get_subtopics(year_label, subject, topic) or ['']
                    for subtopic in subs:
                        rows.append((year_label, subject, topic, subtopic))
        con.executemany("INSERT OR IGNORE INTO curriculum_topics(year_label,subject,topic,subtopic) VALUES(?,?,?,?)", rows)
        con.commit()
    finally:
        con.close()


