        row=con.execute("""
            SELECT * FROM curriculum_pedagogy
            WHERE year_label=? AND subject=? AND sk_code=? AND sp_code=?
              AND verified_alignment=1
            LIMIT 1
        """,(s.get('year',''),s.get('subject',''),s.get('sk_code',''),s.get('sp_code',''))).fetchone()
