def _apply_smart_sp_grouping(s):
    """Group related SPs according to the actual lesson duration."""
    primary_code=str(s.get('sp_code') or '').strip()
    primary_text=str(s.get('sp_text') or '').strip()
    s['grouped_sp_codes']=[primary_code] if primary_code else []
    s['grouped_sp_texts']=[primary_text] if primary_text else []
    minutes=int(s.get('rph_duration_minutes') or 30)
    # Short lessons stay focused. Medium lessons may carry 2 SPs; longer lessons up to 3.
    max_sp = 1 if minutes < 40 else (2 if minutes < 55 else 3)
    if max_sp <= 1 or not primary_code:
        return s
    opts=s.get('rph_sp_options') or []
    pos=next((i for i,o in enumerate(opts) if str(o.get('sp_code'))==primary_code), -1)
    if pos >= 0:
        for o in opts[pos+1:]:
            if len(s['grouped_sp_codes']) >= max_sp: break
            if str(o.get('sk_code') or '') != str(s.get('sk_code') or ''): continue
            code=str(o.get('sp_code') or '').strip(); text=str(o.get('sp_text') or '').strip()
            if code and code not in s['grouped_sp_codes']:
                s['grouped_sp_codes'].append(code); s['grouped_sp_texts'].append(text)
    return s

def _rph_sk_display(s):
    codes=s.get('grouped_sk_codes') or s.get('selected_sk_codes') or []
    texts=s.get('grouped_sk_texts') or []
    if codes:
        return '\n'.join(f'{c} {texts[i] if i < len(texts) else ""}'.strip() for i,c in enumerate(codes))
    return f"{s.get('sk_code','')} {s.get('sk_text','')}".strip()

def _rph_sp_display(s):
    if _is_english_subject(s) and s.get('bi_main_row'):
        m=s.get('bi_main_row') or {}; c=s.get('bi_comp_row') or {}
        return (f"Main Skill — {_bi_skill_name(m.get('sp_code'))}: {m.get('sp_code','')} {m.get('sp_text','')} | "
                f"Complementary Skill — {_bi_skill_name(c.get('sp_code'))}: {c.get('sp_code','')} {c.get('sp_text','')}")
    codes=s.get('grouped_sp_codes') or [s.get('sp_code','')]
    texts=s.get('grouped_sp_texts') or [s.get('sp_text','')]
    return '\n'.join(f'{c} {t}'.strip() for c,t in zip(codes,texts) if c or t)

def _class_level_number(s):
    """Extract selected Year/Form number for class-example and soft validation."""
    y=str(s.get('year') or '').strip()
    m=re.search(r'\b([1-6])\b', y)
    return int(m.group(1)) if m else None

def _dynamic_class_example(s):
    n=_class_level_number(s)
    names=['Bestari','Mutiara','Cemerlang','Amanah','Intan','Gemilang']
    # Stable per session so prompt does not unexpectedly change while teacher is entering data.
    seed=str(s.get('year') or '')+'|'+str(s.get('subject') or '')+'|'+str(s.get('rph_date') or '')
    name=names[sum(ord(c) for c in seed) % len(names)]
    return f'{n} {name}' if n else name

def _class_number_mismatch(s, value):
    expected=_class_level_number(s)
    if not expected: return False
    m=re.match(r'^\s*([1-6])(?:\s|$)', str(value or ''))
    return bool(m and int(m.group(1)) != expected)

def _prompt_rph_class(cid, s, prefix=''):
    ex=_dynamic_class_example(s)
    class_rows=_profile_class_records(cid)
    classes=[r['name'] for r in class_rows]
    msg=(prefix+'\n\n' if prefix else '')+'🏫 <b>Pilih atau masukkan kelas</b>'
    kb=[]
    for i,row in enumerate(class_rows[:12]):
        label='🏫 '+row['name']
        if row.get('students'):
            label+=f" • {row['students']} murid"
        kb.append([{'text':label,'callback_data':f'rphclass_profile_{i}'}])
    kb.append([{'text':'✍️ Tulis Nama Kelas Manual','callback_data':'rphclass_manual'}])
    if not classes:
        msg+=f'\nTiada kelas disimpan dalam profil. Cikgu boleh taip manual.\nContoh: <code>{html.escape(ex)}</code>'
    else:
        msg+='\nPilih kelas daripada profil, atau tulis nama kelas manual jika kelas yang diperlukan belum disimpan.'
    send(cid,msg,kb)

def _rph_session_question(cid):
    # Tarikh dan masa sudah dipilih melalui picker; hanya maklumat kelas/murid perlu dilengkapkan.
    s=state.setdefault(cid,{})
    dur=int(s.get('rph_duration_minutes') or 0)
    send(cid,f'🗓️ <b>Maklumat sesi PdP</b>\n\n📅 {html.escape(str(s.get("rph_date") or "-"))} ({html.escape(str(s.get("rph_day") or "-"))})\n⏰ {html.escape(str(s.get("rph_time") or "-"))}\n⏱️ Tempoh dikesan: <b>{dur} minit</b>\n\nLengkapkan kelas dan bilangan murid?',[[{'text':'✍️ Isi Kelas & Murid','callback_data':'rphsession_fill'},{'text':'⏭️ Biarkan Kosong','callback_data':'rphsession_blank'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])

def _rph_date_picker(cid, offset=0):
    from datetime import date, timedelta
    s=state.setdefault(cid,{})
    base=date.today()+timedelta(days=offset)
    kb=[]
    for r in range(0,7,2):
        row=[]
        for j in range(2):
            i=r+j
            if i>=7: break
            d=base+timedelta(days=i)
            
            if _is_english_subject(s): label=d.strftime('%a %d/%m')
            else:
                _ms=['Isn','Sel','Rab','Kha','Jum','Sab','Ahd']; label=f'{_ms[d.weekday()]} {d.strftime("%d/%m")}'
            row.append({'text':label,'callback_data':'rphdate|'+d.strftime('%Y%m%d')})
        kb.append(row)
    kb.append([{'text':'⬅️ 7 hari','callback_data':f'rphdatepage|{offset-7}'},{'text':'7 hari ➡️','callback_data':f'rphdatepage|{offset+7}'}])
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    send(cid,'📅 <b>Pilih tarikh RPH</b>\n\nTekan tarikh — tidak perlu menaip.',kb)

def _rph_time_picker(cid, mode='start', page=0):
    # 5-minute increments; 3-hour pages keep the Telegram keyboard compact.
    start_min=max(0,min(23*60+55,int(page)*180))
    end_min=min(24*60,start_min+180)
    kb=[]; row=[]
    for m in range(start_min,end_min,10):
        hh=m//60; mm=m%60
        label=f'{hh:02d}:{mm:02d}'
        row.append({'text':label,'callback_data':f'rphtime|{mode}|{m}'})
        if len(row)==3: kb.append(row); row=[]
    if row: kb.append(row)
    nav=[]
    if start_min>0: nav.append({'text':'⬅️ Awal','callback_data':f'rphtimepage|{mode}|{max(0,page-1)}'})
    if end_min<24*60: nav.append({'text':'Lewat ➡️','callback_data':f'rphtimepage|{mode}|{page+1}'})
    if nav: kb.append(nav)
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    title='masa mula' if mode=='start' else 'masa tamat'
    send(cid,f'⏰ <b>Pilih {title} PdP</b>\n\nPilih terus daripada butang masa.',kb)

def start_rph_session(cid):
    # v23.62: personal timetable first when available; manual date/time remains fallback.
    s=state.setdefault(cid,{})
    for k in ('rph_date','rph_day','rph_start_minutes','rph_end_minutes','rph_time','rph_duration_minutes','rph_periods'):
        s.pop(k,None)
    if globals().get('_timetable_entries') and _timetable_entries(cid):
        return _timetable_pick_for_rph(cid)
    _rph_date_picker(cid,0)

