def _upsert_user(user, cid=None):
    """Simpan profil Telegram dan pulangkan True hanya jika pengguna benar-benar baharu."""
    if not user and cid is None:
        return False
    chat_id=str(cid if cid is not None else (user or {}).get('id','')).strip()
    if not chat_id:
        return False
    user=user or {}
    # Telegram ID ialah identiti kanonik. Nama/username hanya metadata paparan dan TIDAK unik.
    # Semak stor persistent dahulu supaya penggantian SQLite ketika deploy tidak menyebabkan
    # pengguna lama dianggap sebagai pengguna baharu.
    persistent_exists=False
    try:
        uid_int=int(chat_id)
        p_rows=_sb_request('GET',f'teacher_profiles?telegram_user_id=eq.{uid_int}&select=telegram_user_id') or []
        u_rows=_sb_request('GET',f'cikgulaju_users?telegram_user_id=eq.{uid_int}&select=telegram_user_id') or []
        persistent_exists=bool(p_rows or u_rows)
    except Exception as e:
        print('persistent identity existence check:',repr(e),flush=True)

    con=_db(); is_new=False
    try:
        existed=con.execute('SELECT 1 FROM bot_users WHERE chat_id=? LIMIT 1',(chat_id,)).fetchone()
        is_new = (existed is None) and (not persistent_exists)
        con.execute("""
          INSERT INTO bot_users(chat_id,username,first_name,last_name,last_seen)
          VALUES(?,?,?,?,CURRENT_TIMESTAMP)
          ON CONFLICT(chat_id) DO UPDATE SET
            username=excluded.username,
            first_name=excluded.first_name,
            last_name=excluded.last_name,
            last_seen=CURRENT_TIMESTAMP
        """,(chat_id,str(user.get('username') or ''),str(user.get('first_name') or ''),
             str(user.get('last_name') or '')))
        con.commit()
    finally:
        con.close()
    # Simpan identiti asas secara kekal di Supabase. Jangan timpa display_name yang cikgu pilih sendiri.
    try:
        rows=_sb_request('GET',f'teacher_profiles?telegram_user_id=eq.{int(chat_id)}&select=telegram_user_id,display_name') or []
        tg_name=(' '.join(x for x in (str(user.get('first_name') or '').strip(),str(user.get('last_name') or '').strip()) if x).strip())
        if not rows:
            payload={'telegram_user_id':int(chat_id),'display_name':tg_name or None,'updated_at':datetime.now(timezone.utc).isoformat()}
            _sb_request('POST','teacher_profiles',json=payload,prefer='return=minimal')
        elif tg_name and not str(rows[0].get('display_name') or '').strip():
            _sb_request('PATCH',f'teacher_profiles?telegram_user_id=eq.{int(chat_id)}',json={'display_name':tg_name,'updated_at':datetime.now(timezone.utc).isoformat()},prefer='return=minimal')
    except Exception as e:
        print('persistent user identity:',repr(e),flush=True)
    if is_new:
        _notify_admin_new_user(chat_id,user)
    return is_new

def _new_payment_request(chat_id, message_id=None, amount=5.00):
    _ensure_access_schema()
    con=_db()
    try:
        # Elakkan banyak rekod pending untuk screenshot/resit yang sama dihantar berulang.
        row=con.execute("""SELECT id FROM payment_requests
                           WHERE chat_id=? AND status='pending'
                           ORDER BY id DESC LIMIT 1""",(str(chat_id),)).fetchone()
        if row:
            return int(row['id'])
        cur=con.execute("""INSERT INTO payment_requests(chat_id,amount,telegram_message_id,status)
                           VALUES(?,?,?,'pending')""",
                        (str(chat_id),float(amount),message_id))
        con.commit()
        return int(cur.lastrowid)
    finally:
        con.close()


