def _new_donation_receipt(chat_id, message_id=None):
    """Rekod lokal + audit persistent Supabase. Resit fizikal kekal di Telegram; audit tidak hilang bila DB deploy."""
    _ensure_access_schema()
    import uuid
    token='donation:'+uuid.uuid4().hex
    con=_db()
    try:
        cur=con.execute("""INSERT INTO donation_receipts(chat_id,telegram_message_id,status,receipt_token)
                           VALUES(?,?,'received',?)""",(str(chat_id),message_id,token))
        con.commit(); rid=int(cur.lastrowid)
    finally: con.close()
    # Gunakan ledger Supabase sedia ada sebagai audit trail persistent; tidak perlu schema Supabase baharu.
    try:
        bal=_ensure_user_credit(chat_id)
        _sb_request('POST','credit_ledger',json={
            'telegram_user_id':int(chat_id),'amount':0,'transaction_type':'donation_receipt',
            'description':'Resit sumbangan diterima dan direkod oleh admin',
            'reference_id':token,'balance_after':int(bal)
        },prefer='return=minimal')
    except Exception as e:
        print('Persistent donation receipt audit warning:',repr(e),flush=True)
    return rid

def _donation_receipt(receipt_id):
    _ensure_access_schema(); con=_db()
    try:
        r=con.execute("SELECT * FROM donation_receipts WHERE id=?",(int(receipt_id),)).fetchone()
        return dict(r) if r else None
    finally: con.close()

def _grant_post_beta_days(target_cid, days, receipt_id, admin_cid=''):
    """Tambah entitlement selepas tamat Public Beta; Telegram ID ialah identiti kanonik."""
    days=int(days)
    allowed={5,10,15,20,25,30,60,90,120,150,180,210,240,270,300}
    if days not in allowed: raise ValueError('Tempoh tidak dibenarkan')
    # 15 Oct 2026 00:00 Malaysia = 14 Oct 2026 16:00 UTC.
    beta_base=datetime(2026,10,14,16,0,0,tzinfo=timezone.utc)
    uid=int(target_cid)
    rec=_donation_receipt(receipt_id) or {}
    token=str(rec.get('receipt_token') or '').strip() or f'legacy-receipt:{uid}:{int(receipt_id)}'
    grant_ref=f'{token}:grant:+{days}d'
    # Duplicate guard persistent: walaupun SQLite diganti, ledger Supabase masih tahu grant ini.
    try:
        prior=_sb_request('GET',f'credit_ledger?telegram_user_id=eq.{uid}&reference_id=eq.{grant_ref}&select=id&limit=1') or []
        if prior:
            raise ValueError('Tambahan hari untuk resit ini telah direkod sebelum ini')
    except CreditStoreUnavailable:
        raise
    rows=_sb_request('GET',f'subscriptions?telegram_user_id=eq.{uid}&select=telegram_user_id,status,started_at,expires_at,last_payment_reference') or []
    current=_parse_sb_dt((rows[0] if rows else {}).get('expires_at')) if rows else None
    if current is not None and current.tzinfo is None: current=current.replace(tzinfo=timezone.utc)
    base=max(beta_base,current) if current else beta_base
    new_expiry=base+timedelta(days=days)
    ref=grant_ref
    payload={'status':'active','started_at':beta_base.isoformat(),'expires_at':new_expiry.isoformat(),'last_payment_reference':ref}
    if rows:
        _sb_request('PATCH',f'subscriptions?telegram_user_id=eq.{uid}',json=payload,prefer='return=minimal')
    else:
        payload['telegram_user_id']=uid
        _sb_request('POST','subscriptions',json=payload,prefer='return=minimal')
    # Audit entitlement persistent di Supabase. amount=0 kerana ini bukan transaksi kredit.
    bal=_ensure_user_credit(uid)
    _sb_request('POST','credit_ledger',json={
        'telegram_user_id':uid,'amount':0,'transaction_type':'donation_entitlement',
        'description':f'Admin tambah {days} hari akses selepas Public Beta; tamat {new_expiry.isoformat()}',
        'reference_id':grant_ref,'balance_after':int(bal)
    },prefer='return=minimal')
    con=_db()
    try:
        con.execute("""UPDATE donation_receipts SET status='recorded',granted_days=?,recorded_at=CURRENT_TIMESTAMP,
                       recorded_by=?,notes=? WHERE id=? AND status!='recorded'""",
                    (days,str(admin_cid or ''),ref,int(receipt_id)))
        con.commit()
    finally: con.close()
    return new_expiry

def _admin_donation_days_keyboard(receipt_id):
    vals=[5,10,15,20,25,30,60,90,120,150,180,210,240,270,300]
    rec=_donation_receipt(receipt_id) or {}
    sig=str(rec.get('receipt_token') or '')[-10:] or 'legacy'
    rows=[]
    for i in range(0,len(vals),3):
        rows.append([{'text':f'+{d} HARI','callback_data':f'admin_donation_grant|{receipt_id}|{d}|{sig}'} for d in vals[i:i+3]])
    rows.append([{'text':'👤 LIHAT PENGGUNA','callback_data':f'admin_donation_user|{receipt_id}|{sig}'},{'text':'🛠️ ADMIN PANEL','callback_data':'admin_panel'}])
    return rows

def _admin_persistent_users():
    """Gabungkan direktori pengguna tempatan + Supabase supaya deploy SQLite tidak menghilangkan pengguna lama."""
    merged={}
    con=_db()
    try:
        for r0 in con.execute("SELECT chat_id,username,first_name,last_name,created_at,last_seen FROM bot_users").fetchall():
            r=dict(r0); uid=str(r.get('chat_id') or '').strip()
            if uid: merged[uid]=r
    finally:
        con.close()
    # teacher_profiles ialah stor profil kekal dan memberi nama/panggilan pengguna.
    try:
        rows=_sb_request('GET','teacher_profiles?select=telegram_user_id,display_name,updated_at') or []
        for r in rows:
            uid=str(r.get('telegram_user_id') or '').strip()
            if not uid: continue
            x=merged.setdefault(uid,{'chat_id':uid,'username':'','first_name':'','last_name':'','created_at':'','last_seen':''})
            display=str(r.get('display_name') or '').strip()
            if display and not (str(x.get('first_name') or '').strip() or str(x.get('last_name') or '').strip()):
                x['first_name']=display
            if r.get('updated_at') and not x.get('last_seen'): x['last_seen']=r.get('updated_at')
    except Exception as e:
        print('admin persistent teacher_profiles:',repr(e),flush=True)
    # cikgulaju_users memastikan akaun lama yang mempunyai kredit/percubaan tetap tersenarai.
    try:
        rows=_sb_request('GET','cikgulaju_users?select=telegram_user_id') or []
        for r in rows:
            uid=str(r.get('telegram_user_id') or '').strip()
            if uid: merged.setdefault(uid,{'chat_id':uid,'username':'','first_name':'','last_name':'','created_at':'','last_seen':''})
    except Exception as e:
        print('admin persistent cikgulaju_users:',repr(e),flush=True)
    return list(merged.values())

def _admin_counts():
    con=_db()
    try:
        users=len(_admin_persistent_users())
        feedback=con.execute("SELECT COUNT(*) c FROM beta_feedback").fetchone()['c'] if con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='beta_feedback'").fetchone() else 0
        new_feedback=con.execute("SELECT COUNT(*) c FROM beta_feedback WHERE status='baru'").fetchone()['c'] if feedback else 0
        read_feedback=con.execute("SELECT COUNT(*) c FROM beta_feedback WHERE status='dibaca'").fetchone()['c'] if feedback else 0
        done_feedback=con.execute("SELECT COUNT(*) c FROM beta_feedback WHERE status='selesai'").fetchone()['c'] if feedback else 0
        pending=con.execute("SELECT COUNT(*) c FROM payment_requests WHERE status='pending'").fetchone()['c']
        paid=con.execute("SELECT COUNT(*) c FROM payment_requests WHERE status='approved'").fetchone()['c']
        beta=users if _public_beta_info()['active'] else 0
        return dict(users=users,beta=beta,feedback=feedback,new_feedback=new_feedback,read_feedback=read_feedback,done_feedback=done_feedback,pending=pending,paid=paid)
    finally:
        con.close()

