def _parse_db_dt(v):
    if not v: return None
    try:
        return datetime.fromisoformat(str(v).replace('Z','+00:00')).replace(tzinfo=None)
    except Exception:
        try:
            return datetime.strptime(str(v)[:19],'%Y-%m-%d %H:%M:%S')
        except Exception:
            return None

def _parse_sb_dt(value):
    if not value:
        return None
    try:
        from datetime import datetime, timezone
        txt=str(value).strip().replace('Z','+00:00')
        dt=datetime.fromisoformat(txt)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=timezone.utc)
        return dt
    except Exception:
        return None

def _ensure_trial_user(cid):
    """Ensure a persistent Supabase user row exists and return trial balance."""
    uid=int(cid)
    rows=_sb_request('GET',f'cikgulaju_users?telegram_user_id=eq.{uid}&select=telegram_user_id,trial_remaining') or []
    if rows:
        return max(0,int(rows[0].get('trial_remaining') or 0))
    # New users receive the database default (3 trials). Do not migrate old credit balance.
    _sb_request('POST','cikgulaju_users',json={'telegram_user_id':uid},prefer='return=minimal')
    rows=_sb_request('GET',f'cikgulaju_users?telegram_user_id=eq.{uid}&select=trial_remaining') or []
    return max(0,int((rows[0] if rows else {}).get('trial_remaining') or 3))

def _trial_balance(cid):
    return _ensure_trial_user(cid)

def _use_trial(cid, reason='generation'):
    """Atomically consume one free trial through the Supabase RPC."""
    import uuid
    _ensure_trial_user(cid)
    ref=f'trial:{cid}:{uuid.uuid4().hex}'
    data=_sb_request('POST','rpc/cikgulaju_use_trial',json={
        'p_telegram_user_id':int(cid),
        'p_reference_id':ref,
        'p_reason':str(reason or 'generation')[:200]
    })
    row=(data or [{}])[0] if isinstance(data,list) else (data or {})
    return bool(row.get('ok')), max(0,int(row.get('remaining') or 0))

def _admin_add_trials(target_cid, amount, admin_cid=''):
    """Admin-only bonus trials. Persist balance and audit entry in Supabase."""
    import uuid
    amount=max(1,min(int(amount),100))
    current=_ensure_trial_user(target_cid)
    new_balance=current+amount
    uid=int(target_cid)
    _sb_request('PATCH',f'cikgulaju_users?telegram_user_id=eq.{uid}',
                json={'trial_remaining':new_balance},prefer='return=minimal')
    _sb_request('POST','trial_ledger',json={
        'telegram_user_id':uid,'amount':amount,
        'reason':f'Bonus percubaan oleh admin {admin_cid or "system"}',
        'reference_id':f'admin-trial:{admin_cid or "system"}:{uid}:{uuid.uuid4().hex}',
        'balance_after':new_balance
    },prefer='return=minimal')
    return new_balance

