def _legacy_profile_classes(cid):
    """One-time migration source from the old local SQLite profile-class store."""
    try:
        con=_db()
        con.execute("CREATE TABLE IF NOT EXISTS teacher_profile_classes (chat_id TEXT NOT NULL,class_name TEXT NOT NULL,sequence_no INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(chat_id,class_name))")
        rows=con.execute("SELECT class_name FROM teacher_profile_classes WHERE chat_id=? ORDER BY sequence_no,class_name",(str(cid),)).fetchall()
        return [str(r['class_name'] if hasattr(r,'keys') else r[0]).strip() for r in rows if str(r['class_name'] if hasattr(r,'keys') else r[0]).strip()]
    except Exception as e:
        print('legacy profile classes read:',repr(e),flush=True)
        return []
    finally:
        try: con.close()
        except Exception: pass

def _clean_profile_classes(names):
    clean=[]
    for n in names or []:
        n=' '.join(str(n or '').strip().split())[:60]
        if n and n.lower() not in [x.lower() for x in clean]:
            clean.append(n)
    return clean

def _clean_profile_class_records(records):
    """Normalize class profile rows: [{'name':'6 Amanah','students':32}, ...]."""
    clean=[]
    seen=set()
    for item in records or []:
        if isinstance(item,str):
            item={'name':item,'students':None}
        if not isinstance(item,dict):
            continue
        name=' '.join(str(item.get('name') or item.get('class_name') or '').strip().split())[:60]
        if not name or name.lower() in seen:
            continue
        students=item.get('students')
        try:
            students=int(students) if students not in (None,'','-','—') else None
            if students is not None and not (1 <= students <= 100):
                students=None
        except Exception:
            students=None
        
        timetable=[]
        for e in (item.get('timetable') or []):
            if not isinstance(e,dict): continue
            day=str(e.get('day') or '').strip()[:12]
            start=str(e.get('start') or '').strip()[:5]
            end=str(e.get('end') or '').strip()[:5]
            subject=' '.join(str(e.get('subject') or '').strip().split())[:80]
            if day and re.match(r'^\d{2}:\d{2}$',start) and re.match(r'^\d{2}:\d{2}$',end) and subject:
                timetable.append({'day':day,'start':start,'end':end,'subject':subject})
        clean.append({'name':name,'students':students,'timetable':timetable})
        seen.add(name.lower())
    return clean

def _parse_profile_class_records(raw):
    """Accept: 6 Amanah:32, 6 Bestari:28. Also accepts =, | or (32)."""
    raw=str(raw or '').strip()
    if raw in ('','-','—'):
        return []
    chunks=[x.strip() for x in re.split(r'[,;\n]+',raw) if x.strip()]
    out=[]
    for chunk in chunks:
        name=chunk
        students=None
        m=re.match(r'^(.*?)(?:\s*[:=|]\s*|\s*\(\s*)(\d{1,3})\s*\)?$',chunk)
        if m:
            name=m.group(1).strip()
            students=int(m.group(2))
        out.append({'name':name,'students':students})
    return _clean_profile_class_records(out)

def _profile_class_records(cid):
    """Authoritative class+student-count list in Supabase teacher_profiles.class_profiles.

    class_names is retained as a compatibility mirror for older app versions.
    Old class_names / SQLite values are migrated non-destructively when needed.
    """
    try:
        p=_teacher_profile(cid) or {}
        raw=p.get('class_profiles')
        if isinstance(raw,list):
            rows=_clean_profile_class_records(raw)
            if rows:
                return rows
        elif isinstance(raw,str) and raw.strip():
            try:
                rows=_clean_profile_class_records(json.loads(raw))
                if rows:
                    return rows
            except Exception:
                pass

        # Compatibility fallback from existing Supabase class_names.
        names_raw=p.get('class_names')
        names=[]
        if isinstance(names_raw,list):
            names=_clean_profile_classes(names_raw)
        elif isinstance(names_raw,str) and names_raw.strip():
            t=names_raw.strip().strip('{}')
            names=_clean_profile_classes([x.strip().strip('"') for x in t.split(',') if x.strip()])

        # One-time fallback from legacy local SQLite.
        if not names:
            names=_legacy_profile_classes(cid)

        rows=[{'name':n,'students':None} for n in names]
        if rows and p:
            try:
                _save_teacher_profile(cid,class_profiles=rows,class_names=names)
            except Exception as e:
                print('profile class records migration:',repr(e),flush=True)
        return rows
    except Exception as e:
        print('profile class records read:',repr(e),flush=True)
        return []

def _profile_classes(cid):
    return [r['name'] for r in _profile_class_records(cid)]

def _profile_class_record(cid, class_name):
    target=str(class_name or '').strip().lower()
    for row in _profile_class_records(cid):
        if str(row.get('name') or '').strip().lower()==target:
            return row
    return None

def _save_profile_class_records(cid, records):
    clean=_clean_profile_class_records(records)
    # Keep class_names mirrored so old deployments/callbacks remain compatible.
    _save_teacher_profile(cid,
                          class_profiles=clean,
                          class_names=[r['name'] for r in clean])
    return clean

def _save_profile_classes(cid, names):
    # Compatibility wrapper for older callers.
    existing={str(r.get('name') or '').lower():r for r in _profile_class_records(cid)}
    rows=[]
    for name in _clean_profile_classes(names):
        old=existing.get(name.lower()) or {}
        rows.append({'name':name,'students':old.get('students')})
    return _save_profile_class_records(cid,rows)


