def _subscription_row(cid):
    uid=int(cid)
    rows=_sb_request('GET',f'subscriptions?telegram_user_id=eq.{uid}&select=telegram_user_id,status,plan_code,started_at,expires_at,last_payment_reference') or []
    return rows[0] if rows else None

def _access_info(cid):
    """Authoritative subscription access state."""
    from datetime import datetime, timezone
    try:
        row=_subscription_row(cid)
    except CreditStoreUnavailable:
        raise
    now=datetime.now(timezone.utc)
    if not row:
        return {'active':False,'status':'inactive','access_start':None,'access_until':None,'days_left':0}
    until=_parse_sb_dt(row.get('expires_at'))
    active=(str(row.get('status') or '').lower()=='active' and until is not None and until>now)
    days_left=max(0,(until.date()-now.date()).days+1) if active and until else 0
    return {'active':active,
            'status':'active' if active else ('expired' if until else str(row.get('status') or 'inactive')),
            'access_start':row.get('started_at'),'access_until':row.get('expires_at'),'days_left':days_left}

def _activate_access(target_cid, days=30, admin_cid='', notes='Manual payment verified', payment_reference=None, amount_rm=5.00):
    """Activate/extend access atomically in Supabase. Active users extend from current expiry."""
    import uuid
    days=max(1,min(int(days),3650))
    ref=str(payment_reference or f'admin:{admin_cid or "system"}:{target_cid}:{uuid.uuid4().hex}')
    data=_sb_request('POST','rpc/cikgulaju_activate_subscription',json={
        'p_telegram_user_id':int(target_cid),
        'p_payment_reference':ref,
        'p_amount_rm':float(amount_rm) if amount_rm is not None else None,
        'p_days':days
    })
    row=(data or [{}])[0] if isinstance(data,list) else (data or {})
    expiry=row.get('new_expires_at')
    return _parse_sb_dt(expiry) or expiry

def _deactivate_access(target_cid, admin_cid='', notes='Manual deactivation'):
    """Deactivate subscription in persistent Supabase storage."""
    uid=int(target_cid)
    _sb_request('PATCH',f'subscriptions?telegram_user_id=eq.{uid}',
                json={'status':'inactive'},prefer='return=minimal')
    return True

def _public_beta_info():
    """Public Beta is free/unlimited through 14 Oct 2026 (Malaysia date)."""
    now_my = datetime.now(timezone.utc) + timedelta(hours=8)
    today = now_my.date()
    start = datetime(2026,9,14).date()
    end = datetime(2026,10,14).date()
    active = start <= today <= end
    return {'active': active, 'start': start, 'end': end,
            'end_label': '14 Oktober 2026', 'days_left': max(0,(end-today).days+1) if active else 0}

def _is_beta_tester(cid):
    # During Public Beta every user, including existing users, is a beta tester.
    return bool(_public_beta_info()['active'])

