def send_subscription_payment(cid):
    global _donation_qr_file_id

    # Create/reuse a pending payment record as soon as the user opens payment.
    pending=_latest_pending_payment(cid)
    req_id=(pending or {}).get('id') or _new_payment_request(cid,None,5.00)
    _set_payment_note(req_id,'awaiting_proof')
    state.setdefault(cid,{})['waiting']='payment_proof'

    caption=(
      '💳 <b>BAYARAN CIKGULAJU</b>\n\n'
      '📦 Pakej: <b>AKSES 30 HARI</b>\n'
      '💰 Jumlah: <b>RM5.00</b>\n\n'
      '<b>CARA BAYAR:</b>\n\n'
      '1️⃣ Scan DuitNow QR di atas.\n\n'
      '2️⃣ Buat pembayaran sebanyak <b>RM5.00</b>.\n\n'
      '3️⃣ Selepas pembayaran berjaya, ambil screenshot RESIT pembayaran.\n\n'
      '4️⃣ Hantar screenshot resit tersebut di chat ini.\n\n'
      '⌛ Akses 30 hari akan diaktifkan selepas pembayaran disahkan oleh admin.\n\n'
      '⚠️ Jangan hantar gambar bahan/produk ketika berada di halaman pembayaran ini.'
    )

    kb={'inline_keyboard':[
        [{'text':'❌ Batal Bayaran','callback_data':'cancel_payment'}],
        [{'text':'🏠 Menu Utama','callback_data':'home'}]
    ]}
    reply_markup=__import__('json').dumps(kb,ensure_ascii=False)

    try:
        qr_bytes=base64.b64decode(DONATION_QR_B64, validate=True)

        if _donation_qr_file_id:
            r=requests.post(
                f'{API}/sendPhoto',
                data={'chat_id':str(cid),'photo':_donation_qr_file_id,
                      'caption':caption,'parse_mode':'HTML',
                      'reply_markup':reply_markup},
                timeout=30
            )
            if r.ok:
                return r
            _donation_qr_file_id=None

        r=requests.post(
            f'{API}/sendPhoto',
            data={'chat_id':str(cid),'caption':caption,'parse_mode':'HTML',
                  'reply_markup':reply_markup},
            files={'photo':('CikguLaju_DuitNow_QR.jpg',BytesIO(qr_bytes),'image/jpeg')},
            timeout=45
        )
        if r.ok:
            try:
                photos=r.json().get('result',{}).get('photo',[])
                if photos:
                    _donation_qr_file_id=photos[-1].get('file_id')
            except Exception:
                pass
            return r

        print('sendPhoto QR failed:',r.status_code,r.text[:300],flush=True)

        r2=requests.post(
            f'{API}/sendDocument',
            data={'chat_id':str(cid),
                  'caption':caption,
                  'parse_mode':'HTML',
                  'reply_markup':reply_markup},
            files={'document':('CikguLaju_DuitNow_QR.jpg',BytesIO(qr_bytes),'image/jpeg')},
            timeout=45
        )
        if r2.ok:
            return r2

        raise RuntimeError(
            f'sendPhoto={r.status_code}:{r.text[:120]} | '
            f'sendDocument={r2.status_code}:{r2.text[:120]}'
        )

    except Exception as e:
        print('Subscription QR error:',repr(e),flush=True)
        return send(
            cid,
            '⚠️ <b>QR bayaran gagal dihantar.</b>\n\n'
            'Tekan Cuba Semula.',
            [[{'text':'🔄 Cuba Semula','callback_data':'subscribe_500'}],
             [{'text':'🏠 Menu Utama','callback_data':'home'}]]
        )

def _credit_gate(cid,s):
    """Unlimited generation for every beta tester through 14 Oct 2026."""
    if _is_beta_tester(cid):
        return True
    try:
        a=_access_info(cid)
        if a['active']:
            return True
        reason='Jana '+str((s or {}).get('task') or 'bahan')+' '+str((s or {}).get('assessment_mode') or '')
        ok,remaining=_use_trial(cid,reason)
    except CreditStoreUnavailable as e:
        print('Supabase access store error:',repr(e),flush=True)
        send(cid,'⚠️ <b>Status akaun sedang tidak dapat disemak.</b>\n\nLangganan dan percubaan cikgu tidak direset atau dipadam. Cuba lagi sebentar.',
             [[{'text':'🔄 Cuba Lagi','callback_data':'generate'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        return False
    if ok:
        send(cid,f'🎁 <b>Percubaan percuma digunakan.</b> Baki: <b>{remaining}</b>',None)
        return True
    send(cid,
      '🔒 <b>Percubaan percuma telah habis.</b>\n\n'
      'Aktifkan CikguLaju untuk penggunaan sepanjang <b>30 hari</b>.\n\n'
      '⭐ <b>RM5.00 / 30 hari</b>\n'
      'Tiada kontrak • Tiada pembaharuan automatik.',
      [[{'text':'💳 AKTIFKAN RM5.00','callback_data':'subscribe_500'}],
       [{'text':'👤 Akaun Saya','callback_data':'account'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    return False

