def _material_save(cid,key,obj):
    _exam_bank_init(); con=_db()
    try:
        con.execute("INSERT INTO generated_materials(chat_id,material_key,payload,updated_at) VALUES(?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(chat_id,material_key) DO UPDATE SET payload=excluded.payload,updated_at=CURRENT_TIMESTAMP",(str(cid),key,json.dumps(obj,ensure_ascii=False)))
        con.commit()
    finally: con.close()

def _material_load(cid,key):
    _exam_bank_init(); con=_db()
    try:
        r=con.execute('SELECT payload FROM generated_materials WHERE chat_id=? AND material_key=?',(str(cid),key)).fetchone()
        return json.loads(r['payload']) if r else None
    except Exception: return None
    finally: con.close()

def _year_num_local(year):
    m=re.search(r'(\\d+)',str(year or ''))
    return int(m.group(1)) if m else 1

def _local_exam_from_bank(s):
    """Zero-AI exam generator. Diverse, topic-aware items with proper calculation space."""
    _exam_bank_init()
    subject=str(s.get('subject') or ''); y=_year_num_local(s.get('year'))
    topics=list(s.get('summative_topics') or []); bp=_summative_exam_blueprint(s)
    seed=str(s.get('variation_seed') or secrets.token_hex(4)); rng=random.Random(seed)
    con=_db()
    try:
        rows=[dict(r) for r in con.execute('SELECT * FROM exam_item_bank WHERE subject=? AND year_min<=? AND year_max>=? AND active=1 ORDER BY id',(subject,y,y)).fetchall()]
    finally: con.close()
    marks=int(bp.get('marks') or (20 if y==1 else 30)); lines=[]; scheme=[]; q=1; total=0
    topic_text=' '.join(topics).lower()

    if subject=='Matematik':
        # Bahagian A: item pendek yang pelbagai. Elak pola tambah/tolak berselang-seli sahaja.
        lines += ['BAHAGIAN A','Jawab semua soalan. Tulis jawapan pada ruang yang disediakan.','']
        target_a=min(15, max(10, marks//2))
        item_pool=[]
        def add(text,ans,space=''):
            item_pool.append((text,str(ans),space))

        # Nombor bulat / nilai tempat / pola / anggaran / pembundaran
        if (not topics) or any(k in topic_text for k in ['nombor','bulat','nilai','pola','anggar','bundar']):
            n=rng.randint(101,999 if y>=2 else 100)
            hundreds=(n//100)*100; tens=((n//10)%10)*10
            add(f'Nyatakan nilai digit {str(n)[1] if n>=100 else str(n)[0]} dalam nombor {n}.', tens if n>=100 else n)
            a=rng.randint(120,700); b=a+rng.randint(10,180)
            add(f'Antara {a} dan {b}, nombor manakah lebih besar?',max(a,b))
            st=rng.randint(120,500); step=rng.choice([2,5,10,100]); add(f'Lengkapkan pola nombor: {st}, {st+step}, {st+2*step}, ______, {st+4*step}.',st+3*step)
            n2=rng.randint(111,989); rounded=int(round(n2/10.0)*10); add(f'Bundarkan {n2} kepada puluh terdekat.',rounded)

        # Operasi asas — campur, tolak, darab, bahagi; bentuk lazim bila sesuai.
        if (not topics) or any(k in topic_text for k in ['operasi','tambah','tolak','darab','bahagi']):
            a=rng.randint(120,650); b=rng.randint(20,min(300,999-a)); add(f'{a} + {b} = ______',a+b,'[FORM_LAZIM: 3, 4]')
            a=rng.randint(300,950); b=rng.randint(20,a-10); add(f'{a} − {b} = ______',a-b,'[FORM_LAZIM: 3, 4]')
            m=rng.randint(2,9); n=rng.randint(2,9); add(f'{m} × {n} = ______',m*n,'[ANSWERSPACE: 2]')
            d=rng.randint(2,9); quot=rng.randint(2,9); add(f'{d*quot} ÷ {d} = ______',quot,'[ANSWERSPACE: 2]')
            x=rng.randint(2,9); add(f'{x} × 10 = ______',x*10,'[ANSWERSPACE: 2]')

        # Pecahan / perpuluhan — visual dan perbandingan, bukan operasi berulang.
        if (not topics) or any(k in topic_text for k in ['pecahan','perpuluhan']):
            den=rng.choice([2,4,5,10]); num=rng.randint(1,den-1)
            add(f'Nyatakan pecahan yang ditunjukkan. [FRACTION_BAR: {num}, {den}]',f'{num}/{den}')
            d=10; n=rng.randint(1,9); add(f'Tukarkan pecahan {n}/10 kepada perpuluhan.',f'0.{n}')
            x,y=sorted(rng.sample(range(1,10),2)); add(f'Yang manakah lebih besar, 0.{x} atau 0.{y}?',f'0.{y}')
            add('Pilih pecahan yang sama dengan satu perdua.\nA. 1/4\nB. 1/2\nC. 3/4\nD. 1/10','B')

        # Tambah variasi jika skop sempit, kemudian rawak dan ambil jumlah sesuai.
        while len(item_pool)<target_a:
            a=rng.randint(20,300); b=rng.randint(2,50)
            add(f'{a} + {b} = ______',a+b,'[ANSWERSPACE: 2]')
        rng.shuffle(item_pool)
        for text,ans,space in item_pool[:target_a]:
            lines.append(f'{q}. {text} [1 markah]')
            if space: lines.append(space)
            lines.append(''); scheme.append(f'{q}. {ans}'); q+=1; total+=1

        # Bahagian B: penyelesaian masalah / aplikasi. Ruang pengiraan besar dan jelas.
        lines += ['BAHAGIAN B','Jawab semua soalan. Tunjukkan jalan kerja dengan jelas.','']
        contexts=[]
        a=rng.randint(120,500); b=rng.randint(30,200); contexts.append((f'Perpustakaan mempunyai {a} buah buku. Sekolah menerima {b} buah buku baharu. Berapakah jumlah buku sekarang?',a+b))
        a=rng.randint(300,900); b=rng.randint(50,a-30); contexts.append((f'Sebuah kedai mempunyai {a} batang pensel. Sebanyak {b} batang telah dijual. Berapakah pensel yang masih ada?',a-b))
        m=rng.randint(3,8); n=rng.randint(2,9); contexts.append((f'Ada {m} bekas. Setiap bekas mengandungi {n} biji guli. Berapakah jumlah guli semuanya?',m*n))
        d=rng.randint(2,8); each=rng.randint(2,9); contexts.append((f'{d*each} biji kuih dibahagikan sama rata kepada {d} orang murid. Berapa biji kuih diterima oleh setiap murid?',each))
        contexts.append(('Lorek atau nyatakan satu perdua daripada satu bentuk yang dibahagi kepada 2 bahagian sama besar. [FRACTION_BAR: 1, 2]','1/2'))
        rng.shuffle(contexts)
        remaining=marks-total
        idx=0
        while remaining>0:
            m=min(3,remaining); text,ans=contexts[idx%len(contexts)]; idx+=1
            lines += [f'{q}. {text} [{m} markah]','[ANSWERSPACE: 5]','']
            scheme.append(f'{q}. {ans}'); q+=1; total+=m; remaining-=m

    elif subject=='Bahasa Inggeris':
        lines += ['PART 1','Answer all questions.','']
        bank=rows or []
        while total < marks:
            r=bank[(q-1)%len(bank)] if bank else {'template_text':'Choose the correct greeting.\nA. Good morning\nB. Blue\nC. Run\nD. Pencil','answer_rule':'A','marks':1}
            lines += [f'{q}. '+r['template_text'],'']; scheme.append(f"{q}. {r.get('answer_rule') or 'A'}")
            total+=int(r.get('marks') or 1); q+=1
    else:
        lines += ['BAHAGIAN A','Jawab semua soalan.','']
        bank=rows or []
        while total < marks:
            if bank:
                r=bank[(q-1)%len(bank)]; text=r['template_text']; ans=r.get('answer_rule') or 'A'; m=int(r.get('marks') or 1)
            else:
                text=f'Nyatakan satu fakta yang betul berkaitan {topics[(q-1)%len(topics)] if topics else subject}.'; ans='Jawapan munasabah berdasarkan DSKP'; m=1
            lines += [f'{q}. {text}', '[ANSWERSPACE: 2]' if m>1 else '', '']; scheme.append(f'{q}. {ans}'); total+=m; q+=1
    lines += ['', 'SKEMA JAWAPAN' if subject!='Bahasa Inggeris' else 'MARKING SCHEME'] + scheme
    return '\n'.join(x for x in lines if x is not None)

def generate_summative_paper(cid, s, regen_cb='generate_selected_material'):
    with _runtime_lock:
        if cid in _processing_chats:
            return send(cid,'⏳ <b>Kertas sumatif masih sedang dijana.</b>')
        _processing_chats.add(cid)
    try:
        send(cid,'⚡ <b>Sedang menyediakan kertas sumatif...</b>\n<i>Cikgu tunggu beberapa saat.</i>')
        ctx=dict(s); ctx['task']='worksheet'; ctx['assessment_mode']='summative'
        ctx['variation_seed']=secrets.token_hex(4)
        raw=_local_exam_from_bank(ctx)
        st=state.setdefault(cid,{})
        st['summative_result']=raw
        st['summative_context']=ctx
        _material_save(cid,'summative',{'result':raw,'context':ctx})
        send(cid,'✅ <b>Kertas sumatif siap!</b>',[
            [{'text':'📄 Dapatkan PDF','callback_data':'file_summative'}],
            [{'text':'🔄 Jana Semula','callback_data':regen_cb}],
            [{'text':'🏠 Menu Utama','callback_data':'home'}]
        ])
    except Exception as e:
        print('Summative generation error:',repr(e),flush=True)
        send(cid,'⚠️ Kertas sumatif belum berjaya dijana. Cuba lagi.',[[{'text':'🔄 Cuba Lagi','callback_data':regen_cb}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    finally:
        with _runtime_lock:
            _processing_chats.discard(cid)

def generate_summative_both(cid, s):
    """Generate RPH examination session + one summative paper."""
    with _runtime_lock:
        if cid in _processing_chats:
            return send(cid,'⏳ <b>Bahan sumatif masih sedang dijana.</b>')
        _processing_chats.add(cid)
    try:
        send(cid,'⚡ <b>Sedang menyediakan RPH pentaksiran dan kertas sumatif...</b>\n<i>Cikgu tunggu beberapa saat.</i>')
        rctx=dict(s); rctx['task']='rph'; rctx['assessment_mode']='summative'
        wctx=dict(s); wctx['task']='worksheet'; wctx['assessment_mode']='summative'
        rph=_summative_rph_text(rctx)
        wctx['variation_seed']=secrets.token_hex(4)
        paper=_local_exam_from_bank(wctx)
        st=state.setdefault(cid,{})
        st['summative_both_results']={'rph':rph,'paper':paper}
        st['summative_both_contexts']={'rph':rctx,'paper':wctx}
        _material_save(cid,'summative_both',{'results':st['summative_both_results'],'contexts':st['summative_both_contexts']})
        send(cid,'✅ <b>RPH pentaksiran dan kertas sumatif siap!</b>',[
            [{'text':'📚 Dapatkan Pakej','callback_data':'file_summative_both'}],
            [{'text':'🔄 Jana Semula','callback_data':'generate_selected_material'}],
            [{'text':'🏠 Menu Utama','callback_data':'home'}]
        ])
    except Exception as e:
        print('Summative both error:',repr(e),flush=True)
        send(cid,'⚠️ Bahan sumatif belum berjaya dijana. Cuba lagi.',[[{'text':'🔄 Cuba Lagi','callback_data':'generate_selected_material'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    finally:
        with _runtime_lock:
            _processing_chats.discard(cid)

def _curriculum_state_ready(cid, require_subject=True):
    """Validate volatile Telegram flow state after a Render restart/deploy.
    Never silently fall back to Tahun 1 when the previous in-memory session is gone.
    """
    ss=state.setdefault(cid,{})
    year_label=str(ss.get('year') or '').strip()
    subject=str(ss.get('subject') or '').strip()
    valid_year=year_label in SUBJECTS_BY_GRADE
    valid_subject=(not require_subject) or (valid_year and subject in SUBJECTS_BY_GRADE.get(year_label,[]))
    if valid_year and valid_subject:
        return True
    # A deployment/restart clears Python RAM; old Telegram inline buttons can still be tapped.
    # Recover explicitly instead of defaulting to Tahun 1.
    task=ss.get('task')
    rph_mode=ss.get('rph_mode')
    state[cid]={}
    if task: state[cid]['task']=task
    if rph_mode: state[cid]['rph_mode']=rph_mode
    send(cid,
         '🔄 <b>Sesi pilihan telah dimulakan semula.</b>\n\n'
         'Ini biasanya berlaku selepas aplikasi di-deploy/restart. '
         'Sila pilih semula Tahun/Tingkatan supaya pilihan lama tidak tersalah menjadi Tahun 1.')
    choose_grade(cid)
    return False

def choose_assessment_mode(cid):
    # v22.71: Sumatif disembunyikan sementara daripada UI.
    # Semua worksheet/RPH standard terus menggunakan flow formatif.
    if not _curriculum_state_ready(cid, require_subject=True):
        return
    s=state.setdefault(cid,{})
    s['assessment_mode']='formative'
    s.pop('summative_topics',None)
    return show_topics(cid,0)

def show_summative_scope(cid, page=0):
    s=state.setdefault(cid,{})
    topics=curriculum_topic_options(s.get('year',''),s.get('subject',''))
    selected=set(s.get('summative_topics') or [])
    if not topics:
        return show_topics(cid,0)
    s['summative_topic_list']=topics
    per_page=8; start=page*per_page; end=min(start+per_page,len(topics))
    kb=[]
    for i in range(start,end):
        mark='☑️' if topics[i] in selected else '⬜'
        kb.append([{'text':f'{mark} {topics[i]}','callback_data':f'sumtopic_{i}_{page}'}])
    nav=[]
    if page>0: nav.append({'text':'⬅️ Sebelum','callback_data':f'sumpage_{page-1}'})
    if end<len(topics): nav.append({'text':'Seterusnya ➡️','callback_data':f'sumpage_{page+1}'})
    if nav: kb.append(nav)
    kb.append([{'text':'☑️ Pilih Semua Topik','callback_data':'sum_all'}])
    kb.append([{'text':f'✅ Teruskan ({len(selected)} topik)','callback_data':'sum_continue'}])
    kb.append([{'text':'⬅️ Jenis Latihan','callback_data':'back_mode'}])
    send(cid, f'📝 <b>Sumatif — {s.get("subject","")} {s.get("year","")}</b>\n\nPilih satu atau banyak topik untuk skop ujian:', kb)

def show_topics(cid, page=0):
    if not _curriculum_state_ready(cid, require_subject=True):
        return
    s = state.setdefault(cid,{})
    year_label = s.get('year','')
    sub = s.get('subject','')
    topics = curriculum_topic_options(year_label, sub)

    if not topics:
        # Untuk 4 subjek sekolah rendah production, topik mesti datang daripada DB kurikulum.
        # Jangan jatuh balik kepada input tajuk bebas kerana itu boleh menghasilkan kandungan di luar SK/SP.
        db_name=os.path.basename(DB_PATH)
        send(cid,
             f'⚠️ <b>Data kurikulum belum dapat dibaca.</b>\n\n'
             f'Subjek: <b>{sub}</b>\nTahun: <b>{year_label}</b>\n\n'
             f'Pastikan fail <code>{db_name}</code> berada bersama <code>app.py</code> di Render/GitHub.\n'
             'Selepas fail database tersedia, sistem akan memaparkan senarai topik — cikgu tidak perlu menaip tajuk sendiri.',
             [[{'text':'⬅️ Pilih Subjek','callback_data':'back_subjects'}],
              [{'text':'🏠 Menu Utama','callback_data':'home'}]])
        return

    s['topic_list'] = topics
    per_page = 8
    start = page * per_page
    end = min(start + per_page, len(topics))
    kb = []
    for idx in range(start, end):
        kb.append([{'text':f'📖 {topics[idx]}','callback_data':f'topic_{idx}'}])

    nav = []
    if page > 0:
        nav.append({'text':'⬅️ Sebelum','callback_data':f'tpage_{page-1}'})
    if end < len(topics):
        nav.append({'text':'Seterusnya ➡️','callback_data':f'tpage_{page+1}'})
    if nav:
        kb.append(nav)
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])

    pages = (len(topics)+per_page-1)//per_page
    send(cid,f'📚 <b>{sub} — {year_label}</b>\n\nPilih tajuk/topik:\n<i>Halaman {page+1}/{pages}</i>',kb)

def show_subtopics(cid, topic_index):
    s = state.setdefault(cid,{})
    topics = curriculum_topic_options(s.get('year',''),s.get('subject',''))
    if topic_index < 0 or topic_index >= len(topics):
        return show_topics(cid,0)

    s['selected_topic_index'] = topic_index
    s['topic'] = topics[topic_index]
    subs = get_subtopics(s.get('year',''), s.get('subject',''), s['topic'])

    kb = [[{'text':'📚 Semua Subtopik','callback_data':f'st3|-1|{topic_index}'}]]
    for i, item in enumerate(subs):
        kb.append([{'text':f'▫️ {item}','callback_data':f'st3|{i}|{topic_index}'}])
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    send(cid,
         f"📖 <b>{s['topic']}</b>\n\nPilih subtopik dengan menekan butang di bawah:\n<i>Tidak perlu taip sendiri. Senarai ini tetap.</i>",
         kb)

def choose_topic(cid, idx):
    s=state.setdefault(cid,{})
    topics=curriculum_topic_options(s.get('year',''),s.get('subject',''))
    if idx < 0 or idx >= len(topics):
        return show_topics(cid,0)
    s['selected_topic_index']=idx
    s['topic']=topics[idx]
    s['subtopic']='Semua Subtopik'
    if s.get('task') == 'quick_material':
        return show_curriculum_sk(cid,s)
    if s.get('task') == 'bbm':
        # BBM must follow explicit SK/SP selection, not a broad topic alone.
        return show_curriculum_sk(cid,s)
    if s.get('task') in ('rph','both'):
        start_rph_session(cid)
    else:
        show_curriculum_sk(cid,s)

TASK_TO_CODE = {'questions':'q','worksheet':'w','rph':'r','both':'b','kbat':'k'}
CODE_TO_TASK = {v:k for k,v in TASK_TO_CODE.items()}
QTYPE_TO_CODE = {'Objektif':'o','Struktur':'s','KBAT':'k','Campuran':'c'}
CODE_TO_QTYPE = {v:k for k,v in QTYPE_TO_CODE.items()}

def compact_year(label):
    return ('p' if label.startswith('Tahun ') else 's') + label.split()[-1]

def expand_year(code):
    return ('Tahun ' if code.startswith('p') else 'Tingkatan ') + code[1:]

def subject_index(subject):
    for i, (_, sub) in enumerate(SUBJECTS):
        if sub == subject:
            return i
    return -1

def rebuild_state(tc, yc, si, ti, sti, qc='-', amount='-'):
    try:
        si, ti, sti = int(si), int(ti), int(sti)
    except Exception:
        return None
    year_label = expand_year(yc)
    if si < 0 or si >= len(SUBJECTS):
        return None
    subject = SUBJECTS[si][1]
    topics = curriculum_topic_options(year_label,subject)
    if ti < 0 or ti >= len(topics):
        return None
    topic = topics[ti]
    subs = get_subtopics(year_label, subject, topic)
    subtopic = 'Semua Subtopik'
    if sti >= 0:
        if sti >= len(subs):
            return None
        subtopic = subs[sti]

    s = {
        'task': CODE_TO_TASK.get(tc,''),
        'year': year_label,
        'subject': subject,
        'topic': topic,
        'subtopic': subtopic,
        'selected_topic_index': ti,
        'selected_subtopic_index': sti,
    }
    if qc != '-':
        s['qtype'] = CODE_TO_QTYPE.get(qc,'')
    if amount != '-':
        s['amount'] = str(amount)
    return s if s['task'] else None

def show_qtype_v3(cid, s, sti):
    tc = TASK_TO_CODE[s['task']]
    yc = compact_year(s['year'])
    si = subject_index(s['subject'])
    ti = s['selected_topic_index']
    send(cid,'📝 <b>Pilih jenis soalan:</b>',[
        [{'text':'🔘 Objektif','callback_data':f'qt3|o|{tc}|{yc}|{si}|{ti}|{sti}'},
         {'text':'✍️ Subjektif / Struktur','callback_data':f'qt3|s|{tc}|{yc}|{si}|{ti}|{sti}'}],
        [{'text':'🧠 KBAT','callback_data':f'qt3|k|{tc}|{yc}|{si}|{ti}|{sti}'},
         {'text':'🔀 Campuran','callback_data':f'qt3|c|{tc}|{yc}|{si}|{ti}|{sti}'}]])

def preview_v3(cid, s, gen_cb):
    task=s.get('task')
    if task == 'worksheet':
        detail = (f"📘 SK: {s.get('sk_code','-')} {s.get('sk_text','')}\n"
                  f"📗 SP: {s.get('sp_code','-')} {s.get('sp_text','')}\n"
                  f"📐 Jumlah item: automatik mengikut SP, tahap murid dan ruang A4\n"
                  f"📚 4 aras dijana terus: Pemulihan/Asas • Sederhana • Penguasaan • Pengayaan/KBAT")
    elif task in ('rph','both'):
        date = s.get('rph_date') or 'Kosong'
        day = s.get('rph_day') or 'Kosong'
        kelas = s.get('rph_class') or 'Kosong'
        masa = s.get('rph_time') or 'Kosong'
        murid = s.get('rph_students') or 'Kosong'
        detail = (f"📘 SK: {s.get('sk_code','-')} {s.get('sk_text','')}\n"
                  f"📗 SP: {s.get('sp_code','-')} {s.get('sp_text','')}\n"
                  f"📅 Tarikh: {date} ({day})\n🏫 Kelas: {kelas}\n⏰ Masa: {masa}\n👥 Bilangan Murid: {murid}")
        if task=='both':
            detail += "\n📝 Worksheet: 4 aras • jumlah item automatik"
    else:
        detail = f"📝 {s.get('qtype','-')}\n🔢 {s.get('amount','-')} soalan"
    msg = (f"✅ <b>Pilihan Cikgu</b>\n\n🎓 {s.get('year','-')}\n📚 {s.get('subject','-')}\n"
           f"📖 {s.get('topic','-')}\n▫️ {s.get('subtopic','Semua Subtopik')}\n{detail}")
    label = '📚 Jana RPH + BBM + Worksheet' if task=='both' else ('📘 Jana RPH' if task=='rph' else '📝 Jana Worksheet')
    send(cid, msg, [[{'text':label,'callback_data':gen_cb}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])

def _duration_fit_rph_text(text, s):
    """Force RPH phases, objective load and assessment to fit the exact selected lesson duration."""
    import re
    dur=max(20, min(180, int(s.get('rph_duration_minutes') or 60)))
    sec=_parse_rph_sections(text)
    subject=str(s.get('subject') or '')
    topic=str(s.get('topic') or '')
    sub=str(s.get('subtopic') or '')
    focus=sub if sub and sub not in ('Semua Subtopik','All Subtopics') else topic
    sp_codes=[str(x).strip() for x in (s.get('grouped_sp_codes') or s.get('selected_sp_codes') or []) if str(x).strip()]
    if not sp_codes and str(s.get('sp_code') or '').strip():
        sp_codes=[x.strip() for x in str(s.get('sp_code') or '').split(';') if x.strip()]
    sp_texts=[str(x).strip() for x in (s.get('grouped_sp_texts') or []) if str(x).strip()]
    if not sp_texts and str(s.get('sp_text') or '').strip():
        sp_texts=[x.strip() for x in str(s.get('sp_text') or '').split(';') if x.strip()]
    sp=', '.join(sp_codes)
    sp_detail='; '.join(sp_texts)
    eng=(subject=='Bahasa Inggeris')
    # English may use a Main Skill + Complementary Skill. Ensure the PDF
    # displays every committed SK/SP instead of showing only the legacy
    # primary standard while the objective mentions both.
    if eng:
        gsk_codes=[str(x).strip() for x in (s.get('grouped_sk_codes') or []) if str(x).strip()]
        gsk_texts=[str(x).strip() for x in (s.get('grouped_sk_texts') or [])]
        if gsk_codes:
            sec['STANDARD KANDUNGAN']='\n'.join((c + (' ' + gsk_texts[i] if i < len(gsk_texts) and gsk_texts[i] else '')).strip() for i,c in enumerate(gsk_codes))
        if sp_codes:
            sec['STANDARD PEMBELAJARAN']='\n'.join((c + (' ' + sp_texts[i] if i < len(sp_texts) and sp_texts[i] else '')).strip() for i,c in enumerate(sp_codes))
    # Skill routing must consider every SP selected, not only the first SP.
    key=(focus+' '+sp_detail).lower()

    # Exact time budget. Closure includes the final PBD/exit evidence for short lessons.
    if dur <= 25:
        induction=2; closure=3; main=dur-induction-closure; slots=[main]
    elif dur <= 35:
        induction=3; closure=4; main=dur-induction-closure; slots=[main//2, main-main//2]
    elif dur <= 50:
        induction=4; closure=5; main=dur-induction-closure; a=main//2; slots=[a,main-a]
    elif dur <= 70:
        induction=5; closure=5; main=dur-induction-closure; a=main//3; slots=[a,a,main-2*a]
    elif dur <= 90:
        induction=7; closure=7; main=dur-induction-closure; n=4; a=main//n; slots=[a]*(n-1)+[main-a*(n-1)]
    elif dur <= 120:
        induction=8; closure=8; main=dur-induction-closure; n=5; a=main//n; slots=[a]*(n-1)+[main-a*(n-1)]
    else:
        induction=10; closure=10; main=dur-induction-closure; n=6 if dur<=150 else 7; a=main//n; slots=[a]*(n-1)+[main-a*(n-1)]

    if eng:
        if any(w in key for w in ('speak','speaking','communicat','ask','answer')):
            prompts=2 if dur<=25 else (3 if dur<=40 else (4 if dur<=60 else 5))
            sec['OBJEKTIF PEMBELAJARAN']=f'By the end of the {dur}-minute lesson, pupils can demonstrate SP {sp} in the context of {focus} by completing a short spoken exchange and responding appropriately to at least {prompts} prompts.'
            sec['KRITERIA KEJAYAAN']=f'Pupils complete the target question/response pattern for at least {prompts} prompts with relevant information and understandable pronunciation.'
            sec['SET INDUKSI']=f'{induction} minutes\n1. Teacher shows one picture/profile card related to {focus} and elicits one natural question and answer.\n2. Pupils identify and repeat only the useful language chunks needed for the task.'
            acts=[]
            names=['Model + Pair Rehearsal','Information Gap Exchange','Partner Rotation','Language Upgrade','Role-play Challenge','Individual Speaking Check','Reflection + Extension']
            bodies=[
              'Teacher models one exchange. Pairs practise with prompt/profile cards, then replace the model information with their own details.',
              'Pupil A and Pupil B receive different information. They ask and answer without showing their cards and complete the missing information.',
              'Pupils change partner and repeat the target exchange with a new prompt, improving fluency and accuracy.',
              'Pairs improve an earlier response by adding accurate detail, a follow-up question or clearer pronunciation, then rehearse again.',
              'Pairs complete a short role-play using a new situation and must sustain the exchange without reading a full script.',
              'Selected pupils answer an unseen prompt individually while the teacher records evidence using the success criteria.',
              'Pupils compare two responses, identify one improvement and produce a final stronger response.'
            ]
            for i,m in enumerate(slots): acts.append(f'Activity {i+1} – {names[i]} ({m} minutes)\n{bodies[i]}')
            sec['AKTIVITI UTAMA']='\n\n'.join(acts)
            sec['PENUTUP']=f'{closure} minutes\n1. Teacher gives a quick final speaking prompt to check the success criteria.\n2. Pupils state one useful phrase learned; teacher identifies pupils needing follow-up support.'
            sec['PENTAKSIRAN']='Teacher observes the final spoken response using the stated success criteria; evidence is collected within the allocated lesson time.'
        elif any(w in key for w in ('listen','listening','phoneme','sound')):
            items=3 if dur<=25 else (4 if dur<=45 else 5)
            sec['OBJEKTIF PEMBELAJARAN']=f'By the end of the {dur}-minute lesson, pupils can demonstrate SP {sp} by identifying the required information/sounds in the {focus} context correctly in at least {items-1} out of {items} items.'
            sec['KRITERIA KEJAYAAN']=f'Pupils respond correctly to at least {items-1}/{items} listening items.'
            sec['SET INDUKSI']=f'{induction} minutes\nTeacher uses two topic pictures and one short oral example to activate prior knowledge and introduce the listening focus.'
            pool=['Listen and Choose – pupils select the matching picture/word after short teacher-read items.','Listen and Transfer – pupils record key information in a simple grid/checklist.','Pair Check – pupils compare answers and justify the clue they heard.','Focused Re-listen – pupils listen again for one specific detail and correct earlier answers.','Information Gap – pupils use listened information to complete a partner task.','Individual Listening Check – pupils complete fresh items independently.','Reflection + Extension – pupils explain which listening clue helped and apply it to one final item.']
            sec['AKTIVITI UTAMA']='\n\n'.join(f'Activity {i+1} ({m} minutes)\n{pool[i]}' for i,m in enumerate(slots))
            sec['PENUTUP']=f'{closure} minutes\nTeacher checks one final item, reviews the success criterion and notes pupils needing support.'
        elif any(w in key for w in ('read','reading','comprehension')):
            q=2 if dur<=25 else (3 if dur<=40 else 5)
            sec['OBJEKTIF PEMBELAJARAN']=f'By the end of the {dur}-minute lesson, pupils can demonstrate SP {sp} by locating the required information in a short text about {focus} and answering at least {max(1,q-1)} out of {q} questions correctly.'
            sec['KRITERIA KEJAYAAN']=f'Pupils locate textual evidence and answer at least {max(1,q-1)}/{q} questions correctly.'
            sec['SET INDUKSI']=f'{induction} minutes\nTeacher shows the title/visual and elicits a quick prediction about {focus}.'
            pool=['First Read – pupils read for the main idea and identify one key fact.','Scan for Evidence – pupils locate requested details and mark the exact evidence.','Vocabulary in Context – pupils infer selected words/phrases from surrounding clues.','Information Transfer – pupils transfer details into a simple table/organiser.','Pair Reasoning – pupils compare answers and justify them using textual evidence.','Individual Check – pupils answer fresh questions independently.','Reflection + Extension – pupils summarise the key idea or connect it to a new prompt.']
            sec['AKTIVITI UTAMA']='\n\n'.join(f'Activity {i+1} ({m} minutes)\n{pool[i]}' for i,m in enumerate(slots))
            sec['PENUTUP']=f'{closure} minutes\nPupils give one answer with evidence; teacher checks the success criterion and follow-up needs.'
        else:
            sentences=1 if dur<=25 else (2 if dur<=40 else (3 if dur<=60 else 4))
            sec['OBJEKTIF PEMBELAJARAN']=f'By the end of the {dur}-minute lesson, pupils can demonstrate SP {sp} by producing at least {sentences} relevant sentence(s) about {focus} using the target language with appropriate support.'
            sec['KRITERIA KEJAYAAN']=f'Pupils produce at least {sentences} relevant sentence(s) meeting the task criteria.'
            sec['SET INDUKSI']=f'{induction} minutes\nTeacher uses one topic visual and elicits a small word/phrase bank for {focus}.'
            pool=['Build the Model – teacher and pupils construct one sentence together.','Language Bank – pupils select useful vocabulary/structures and test them orally.','Plan and Write – pupils organise ideas and produce their own response.','Peer Check – pupils use a short checklist to identify one strength and one improvement.','Revise and Extend – pupils improve accuracy and add relevant detail.','Independent Evidence – pupils produce a fresh response independently.','Share + Reflect – selected pupils share; class identifies successful language features.']
            sec['AKTIVITI UTAMA']='\n\n'.join(f'Activity {i+1} ({m} minutes)\n{pool[i]}' for i,m in enumerate(slots))
            sec['PENUTUP']=f'{closure} minutes\nOne or two pupils share a response; teacher checks the success criterion and identifies follow-up support.'
    else:
        # Subject-aware, multi-SP-aware local RPH. Avoid generic placeholders in teacher-facing output.
        sp_codes=[str(x).strip() for x in (s.get('grouped_sp_codes') or s.get('selected_sp_codes') or []) if str(x).strip()]
        sp_texts=[str(x).strip() for x in (s.get('grouped_sp_texts') or []) if str(x).strip()]
        if not sp_codes and str(s.get('sp_code') or '').strip():
            sp_codes=[x.strip() for x in str(s.get('sp_code') or '').split(';') if x.strip()]
        if not sp_texts and str(s.get('sp_text') or '').strip():
            sp_texts=[str(s.get('sp_text')).strip()]
        sp_label=', '.join(sp_codes) if sp_codes else str(s.get('sp_code') or '')
        content='; '.join(sp_texts) if sp_texts else focus
        lower=(focus+' '+content).lower()

        # Build measurable objectives from the actual selected standards.
        if 'prisma' in lower:
            sec['OBJEKTIF PEMBELAJARAN']=(f'Pada akhir pembelajaran selama {dur} minit, murid dapat mengenal pasti prisma segi empat sama, '
                'prisma segi empat tepat dan prisma segi tiga serta menyatakan ciri setiap prisma berdasarkan permukaan, tapak, bucu dan tepi dengan betul.')
            sec['KRITERIA KEJAYAAN']='Murid mengenal pasti sekurang-kurangnya 3 jenis prisma dengan betul dan melengkapkan jadual ciri prisma dengan sekurang-kurangnya 4 daripada 5 maklumat tepat.'
            sec['PENGETAHUAN SEDIA ADA']='Murid pernah melihat dan memegang objek harian berbentuk tiga dimensi seperti kotak, bekas dan bongkah.'
            sec['BAHAN BANTU MENGAJAR']='Buku teks, model prisma segi empat sama, prisma segi empat tepat dan prisma segi tiga, kotak pembungkusan, kad nama bentuk, kad ciri, jadual ciri prisma dan papan mini.'
            sec['SET INDUKSI']=(f'{induction} minit\n1. Guru menunjukkan sebuah kotak dan satu model prisma segi tiga tanpa menyebut nama bentuk.\n'
                '2. Murid memerhati, memegang dan menyatakan persamaan/perbezaan yang dapat dilihat.\n'
                f'3. Guru mengaitkan respons murid dengan SP {sp_label}.')
            pool=[
                'Kenali Prisma – Guru menunjukkan tiga model prisma. Murid memadankan kad nama prisma segi empat sama, prisma segi empat tepat dan prisma segi tiga pada model yang betul serta menerangkan petunjuk yang digunakan.',
                'Bongkar Ciri Prisma – Dalam pasangan, murid memegang dan memusing model. Mereka mengira serta merekod bilangan permukaan, tapak, bucu dan tepi dalam jadual ciri. Guru membimbing murid membezakan permukaan dengan tapak.',
                'Stesen Klasifikasi – Kumpulan mengelaskan beberapa model/objek kepada prisma segi empat sama, prisma segi empat tepat, prisma segi tiga atau bukan contoh yang dipelajari. Setiap kumpulan mesti memberi sebab berdasarkan ciri, bukan rupa semata-mata.',
                'Kad Misteri – Seorang murid mengambil kad ciri tanpa menunjukkan nama bentuk. Rakan menentukan jenis prisma daripada maklumat permukaan, tapak, bucu dan tepi serta memberikan justifikasi.',
                'Aplikasi Objek Harian – Murid memilih objek/kotak yang disediakan, menentukan prisma yang sepadan dan melabel sekurang-kurangnya satu permukaan, satu tapak, satu bucu dan satu tepi pada gambar/model.',
                'PBD Individu – Murid mengenal pasti tiga gambar/model prisma dan melengkapkan jadual ciri secara individu. Guru merekod penguasaan bagi SP yang dipilih dan memberi bimbingan segera kepada murid yang masih keliru.',
                'Cabaran Cipta Petunjuk – Murid menulis atau menyebut tiga petunjuk ciri bagi satu prisma tanpa menyatakan namanya. Rakan meneka bentuk dan menyemak petunjuk menggunakan model.'
            ]
            sec['AKTIVITI UTAMA']='\n\n'.join(f'Aktiviti {i+1} ({m} minit)\n{pool[i]}' for i,m in enumerate(slots))
            sec['PENUTUP']=(f'{closure} minit\n1. Guru menunjukkan satu model secara rawak; murid menulis nama prisma dan dua cirinya pada papan mini.\n'
                '2. Guru menyemak jawapan berdasarkan kriteria kejayaan dan mengenal pasti murid untuk pemulihan/pengayaan.')
            sec['PENTAKSIRAN']='Pemerhatian semasa manipulasi model, semakan jadual ciri, justifikasi lisan semasa klasifikasi dan exit ticket individu berdasarkan SP yang dipilih.'
        else:
            # Generic fallback still uses the real standards and named focus; no \"Fokus Mingguan\"/\"tugasan sasaran\" wording.
            action='menunjukkan penguasaan'
            if sp_texts:
                action='melaksanakan kemahiran yang dinyatakan dalam Standard Pembelajaran terpilih'
            sec['OBJEKTIF PEMBELAJARAN']=(f'Pada akhir pembelajaran selama {dur} minit, murid dapat {action} bagi {focus} melalui aktiviti berpandu dan tugasan individu yang merangkumi SP {sp_label}.')
            sec['KRITERIA KEJAYAAN']=f'Murid menyelesaikan sekurang-kurangnya 80% tugasan yang mengukur SP {sp_label} dengan betul dan dapat menerangkan sekurang-kurangnya satu jawapan/strategi.'
            sec['SET INDUKSI']=(f'{induction} minit\n1. Guru menunjukkan contoh, objek atau situasi sebenar berkaitan {focus}.\n'
                f'2. Murid memberi respons berdasarkan pengetahuan sedia ada dan guru menghubungkannya dengan SP {sp_label}.')
            pool=[
              f'Penerokaan – Guru memodelkan satu contoh khusus {focus}. Murid menggunakan BBM yang disenaraikan untuk mengenal pasti konsep, ciri atau langkah yang diperlukan oleh SP {sp_label}.',
              f'Latihan berpandu – Murid menyelesaikan tugasan bertahap berkaitan {focus} secara pasangan. Guru menyemak miskonsepsi dan meminta murid menerangkan sebab atau strategi.',
              f'Aktiviti kolaboratif – Murid melaksanakan kad tugasan/stesen yang mengukur kandungan SP {sp_label}, membandingkan jawapan dan memberikan justifikasi sebelum semakan kelas.',
              f'Aplikasi – Murid menggunakan pengetahuan {focus} dalam situasi baharu atau konteks harian dan memilih strategi yang sesuai.',
              f'Pengukuhan berbeza aras – Murid menerima tugasan sokongan, standard atau cabaran berdasarkan bukti penguasaan semasa bagi SP {sp_label}.',
              f'PBD individu – Murid melengkapkan tugasan baharu secara individu yang mengukur semua SP terpilih ({sp_label}); guru merekod bukti penguasaan dan kesilapan utama.',
              f'Pengayaan/refleksi – Murid menghasilkan satu contoh atau penyelesaian sendiri berkaitan {focus} dan menerangkan mengapa jawapan tersebut menepati konsep.'
            ]
            sec['AKTIVITI UTAMA']='\n\n'.join(f'Aktiviti {i+1} ({m} minit)\n{pool[i]}' for i,m in enumerate(slots))
            sec['PENUTUP']=(f'{closure} minit\n1. Murid menjawab satu exit ticket khusus berkaitan {focus}.\n'
                f'2. Guru menyemak bukti bagi SP {sp_label} dan menentukan tindakan pemulihan atau pengayaan.')
            sec['PENTAKSIRAN']=f'Pemerhatian, semakan hasil aktiviti dan tugasan individu yang mengukur SP {sp_label} berdasarkan kriteria kejayaan.'

    # Rebuild in canonical headings so the existing PDF renderer can translate English labels.
    order=['MATA PELAJARAN','TAHUN/TINGKATAN','TAJUK','STANDARD KANDUNGAN','STANDARD PEMBELAJARAN','OBJEKTIF PEMBELAJARAN','KRITERIA KEJAYAAN','PENGETAHUAN SEDIA ADA','BAHAN BANTU MENGAJAR','EMK / NILAI','KBAT / PAK21','PENTAKSIRAN','SET INDUKSI','AKTIVITI UTAMA','PENUTUP','PEMULIHAN / PENGAYAAN','REFLEKSI']
    return '\n'.join(f'{k}: {sec.get(k,"")}' for k in order if sec.get(k,''))

def generate_v3(cid, s, regen_cb):
    # Prevent Telegram webhook retries / double taps from launching duplicate AI jobs.
    with _runtime_lock:
        if cid in _processing_chats:
            send(cid, '⏳ <b>RPH masih sedang dijana.</b>\n\nCikgu tak perlu tekan lagi. Tunggu sehingga proses siap.' if s.get('task') == 'rph' else '⏳ <b>Worksheet masih sedang dijana.</b>\n\nCikgu tak perlu tekan lagi. Tunggu sehingga proses siap.')
            return
        _processing_chats.add(cid)

    try:
        # Fresh seed on every generation, including Jana Semula.
        if s.get('task') in ('worksheet','rph'):
            s['variation_seed'] = secrets.token_hex(4)
        send(cid, ('⚡ <b>Sedang jana RPH...</b>' if s.get('task') == 'rph' else '⚡ <b>Sedang jana worksheet...</b>') + '\n<i>Cikgu tunggu beberapa saat.</i>')
        try:
            if s.get('task') == 'rph' and s.get('sk_code') and s.get('sp_code'):
                # RPH sengaja dijana semula daripada bank pedagogi supaya aktiviti tidak berulang.
                result = _duration_fit_rph_text(_local_rph_text(s), s)
                _rph_cache_put(s, result)
            elif _can_generate_zero_cost(s):
                print('Hybrid zero-cost local generator: Matematik > Darab > Konsep darab', flush=True)
                result = _local_concept_darab_worksheet(s)
            else:
                result = gemini_generate(build_ai_prompt(s), max_output_tokens=_worksheet_output_token_budget(s))
            result = _hybrid_postprocess_worksheet(result, s)
            state.setdefault(cid,{})['last_result'] = result
            state[cid]['last_result_context'] = s

            # Bahan tidak dipaparkan sebagai teks dalam Telegram; terus tawarkan fail siap.
            ready_label = 'RPH siap!' if s.get('task') == 'rph' else 'Worksheet siap!'
            if s.get('task') == 'rph':
                kb=[[{'text':'📄 Dapatkan PDF','callback_data':'file_pdf'}]] + _integrated_material_buttons('rph') + [
                    [{'text':'🔄 Jana Semula RPH','callback_data':regen_cb}],
                    [{'text':'🏠 Menu Utama','callback_data':'home'}]]
            else:
                kb=[[{'text':'📄 Dapatkan PDF','callback_data':'file_pdf'}]] + _integrated_material_buttons('worksheet') + [
                    [{'text':'🔄 Jana Semula','callback_data':regen_cb}],
                    [{'text':'🏠 Menu Utama','callback_data':'home'}]]
            send(cid,f'✅ <b>{ready_label}</b>\n\nTekan PDF atau sambung jana bahan lain dengan pilihan kurikulum yang sama:',kb)
        except Exception as e:
            err = str(e)
            print('Gemini error:', repr(e), flush=True)
            # Show a safe, short technical reason so failures are diagnosable from Telegram too.
            safe = html.escape(err[:220])
            send(cid,
                 '⚠️ <b>Janaan AI belum berjaya.</b>\n\n'
                 f'<code>{safe}</code>\n\n'
                 'Tekan <b>Cuba Lagi</b>. Sistem akan menggunakan model alternatif secara automatik.',
                 [[{'text':'🔄 Cuba Lagi','callback_data':regen_cb}],
                  [{'text':'🏠 Menu Utama','callback_data':'home'}]])
    finally:
        with _runtime_lock:
            _processing_chats.discard(cid)



WORKSHEET_LEVELS = [
    ('aras1','Aras 1 – Pemulihan / Asas','easy'),
    ('aras2','Aras 2 – Sederhana','medium'),
    ('aras3','Aras 3 – Penguasaan','hard'),
    ('aras4','Aras 4 – Pengayaan / KBAT','kbat'),
]


def _year1_math_generation_rules(s):
    if str(s.get('year','')).strip() != 'Tahun 1':
        return ''
    if str(s.get('subject','')).strip().lower() != 'matematik':
        return ''
    return """
PERATURAN WAJIB MATEMATIK TAHUN 1:
- Utamakan angka dan simbol matematik sebagai jawapan apabila sesuai.
- PAPARAN PECAHAN: Dalam lembaran murid, jangan gunakan slash '/' sebagai garis pecahan.
  Pecahan angka mesti dipaparkan secara menegak: pengangka di atas, garis lurus mendatar, penyebut di bawah.
  Untuk pilihan jawapan, renderer akan menukar bentuk seperti 1/4 kepada pecahan bertingkat secara automatik.
  Jika menjana token, gunakan [FRACTION_NUM: 1, 4].
- Bagi pecahan Tahun 1, utamakan 1/2, 1/4, 2/4 dan 3/4. Ejaan digunakan hanya apabila soalan memang menguji nama pecahan.
- Ayat pendek, konkrit dan mudah dibaca.
- ARAS 1 KHAS PECAHAN: JANGAN guna ayat soalan.
  Paparkan HANYA nombor soalan + pecahan angka bertingkat sebagai rangsangan, kemudian pilihan jawapan A/B/C dalam bentuk RAJAH.
  Format wajib contoh:
  1. [FRACTION_NUM: 1, 2]
  A. [FRACTION_BAR: 1, 2]
  B. [FRACTION_BAR: 1, 4]
  C. [FRACTION_BAR: 3, 4]
  Maksudnya murid melihat PECAHAN ANGKA dan memilih RAJAH yang sepadan.
  Jangan tulis "Pilih", "Rajah manakah", "Apakah pecahan", "satu perdua", "satu perempat" atau ayat penerangan pada item Aras 1.
  Gunakan hanya pecahan dalam skop SP, dan variasikan kedudukan jawapan betul.
- ARAS 2: satu ayat pendek. Elakkan cerita panjang kecuali konteks benar-benar diperlukan.
- Aras 1 dan 2: utamakan arahan mudah seperti Pilih, Padankan, Lorek, Bulatkan, Tulis dan Kira.
- Aras 3: aplikasi mudah dalam situasi harian dan perbandingan representasi dengan bahasa ringkas.
- Aras 4/KBAT: naikkan tahap PEMIKIRAN, bukan tahap bahasa. Gunakan visual, nombor, perbandingan mudah,
  cari kesilapan mudah, pilih antara dua penyelesaian, atau situasi harian bukan rutin yang pendek.
- Contoh KBAT sesuai Tahun 1: tunjuk dua rajah 1/2 dan 2/4, tanya sama ada bahagian sama banyak dan minta sebab ringkas.
- Jangan gunakan alasan pilihan jawapan yang panjang atau abstrak.
- Untuk SP 3.1.1, jangan keluar daripada 1/2, 1/4, 2/4 dan 3/4 semata-mata untuk menjadikan soalan lebih sukar.
- Jika murid diminta melukis/melorek, sediakan bentuk kosong dan jangan beri jawapan siap.
- Aras 1/2: jika rajah sudah membawa maklumat, arahan cukup ringkas; jangan ulang bilangan bahagian/lorekan dalam ayat panjang.
- Jangan sebut "rajah di bawah" tanpa token visual sebenar.
"""

def _four_level_worksheet_prompt(s):
    _tpl=worksheet_template_profile(s)
    q = int(s.get('worksheet_questions', 8) or 8)
    base = dict(s)
    base['difficulty'] = 'mixed'
    base['worksheet_pack_4levels'] = False
    common = build_ai_prompt(base)
    extra = (
        "\n\nARAHAN WAJIB PAKEJ 4 ARAS — ARAHAN INI MENGATASI ARAHAN SATU WORKSHEET DI ATAS:\n"
        f"Hasilkan EMPAT worksheet berasingan untuk SK/SP yang SAMA. Setiap aras mesti mengandungi tepat {q} soalan dan mesti berbeza secara bermakna, bukan sekadar menukar nombor.\n"
        "Gunakan penanda tepat ini pada baris sendiri:\n===ARAS_1===\n===ARAS_2===\n===ARAS_3===\n===ARAS_4===\n\n"
        "ARAS 1 — PEMULIHAN / ASAS: untuk Matematik Tahun 1 Pecahan, item mesti nombor pecahan → pilih rajah; tanpa ayat soalan. Gunakan [FRACTION_NUM] pada soalan dan [FRACTION_BAR]/[FRACTION_SET] pada pilihan A-C.\n"
        "ARAS 2 — SEDERHANA: penguasaan standard SP untuk majoriti murid.\n"
        "ARAS 3 — PENGUASAAN: kurang bantuan, aplikasi dan penyelesaian masalah yang lebih mencabar tetapi masih dalam skop SP.\n"
        "ARAS 4 — PENGAYAAN / KBAT: penaakulan, situasi baharu, nombor hilang, justifikasi atau soalan terbuka yang sesuai dengan Tahun/Tingkatan dan masih dalam skop SP.\n\n"
        "Setiap blok selepas penanda mesti menjadi worksheet lengkap yang boleh dicetak sendiri. Jangan tulis penerangan tentang perbezaan aras; terus beri kandungan worksheet.\n"
        "FORMAT TAHAP DUA: apabila Tahun 4-6, ikut DNA format UASA KPM 2025 bagi subjek tersebut tetapi skala jumlah soalan mengikut bilangan worksheet yang diminta; jangan paksa semua bahagian jika SP hanya sesuai dengan sebahagian format. Matematik kekal subjektif SRT/SRTb, bukan MCQ generik. Sains gunakan A objektif, B OPB/SRT dan C berstruktur apabila sesuai. BM gunakan A-D mengikut tatabahasa/pemahaman/respons/penulisan. BI gunakan struktur Parts 1-7 apabila kemahiran SP berkaitan. "
        "FORMAT TAHAP SATU: Tahun 1-3 bukan UASA; gunakan gaya buku latihan/PBD yang jelas, visual dan mesra umur. "
        "KELENGKAPAN SOALAN WAJIB: setiap item mesti mempunyai semua maklumat yang diperlukan untuk dijawab. "
        "Jangan tulis 'berdasarkan rajah/gambar/petikan/situasi yang diberikan' jika bahan itu tidak benar-benar disertakan. "
        "Untuk pemahaman BM/BI, sertakan petikan lengkap sebelum soalan. Untuk Sains, sertakan situasi, pemerhatian/data atau rajah yang diperlukan. "
        "Untuk Matematik, sertakan semua nombor, jadual/rajah dan ruang kerja yang diperlukan. Objektif mesti mempunyai empat pilihan A-D.\n"
        f"PROFIL REKA BENTUK: {_tpl['band']}. Gunakan campuran format yang sesuai daripada: {', '.join(_tpl['formats'])}. "
        "Jangan jadikan semua item baris teks yang seragam. Kekalkan susun atur kemas seperti buku latihan/kertas pentaksiran; gunakan kotak, jadual, rajah atau ruang kerja hanya apabila sesuai dengan kemahiran SP. "
        "Untuk Tahun 1-3 utamakan gaya latihan/PBD mesra umur. Untuk Tahun 4-6 gunakan struktur lebih formal berinspirasikan instrumen pentaksiran/UASA tanpa menyalin soalan sumber.\n"
        + _year1_math_generation_rules(s)
    )
    return common + extra


def _normalize_y1_fraction_option_numbers(s, worksheet_text):
    if str(s.get('year','')).strip() != 'Tahun 1' or str(s.get('subject','')).strip().lower() != 'matematik':
        return worksheet_text
    if 'pecahan' not in (str(s.get('topic',''))+' '+str(s.get('subtopic',''))).lower():
        return worksheet_text
    mapping={'satu perdua':'1/2','setengah':'1/2','satu perempat':'1/4',
             'dua perempat':'2/4','tiga perempat':'3/4'}
    out=[]
    for line in str(worksheet_text or '').splitlines():
        if re.match(r'^\s*[A-D][\.\)]\s+',line,re.I):
            for word,num in mapping.items():
                line=re.sub(r'\b'+re.escape(word)+r'\b',num,line,flags=re.I)
        out.append(line)
    return '\n'.join(out)

def _split_four_level_worksheet(text):
    markers=['===ARAS_1===','===ARAS_2===','===ARAS_3===','===ARAS_4===']
    if not text:
        return {}
    positions=[]
    for m in markers:
        idx=text.find(m)
        if idx<0:
            return {}
        positions.append(idx)
    out={}
    for i,m in enumerate(markers):
        start=positions[i]+len(m)
        end=positions[i+1] if i+1<len(markers) else len(text)
        out[f'aras{i+1}']=text[start:end].strip()
    return out

def _generate_four_level_worksheets(s):
    results={}
    if _can_generate_zero_cost(s):
        for key,label,diff in WORKSHEET_LEVELS:
            ctx=dict(s); ctx['task']='worksheet'; ctx['difficulty']=diff; ctx['worksheet_pack_4levels']=False
            results[key]=_hybrid_postprocess_worksheet(_local_concept_darab_worksheet(ctx),ctx)
        return results

    # Local-first: tambah/tolak Matematik dijana tanpa API apabila rule tempatan sesuai.
    local_pack = local_first_generate_worksheet(s, n_each=int(s.get('worksheet_questions') or 8))
    if local_pack:
        for (key,label,diff), pack in zip(WORKSHEET_LEVELS, local_pack):
            ctx=dict(s); ctx['task']='worksheet'; ctx['difficulty']=diff; ctx['worksheet_pack_4levels']=False
            lines=[pack.get('title') or label, 'Arahan: Jawab semua soalan.']
            for i,q in enumerate(pack.get('questions') or [],1):
                lines.append(f"{i}. {q}")
                if ('matematik' in str(ctx.get('subject','')).lower()) and (diff in ('hard','kbat') or any(w in str(q).lower() for w in ['berapakah','terangkan','cara'])):
                    lines.append('[WORKLINES: 4]' if diff!='kbat' else '[WORKLINES: 6]')
            results[key]=_hybrid_postprocess_worksheet("\n".join(lines),ctx)
        if len(results)==4:
            return results

    raw=gemini_generate(_four_level_worksheet_prompt(s), max_output_tokens=max(8192, _worksheet_output_token_budget(s)*3))
    raw=_normalize_y1_fraction_option_numbers(s, raw)
    results=_split_four_level_worksheet(raw)
    if len(results)!=4:
        raise RuntimeError('Empat blok worksheet tidak lengkap.')
    issues=[]
    for key,val in results.items():
        issues += [f"{key}: {x}" for x in _worksheet_completeness_issues(val)]
    if issues:
        repaired=_repair_incomplete_four_level_worksheets(s,raw,issues)
        if len(repaired)!=4:
            raise RuntimeError('Empat blok worksheet tidak lengkap selepas pembaikan.')
        remaining=[]
        for key,val in repaired.items():
            remaining += [f"{key}: {x}" for x in _worksheet_completeness_issues(val)]
        if remaining:
            raise RuntimeError('Worksheet masih tidak lengkap: ' + '; '.join(remaining[:6]))
        results=repaired
    return results

def _inject_worksheet_differentiation_into_rph(text):
    if not text:
        return text
    is_english=('MATA PELAJARAN: English' in text or 'SUBJECT: English' in text)
    note=("\n5. Teacher distributes Level 1, 2, 3 or 4 worksheets according to pupils’ current level of mastery. Pupils may progress to the next level after demonstrating mastery of the assigned task.\n" if is_english else
          "\n")
    if is_english and 'CLOSURE' in text:
        return text.replace('CLOSURE', note+'CLOSURE',1)
    if 'PENUTUP' in text:
        return text.replace('PENUTUP', note+'PENUTUP',1)
    return text+note

def _merge_pdf_paths(paths, output_path):
    writer=PdfWriter()
    for pth in paths:
        writer.append(pth)
    with open(output_path,'wb') as f:
        writer.write(f)
    writer.close()
    return output_path

def create_four_level_worksheet_pdf(s, results, cid):
    temp_paths=[]
    try:
        for key,label,diff in WORKSHEET_LEVELS:
            ctx=dict(s); ctx['task']='worksheet'; ctx['difficulty']=diff; ctx['worksheet_pack_4levels']=False
            ctx['subtopic']=(ctx.get('subtopic') or 'Semua Subtopik') + ' | ' + label
            pth=create_pdf_file(ctx, results[key], f'{cid}_{key}')
            temp_paths.append(pth)
        out=os.path.join(tempfile.gettempdir(), f'{cid}_CikguLaju_Worksheet_4_Aras.pdf')
        return _merge_pdf_paths(temp_paths,out)
    finally:
        for pth in temp_paths:
            try:
                if os.path.exists(pth): os.remove(pth)
            except Exception:
                pass

