def _tt_upload_menu_v25281(cid):
    state.setdefault(cid,{})['waiting']='timetable_upload_v25281'
    return send(cid,'📤 <b>UPLOAD JADUAL WAKTU</b>\n\nHantar <b>gambar/screenshot (JPG/PNG)</b> atau <b>PDF</b> jadual waktu cikgu.\n\nCikguLaju akan baca <b>hari, masa, subjek dan kelas</b> sebagai draf. <b>Jadual sedia ada tidak akan berubah</b> sehingga cikgu semak dan tekan SAHKAN.',
        [[{'text':'✏️ Isi Manual','callback_data':'tt_add'}],[{'text':'⬅️ Jadual Waktu','callback_data':'timetable'}]])

def _telegram_media_bytes_v25281(m):
    _tt_diag_v25302('telegram_media_download_start')
    if m.get('photo'):
        item=(m.get('photo') or [])[-1]; fid=item.get('file_id'); mime='image/jpeg'
    else:
        doc=m.get('document') or {}; fid=doc.get('file_id'); mime=str(doc.get('mime_type') or 'application/octet-stream')
        fn=str(doc.get('file_name') or '').lower()
        if mime=='application/octet-stream' and fn.endswith('.pdf'): mime='application/pdf'
    if not fid: raise ValueError('Fail Telegram tidak mempunyai file_id.')
    if mime not in ('image/jpeg','image/png','image/webp','application/pdf'): raise ValueError('Gunakan JPG, PNG atau PDF sahaja.')
    r=requests.get(f'{API}/getFile',params={'file_id':fid},timeout=20)
    if not r.ok or not (r.json().get('ok') if r.content else False): raise RuntimeError('Telegram getFile gagal.')
    fp=(r.json().get('result') or {}).get('file_path')
    if not fp: raise RuntimeError('Telegram file_path tidak ditemui.')
    rr=requests.get(f'https://api.telegram.org/file/bot{BOT_TOKEN}/{fp}',timeout=40)
    if not rr.ok: raise RuntimeError('Fail jadual tidak dapat dimuat turun.')
    if len(rr.content)>12*1024*1024: raise ValueError('Fail terlalu besar. Maksimum 12 MB.')
    return rr.content,mime

def _gemini_timetable_extract_v25281(data,mime):
    import base64, json as _json
    prompt="""Baca jadual waktu guru Malaysia ini. Ekstrak HANYA waktu mengajar guru tersebut.
Pulangkan JSON tulen sahaja, tanpa markdown:
{"entries":[{"day":"Isnin","start":"07:40","end":"08:40","class_name":"3 Amanah","subject":"Matematik"}]}
Peraturan:
- day mesti salah satu Isnin, Selasa, Rabu, Khamis, Jumaat, Sabtu, Ahad.
- masa format 24 jam HH:MM.
- jangan reka data yang tidak jelas.
- abaikan rehat/perhimpunan/aktiviti yang bukan waktu mengajar jika bukan subjek.
- kekalkan nama kelas dan subjek sebagaimana dapat dibaca.
- jika sel kosong/tidak pasti, jangan masukkan entry itu."""
    models=[]
    for model in [GEMINI_MODEL]+list(GEMINI_FALLBACK_MODELS or []):
        if model and model not in models: models.append(model)
    last=None
    for model in models:
        try:
            url=f'https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent'
            payload={'contents':[{'role':'user','parts':[{'text':prompt},{'inline_data':{'mime_type':mime,'data':base64.b64encode(data).decode('ascii')}}]}],
                     'generationConfig':{'temperature':0.0,'maxOutputTokens':3500,'responseMimeType':'application/json'}}
            r=requests.post(url,headers={'Content-Type':'application/json','x-goog-api-key':GEMINI_API_KEY},json=payload,timeout=(15,GEMINI_TIMEOUT))
            if not r.ok: last=f'Gemini HTTP {r.status_code}'; continue
            parts=((r.json().get('candidates') or [{}])[0].get('content') or {}).get('parts') or []
            raw=''.join(str(x.get('text') or '') for x in parts).strip()
            raw=re.sub(r'^```(?:json)?\s*|\s*```$','',raw,flags=re.I|re.S).strip()
            return (_json.loads(raw).get('entries') or [])
        except Exception as e: last=str(e)
    raise RuntimeError(last or 'Jadual tidak dapat dibaca.')

def _norm_time_v25281(v):
    x=str(v or '').strip().replace('.',':'); m=re.fullmatch(r'(\d{1,2}):(\d{2})',x)
    if not m: return None
    h,mi=map(int,m.groups())
    return f'{h:02d}:{mi:02d}' if 0<=h<=23 and 0<=mi<=59 else None

def _prepare_timetable_draft_v25281(cid,raw_entries):
    days={x.lower():x for x in _TIMETABLE_DAYS}; classes=_profile_class_records(cid)
    cmap={re.sub(r'\s+',' ',str(r.get('name') or '').strip()).lower():r['name'] for r in classes}
    good=[]; unmatched=[]; seen=set()
    for x in raw_entries or []:
        day=days.get(str(x.get('day') or '').strip().lower()); start=_norm_time_v25281(x.get('start')); end=_norm_time_v25281(x.get('end'))
        cls=' '.join(str(x.get('class_name') or '').split()); sub=' '.join(str(x.get('subject') or '').split()); canonical=cmap.get(cls.lower())
        try: sm=int(start[:2])*60+int(start[3:]) if start else -1; em=int(end[:2])*60+int(end[3:]) if end else -1
        except Exception: sm=em=-1
        if not (day and start and end and em>sm and cls and sub): continue
        if not canonical: unmatched.append({'day':day,'start':start,'end':end,'class_name':cls,'subject':sub}); continue
        e={'day':day,'start':start,'end':end,'class_name':canonical,'subject':sub}; k=(day,start,end,canonical.lower(),sub.lower())
        if k not in seen: seen.add(k); good.append(e)
    order={d:i for i,d in enumerate(_TIMETABLE_DAYS)}; good.sort(key=lambda e:(order.get(e['day'],99),e['start'],e['class_name']))
    return good,unmatched

def _show_timetable_draft_v25281(cid,good,unmatched):
    ss=state.setdefault(cid,{}); ss['_tt_upload_draft_v25281']=good; ss['_tt_upload_unmatched_v25281']=unmatched; ss.pop('waiting',None)
    lines=['📋 <b>DRAF JADUAL DIKESAN</b>','']
    for e in good[:50]: lines.append(f"• {html.escape(e['day'])} {html.escape(e['start'])}–{html.escape(e['end'])} • {html.escape(e['class_name'])} • {html.escape(e['subject'])}")
    if not good: lines.append('Tiada waktu yang dapat dipadankan dengan kelas dalam profil.')
    if unmatched:
        lines += ['','⚠️ <b>Kelas belum sepadan dengan Profil:</b>']
        for e in unmatched[:15]: lines.append('• '+html.escape(f"{e['day']} {e['start']}–{e['end']} • {e['class_name']} • {e['subject']}"))
        lines.append('\nTambah/betulkan kelas dalam Profil atau upload semula. Item ini <b>tidak akan disimpan</b>.')
    lines += ['','Jadual lama masih belum diubah.']
    kb=[]
    if good: kb.append([{'text':'✅ SAHKAN & GANTI JADUAL','callback_data':'ttupload281_confirm'}])
    kb += [[{'text':'🔄 Upload Semula','callback_data':'ttupload281_start'},{'text':'✏️ Isi Manual','callback_data':'tt_add'}],[{'text':'❌ Batal','callback_data':'timetable'}]]
    return send(cid,'\n'.join(lines),kb)

def _handle_timetable_upload_v25281(cid,m):
    _tt_diag_v25302('upload_handler_start')
    try:
        send(cid,'🔎 <b>Sedang membaca jadual waktu…</b>\nJadual sedia ada belum diubah.')
        data,mime=_telegram_media_bytes_v25281(m); raw=_gemini_timetable_extract_v25281(data,mime)
        good,bad=_prepare_timetable_draft_v25281(cid,raw); return _show_timetable_draft_v25281(cid,good,bad)
    except Exception as e:
        print('v25.281 timetable upload:',repr(e),flush=True); state.setdefault(cid,{})['waiting']='timetable_upload_v25281'
        return send(cid,'⚠️ Jadual belum dapat dibaca dengan yakin. <b>Tiada data lama diubah.</b>\n\nCuba gambar/PDF yang lebih jelas atau gunakan Isi Manual.',
                    [[{'text':'🔄 Cuba Upload Lagi','callback_data':'ttupload281_start'}],[{'text':'✏️ Isi Manual','callback_data':'tt_add'},{'text':'⬅️ Kembali','callback_data':'timetable'}]])

def _commit_timetable_draft_v25281(cid):
    ss=state.setdefault(cid,{}); draft=list(ss.get('_tt_upload_draft_v25281') or [])
    if not draft: return _timetable_menu(cid,'⚠️ Draf upload sudah tiada. Upload semula.')
    rows=_profile_class_records(cid); byname={str(r.get('name') or '').strip().lower():i for i,r in enumerate(rows)}
    for r in rows: r['timetable']=[]
    for e in draft:
        ci=byname.get(str(e.get('class_name') or '').strip().lower())
        if ci is not None: rows[ci].setdefault('timetable',[]).append({'day':e['day'],'start':e['start'],'end':e['end'],'subject':e['subject']})
    _save_profile_class_records(cid,rows); ss.pop('_tt_upload_draft_v25281',None); ss.pop('_tt_upload_unmatched_v25281',None)
    return _timetable_menu(cid,'✅ <b>Jadual upload telah disahkan dan disimpan.</b>')
# ===== END v25.281 HELPERS =====

@app.route('/webhook', methods=['POST'])
def webhook():
    u = request.get_json(silent=True) or {}
    update_id = u.get('update_id')

    # Telegram retries a webhook if the HTTP response is slow. Ignore duplicate deliveries.
    if update_id is not None:
        with _runtime_lock:
            if update_id in _seen_updates:
                return jsonify({'ok':True, 'duplicate':True})
            _seen_updates.add(update_id)
            if len(_seen_updates) > 5000:
                # Bound memory usage; update IDs are monotonically increasing.
                for old_id in sorted(_seen_updates)[:2500]:
                    _seen_updates.discard(old_id)

    if 'callback_query' in u:
        c = u['callback_query']
        try:
            requests.post(
                f'{API}/answerCallbackQuery',
                json={'callback_query_id':c['id']},
                timeout=5
            )
        except Exception as e:
            print('answerCallbackQuery error:', repr(e), flush=True)

        cid = c['message']['chat']['id']
        _upsert_user(c.get('from',{}), cid)
        # Remember the message that owns the inline keyboard so multi-select menus
        # can be updated in place instead of sending another message on each tap.
        state.setdefault(cid,{})['_callback_message_id'] = c.get('message',{}).get('message_id')
        data = c.get('data','')
        # Return HTTP 200 immediately; long work continues in background.
        def _safe_callback():
            try:
                callback(cid, data)
            except Exception as e:
                print('CALLBACK ERROR:',data,repr(e),flush=True)
                try:
                    send(cid,'⚠️ Tindakan tidak berjaya diproses. Sila cuba semula.')
                except Exception:
                    pass
        threading.Thread(target=_safe_callback, daemon=True).start()

    elif 'message' in u:
        m = u['message']
        cid = m['chat']['id']
        _upsert_user(m.get('from',{}), cid)
        txt=(m.get('text') or '').strip()
        if txt == '/myid':
            send(cid,f'🆔 Telegram ID cikgu: <code>{cid}</code>')
        elif txt == '/access':
            send(cid,_user_access_text(cid),[[{'text':'💳 BAYAR RM5.00 / 30 HARI','callback_data':'subscribe_500'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        elif txt == '/pay':
            send_subscription_payment(cid)
        elif txt == '/admin':
            _admin_panel(cid)
        elif txt == '/admintest':
            if _is_admin(cid):
                send(cid,'✅ Sambungan admin CikguLaju berfungsi. Bukti bayaran akan dihantar terus ke chat ini.')
            else:
                send(cid,'⛔ Arahan ini hanya untuk admin CikguLaju.')
        elif txt.startswith('/activate'):
            if not _is_admin(cid):
                send(cid,'⛔ Arahan ini hanya untuk admin CikguLaju.')
            else:
                parts=txt.split()
                if len(parts)<2 or not re.fullmatch(r'-?\d+',parts[1]):
                    send(cid,'Format: <code>/activate TELEGRAM_ID</code> atau <code>/activate TELEGRAM_ID 60</code>')
                else:
                    target=parts[1]; days=30
                    if len(parts)>=3:
                        try: days=int(parts[2])
                        except Exception: days=30
                    until=_activate_access(target,days,cid)
                    send(cid,f'✅ Akses pengguna <code>{target}</code> diaktifkan selama <b>{days} hari</b>.\nAktif sehingga: <b>{until.strftime("%d/%m/%Y %H:%M")}</b>')
                    try:
                        send(target,f'✅ <b>CIKGULAJU TELAH DIAKTIFKAN</b>\n\nAkses cikgu aktif selama <b>{days} hari</b>.\nAktif sehingga: <b>{until.strftime("%d/%m/%Y")}</b>\n\nCikgu boleh terus menggunakan CikguLaju sekarang.',
                             [[{'text':'✨ Jana Bahan','callback_data':'quick'}],[{'text':'👤 Akaun Saya','callback_data':'account'}]])
                    except Exception: pass
        elif txt.startswith('/status'):
            if not _is_admin(cid):
                send(cid,'⛔ Arahan ini hanya untuk admin CikguLaju.')
            else:
                parts=txt.split()
                if len(parts)<2:
                    send(cid,'Format: <code>/status TELEGRAM_ID</code>')
                else:
                    target=parts[1]; a=_access_info(target)
                    send(cid,f'👤 Pengguna: <code>{target}</code>\nStatus akses: <b>{"AKTIF" if a["active"] else a["status"].upper()}</b>\nAktif sehingga: <b>{str(a.get("access_until") or "-")[:19]}</b>')
        elif txt.startswith('/deactivate'):
            if not _is_admin(cid):
                send(cid,'⛔ Arahan ini hanya untuk admin CikguLaju.')
            else:
                parts=txt.split()
                if len(parts)<2:
                    send(cid,'Format: <code>/deactivate TELEGRAM_ID</code>')
                else:
                    target=parts[1]; _deactivate_access(target,cid)
                    send(cid,f'✅ Akses pengguna <code>{target}</code> telah dinyahaktifkan.')
                    try: send(target,'🔒 <b>Akses CikguLaju telah dinyahaktifkan.</b>\nJika ini tidak sepatutnya berlaku, sila hubungi admin.')
                    except Exception: pass
        elif txt in ('/start','/menu','☰ Menu','Menu'):
            state[cid] = {}
            menu(cid, show_persistent=True)
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'timetable_slot_text':
            return _timetable_save_from_text(cid,(m.get('text') or '').strip())
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'beta_feedback':
            feedback=(m.get('text') or '').strip()
            if not feedback:
                send(cid,'⚠️ Taip komen atau cadangan cikgu dahulu.')
            else:
                _save_beta_feedback(cid,feedback)
                state[cid]={}
                send(cid,'✅ <b>Terima kasih!</b>\n\nKomen/cadangan cikgu sudah diterima untuk penambahbaikan CikguLaju.',[[{'text':'💬 Hantar Lagi','callback_data':'beta_feedback'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'profile_name':
            name=(m.get('text') or '').strip()[:80]
            if not name:
                send(cid,'⚠️ Masukkan nama atau panggilan yang cikgu mahu gunakan.')
            else:
                state.setdefault(cid,{})['profile_name']=name
                state[cid].pop('waiting',None)
                _profile_choose_state(cid)
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'profile_edit_name':
            value=' '.join((m.get('text') or '').strip().split())[:80]
            if value:
                _save_teacher_profile(cid,display_name=value)
            state[cid]={}
            return _profile_edit_menu(cid)
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'profile_edit_state':
            value=' '.join((m.get('text') or '').strip().split())[:80]
            if value:
                _save_teacher_profile(cid,state_name=value)
            state[cid]={}
            return _profile_edit_menu(cid)
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'tt286_class_rename':
            _tt286_apply_rename(cid,m.get('text','').strip())
            return jsonify({'ok':True})
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'profile_class_add_name':
            ss=state.setdefault(cid,{})
            yl=str(ss.get('_profile_add_year_v2398') or '').strip()
            suffix=' '.join((m.get('text') or '').strip().split())[:50]
            # Teacher types only the class name (e.g. Amanah). Strip an accidental
            # repeated level number/prefix so the stored display stays canonical.
            num=_year_number_v2393(yl) or ''
            suffix=re.sub(r'^\s*(?:tahun|tingkatan)?\s*'+re.escape(num)+r'\s*[-–:]?\s*','',suffix,flags=re.I).strip() if num else suffix
            name=(f'{num} {suffix}'.strip())[:60]
            rows=_profile_class_records(cid)
            if yl and suffix and name.lower() not in [r['name'].lower() for r in rows]:
                rows.append({'name':name,'students':None,'year_label':yl})
                _save_profile_class_records(cid,rows)
                # Preserve selected row context while clearing temporary add state.
                state[cid]={'profile_class_idx':len(rows)-1}
                return send(cid,
                            f"✅ Kelas <b>{html.escape(name)}</b> ditambah sebagai <b>{html.escape(yl)}</b>.\n\nSekarang pilih bilangan murid.",
                            _profile_student_count_keyboard())
            if not yl:
                state[cid]={}
                return _profile_class_manage_menu(cid,'⚠️ Tahun/Tingkatan belum dipilih. Tambah kelas semula.')
            return send(cid,'ℹ️ Nama kelas itu sudah ada atau tidak sah. Taip nama kelas sahaja, contoh <code>Amanah</code>.')
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'profile_class_students_custom':
            raw=(m.get('text') or '').strip()
            try:
                count=int(raw)
            except Exception:
                count=0
            if not 1<=count<=100:
                return send(cid,'Masukkan nombor antara <b>1 hingga 100</b>.')
            return _profile_set_student_count(cid,count)
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'profile_class_rename':
            ss=state.setdefault(cid,{})
            idx=ss.get('profile_class_idx')
            rows=_profile_class_records(cid)
            suffix=' '.join((m.get('text') or '').strip().split())[:50]
            try:
                idx=int(idx)
            except Exception:
                return _profile_class_manage_menu(cid)
            if 0<=idx<len(rows) and suffix:
                yl=str(rows[idx].get('year_label') or '').strip()
                num=_year_number_v2393(yl) or _class_level_guess_v2393(rows[idx].get('name')) or ''
                # Rename follows the same rule as Add Class: type suffix only.
                if num:
                    suffix=re.sub(r'^\s*(?:tahun|tingkatan)?\s*'+re.escape(num)+r'\s*[-–:]?\s*','',suffix,flags=re.I).strip()
                name=(f'{num} {suffix}'.strip())[:60]
                if not suffix:
                    return send(cid,'⚠️ Taip nama kelas sahaja, contoh <code>Amanah</code>.')
                if any(i!=idx and str(r.get('name') or '').lower()==name.lower() for i,r in enumerate(rows)):
                    return send(cid,'Nama kelas itu sudah wujud. Taip nama lain.')
                rows[idx]['name']=name
                _save_profile_class_records(cid,rows)
                ss.pop('waiting',None)
                return _profile_class_item_menu(cid,idx)
            return _profile_class_manage_menu(cid)
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'profile_classes':
            raw=(m.get('text') or '').strip()
            records=_parse_profile_class_records(raw)
            _save_profile_class_records(cid,records)
            state[cid]={}
            send(cid,'✅ <b>Profil Cikgu siap.</b>\n\n'+_profile_text(cid),[[{'text':'✨ Jana Bahan','callback_data':'quick'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        elif m.get('text') and state.get(cid,{}).get('waiting') == 'textbook_page':
            ss=state.setdefault(cid,{})
            raw=(m.get('text') or '').strip()
            if not re.fullmatch(r'\d{1,4}',raw):
                send(cid,'⚠️ Masukkan nombor muka surat sahaja, contoh <code>98</code>.')
            else:
                page_no=int(raw)
                _clear_textbook_standard_state(ss)
                # Exact SOW page mapping takes priority over broad unit ranges. This is
                # essential for supplementary English Plus / Get Smart Plus pages such
                # as p.92, p.106, p.117 and p.119 that sit outside the normal unit range.
                exact=_textbook_exact_page_standards(ss.get('year',''),ss.get('subject',''),page_no)
                lesson_meta=_textbook_exact_page_lessons(ss.get('year',''),ss.get('subject',''),page_no)
                ref=_textbook_page_lookup(ss.get('year',''),ss.get('subject',''),page_no)
                if exact:
                    seed=exact[0]
                    ss.pop('waiting',None)
                    ss['rph_mode']='fast_textbook'
                    ss['textbook_page']=page_no
                    ss['textbook_book_title']=str(seed.get('book_title') or (ref or {}).get('book_title') or '')
                    ss['textbook_page_start']=seed.get('page_start')
                    ss['textbook_page_end']=seed.get('page_end')
                    ss['textbook_reference_id']=(ref or {}).get('id')
                    ss['topic']=str(seed.get('unit_title') or (ref or {}).get('topic') or '').strip()
                    ss['subtopic']=f'Muka surat {page_no}'
                    groups=_textbook_page_focus_groups(exact,lesson_meta)
                    if len(groups) > 1:
                        # One page may serve a four-skill lesson and Language Awareness.
                        # Ask only for the real SOW focus; never expose a manual SK/SP selector.
                        ss['textbook_page_groups']=groups
                        kb=[]
                        for i,g in enumerate(groups):
                            focus=str(g.get('focus') or '').strip()
                            lesson=str(g.get('lesson_no') or '').strip()
                            label='🎯 '+(focus or ('Lesson '+lesson if lesson else f'Pilihan {i+1}'))
                            if lesson and focus:
                                label += f' · Lesson {lesson}'
                            kb.append([{'text':label[:60],'callback_data':f'tbpg_{i}'}])
                        kb.append([{'text':'📖 Masukkan Muka Surat Lain','callback_data':'fast_use_textbook'}])
                        send(cid,f"📖 <b>Muka surat {page_no}</b> digunakan untuk lebih daripada satu fokus dalam SOW.\n\nPilih fokus yang cikgu mahu ajar. Untuk lesson kemahiran, SK/SP akan diisi automatik; Language Awareness akan terus menggunakan grammar/fokus SOW tanpa mencipta SP.",kb)
                    elif groups and groups[0].get('kind') == 'language_awareness':
                        _start_textbook_language_awareness(cid,ss,page_no,groups[0].get('lesson_no',''),groups[0].get('focus','Language Awareness'))
                    elif groups and _commit_textbook_page_standards(ss,groups[0]['rows']):
                        rows=groups[0]['rows']
                        _apply_textbook_page_lesson_context(ss,page_no,groups[0].get('lesson_no',''),groups[0].get('focus',''))
                        send(cid,_textbook_page_match_message(ss,rows,page_no))
                        if ss.get('quick_material_flow') or ss.get('task')=='quick_material':
                            _temporary_auto_pack_v2386(cid)
                        else:
                            start_rph_session(cid)
                    else:
                        send(cid,'⚠️ Mapping halaman ditemui tetapi tidak dapat dipadankan dengan standard kurikulum verified.',[[{'text':'📖 Masukkan Muka Surat Lain','callback_data':'fast_use_textbook'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
                elif not ref:
                    rows=_textbook_page_rows(ss.get('year',''),ss.get('subject',''))
                    ranges=[]
                    for r in rows[:20]:
                        ranges.append(f"{r.get('page_start')}–{r.get('page_end')} ({html.escape(str(r.get('topic') or ''))})")
                    msg='⚠️ <b>Muka surat itu belum mempunyai mapping verified.</b>'
                    if ranges:
                        msg += '\n\nJulat yang tersedia:\n• ' + '\n• '.join(ranges)
                    msg += '\n\nMasukkan muka surat lain.'
                    send(cid,msg)
                else:
                    ss.pop('waiting',None)
                    ss['rph_mode']='fast_textbook'
                    ss['textbook_page']=page_no
                    ss['textbook_book_title']=str(ref.get('book_title') or '')
                    ss['textbook_page_start']=ref.get('page_start')
                    ss['textbook_page_end']=ref.get('page_end')
                    ss['textbook_reference_id']=ref.get('id')
                    ss['topic']=str(ref.get('topic') or '').strip()
                    ss['subtopic']=f'Muka surat {page_no}'
                    if not exact:
                        lm=lesson_meta[0] if lesson_meta else None
                        if lm and 'language awareness' in str(lm.get('focus') or '').lower():
                            _start_textbook_language_awareness(cid,ss,page_no,lm.get('lesson_no',''),lm.get('focus','Language Awareness'))
                        else:
                            send(cid,f"📖 <b>{html.escape(ss['topic'])}</b> ditemui untuk muka surat <b>{page_no}</b>, tetapi SK/SP <b>khusus halaman itu</b> belum disahkan.\n\nCikguLaju tidak akan memaparkan menu SK/SP atau mengambil semua standard Unit secara rawak. Masukkan muka surat lain yang mempunyai mapping verified.",[[{'text':'📖 Masukkan Muka Surat Lain','callback_data':'fast_use_textbook'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
                    else:
                        groups=_textbook_page_focus_groups(exact,lesson_meta)
                        if len(groups) > 1:
                            ss['textbook_page_groups']=groups
                            kb=[]
                            for i,g in enumerate(groups):
                                focus=str(g.get('focus') or '').strip()
                                lesson=str(g.get('lesson_no') or '').strip()
                                label='🎯 '+(focus or ('Lesson '+lesson if lesson else f'Pilihan {i+1}'))
                                if lesson and focus:
                                    label += f' · Lesson {lesson}'
                                kb.append([{'text':label[:60],'callback_data':f'tbpg_{i}'}])
                            kb.append([{'text':'📖 Masukkan Muka Surat Lain','callback_data':'fast_use_textbook'}])
                            send(cid,f"📖 <b>Muka surat {page_no}</b> digunakan untuk lebih daripada satu fokus dalam SOW.\n\nPilih fokus yang cikgu mahu ajar. Untuk lesson kemahiran, SK/SP akan diisi automatik; Language Awareness akan terus menggunakan grammar/fokus SOW tanpa mencipta SP.",kb)
                        elif groups and groups[0].get('kind') == 'language_awareness':
                            _start_textbook_language_awareness(cid,ss,page_no,groups[0].get('lesson_no',''),groups[0].get('focus','Language Awareness'))
                        elif groups and _commit_textbook_page_standards(ss,groups[0]['rows']):
                            rows=groups[0]['rows']
                            _apply_textbook_page_lesson_context(ss,page_no,groups[0].get('lesson_no',''),groups[0].get('focus',''))
                            send(cid,_textbook_page_match_message(ss,rows,page_no))
                            if ss.get('quick_material_flow') or ss.get('task')=='quick_material':
                                _temporary_auto_pack_v2386(cid)
                            else:
                                start_rph_session(cid)
                        else:
                            send(cid,'⚠️ Mapping halaman ditemui tetapi tidak dapat dipadankan dengan standard kurikulum verified.',[[{'text':'📖 Masukkan Muka Surat Lain','callback_data':'fast_use_textbook'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        elif m.get('text') and state.get(cid,{}).get('waiting','').startswith('rph_'):
            s = state.setdefault(cid,{})
            text = m.get('text','').strip()
            waiting = s.get('waiting')
            if waiting == 'rph_date':
                date, day = _parse_rph_date(text)
                if date is None:
                    send(cid,'⚠️ Tarikh tidak dikenali. Gunakan format <code>DD/MM/YYYY</code>, contoh <code>10/09/2026</code>.')
                else:
                    s['rph_date'], s['rph_day'] = date, day
                    s['waiting'] = 'rph_class'
                    _prompt_rph_class(cid, s, f'✅ Hari: <b>{day or "akan dikosongkan"}</b>')
            elif waiting == 'rph_class':
                class_value = '' if text in ('-','—') else text
                if class_value and _class_number_mismatch(s, class_value):
                    s['pending_rph_class'] = class_value
                    s.pop('waiting', None)
                    expected=_class_level_number(s)
                    send(cid, f'⚠️ Cikgu memilih <b>{html.escape(str(s.get("year") or ""))}</b>, tetapi kelas dimasukkan sebagai <b>{html.escape(class_value)}</b>.\n\nTeruskan dengan kelas ini atau betulkan?', [[{'text':'✏️ Betulkan Kelas','callback_data':'rphclass_fix'},{'text':'✅ Teruskan','callback_data':'rphclass_keep'}]])
                    return 'ok'
                s['rph_class'] = class_value
                # Jika masa telah dipilih melalui time picker, jangan tanya masa sekali lagi.
                # Teruskan kepada bilangan murid. Kekalkan fallback lama hanya untuk flow
                # legacy yang benar-benar belum mempunyai rph_time.
                if (s.get('rph_time') or '').strip():
                    s['waiting'] = 'rph_students'
                    send(cid,'👥 <b>Masukkan jumlah murid dalam kelas</b>\nContoh: <code>30</code>\nDalam RPH akan dipaparkan sebagai <code>________ / 30</code> supaya guru boleh isi bilangan murid yang hadir.\nTaip <code>-</code> jika mahu biarkan kosong.')
                else:
                    s['waiting'] = 'rph_time'
                    send(cid,'⏰ <b>Masukkan masa PdP</b>\nContoh: <code>8:00 pagi - 9:00 pagi</code>')
            elif waiting == 'rph_time':
                s['rph_time'] = '' if text in ('-','—') else text
                s['waiting'] = 'rph_students'
                send(cid,'👥 <b>Masukkan jumlah murid dalam kelas</b>\nContoh: <code>30</code>\nDalam RPH akan dipaparkan sebagai <code>________ / 30</code> supaya guru boleh isi bilangan murid yang hadir.\nTaip <code>-</code> jika mahu biarkan kosong.')
            elif waiting == 'rph_students':
                s['rph_students'] = '' if text in ('-','—') else text
                s.pop('waiting',None)
                gen_cb = s.get('rph_gen_cb')
                if gen_cb:
                    preview_v3(cid, s, gen_cb)
                else:
                    menu(cid)
        elif 'document' in m or 'photo' in m:
            waiting_now=(state.get(cid,{}) or {}).get('waiting')
            if waiting_now=='timetable_upload_v25281':
                # v25.296: timetable OCR/Gemini can take longer than Telegram's webhook window.
                # Acknowledge the webhook immediately and continue safely in background.
                def _safe_timetable_upload_worker_v25296():
                    try:
                        _handle_timetable_upload_v25281(cid,m)
                    except Exception as e:
                        print('v25.296 timetable background worker:',repr(e),flush=True)
                        state.setdefault(cid,{})['waiting']='timetable_upload_v25281'
                        try:
                            send(cid,'⚠️ Pembacaan jadual terhenti. <b>Jadual lama tidak diubah.</b>\n\nSila cuba upload semula.',
                                 [[{'text':'🔄 Cuba Upload Lagi','callback_data':'ttupload281_start'}],
                                  [{'text':'✏️ Isi Manual','callback_data':'tt_add'},{'text':'⬅️ Kembali','callback_data':'timetable'}]])
                        except Exception:
                            pass
                threading.Thread(target=_safe_timetable_upload_worker_v25296,daemon=True).start()
                return jsonify({'ok':True,'timetable_reader':'background'})
            if waiting_now=='donation_receipt':
                try:
                    rid=_new_donation_receipt(cid,m.get('message_id'))
                    state.setdefault(cid,{}).pop('waiting',None)
                    user=m.get('from',{}) or {}; name=' '.join(x for x in [user.get('first_name',''),user.get('last_name','')] if x).strip() or user.get('username','') or 'Pengguna'
                    cap=('💛 <b>RESIT SUMBANGAN DITERIMA</b>\n\n'
                         f'🧾 Receipt ID: <b>{rid}</b>\n👤 Nama: <b>{html.escape(name)}</b>\n🆔 Telegram ID: <code>{cid}</code>\n\n'
                         'Pilih tambahan hari selepas resit direkod:')
                    delivered=False
                    if ADMIN_CHAT_ID:
                        kb={'inline_keyboard':_admin_donation_days_keyboard(rid)}
                        rr=requests.post(f'{API}/copyMessage',json={'chat_id':str(ADMIN_CHAT_ID),'from_chat_id':str(cid),'message_id':m['message_id'],'caption':cap,'parse_mode':'HTML','reply_markup':kb},timeout=20)
                        delivered=rr.ok
                        if not delivered:
                            fr=requests.post(f'{API}/forwardMessage',json={'chat_id':str(ADMIN_CHAT_ID),'from_chat_id':str(cid),'message_id':m['message_id']},timeout=20)
                            if fr.ok:
                                send(ADMIN_CHAT_ID,cap,_admin_donation_days_keyboard(rid)); delivered=True
                    if delivered:
                        send(cid,'✅ <b>Resit sumbangan anda telah diterima dan akan direkod oleh admin.</b>\n\nTerima kasih atas sumbangan anda.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
                    else:
                        send(cid,'⚠️ Resit telah diterima tetapi belum berjaya direkod kepada admin. Sila cuba hantar semula sebentar lagi.',[[{'text':'📎 Hantar Semula Resit','callback_data':'donation_receipt'},{'text':'🏠 Menu Utama','callback_data':'home'}]])
                except Exception as e:
                    print('Donation receipt handling error:',repr(e),flush=True); send(cid,'⚠️ Resit tidak berjaya direkod. Sila cuba semula.')
                return jsonify({'ok':True})
            pending_req=_latest_pending_payment(cid)
            waiting_payment=(state.get(cid,{}) or {}).get('waiting')=='payment_proof'

            if waiting_payment or pending_req:
                try:
                    req_id=(pending_req or {}).get('id') or _new_payment_request(cid,m.get('message_id'),5.00)
                    state.setdefault(cid,{}).pop('waiting',None)

                    user=m.get('from',{}) or {}
                    name=' '.join(x for x in [user.get('first_name',''),user.get('last_name','')] if x).strip() or user.get('username','') or 'Pengguna'
                    username=str(user.get('username') or '-')

                    admin_delivered=False
                    admin_error=''

                    if ADMIN_CHAT_ID:
                        admin_caption=(
                            '💰 <b>BAYARAN BARU</b>\n\n'
                            f'🧾 Payment ID: <b>{req_id}</b>\n'
                            f'👤 User ID: <code>{cid}</code>\n'
                            f'👩‍🏫 Nama: <b>{html.escape(name)}</b>\n'
                            f'📦 Pakej: <b>AKSES 30 HARI</b>\n'
                            '💰 Jumlah: <b>RM5.00</b>\n\n'
                            '⚠️ Semak resit sebelum Approve.'
                        )
                        admin_kb={
                            'inline_keyboard':[
                                [
                                    {'text':'✅ Approve','callback_data':f'admin_approve|{req_id}'},
                                    {'text':'❌ Reject','callback_data':f'admin_reject|{req_id}'}
                                ],
                                [
                                    {'text':'🧾 Semua Pending','callback_data':'admin_pending_all'}
                                ]
                            ]
                        }

                        # BEST PATH: copy the customer's receipt itself to admin,
                        # with approval buttons attached to that same receipt.
                        # This also works when the payer IS the admin: the bot
                        # copies the receipt back into the same chat with buttons.
                        cr=requests.post(
                            f'{API}/copyMessage',
                            json={
                                'chat_id':str(ADMIN_CHAT_ID),
                                'from_chat_id':str(cid),
                                'message_id':m['message_id'],
                                'caption':admin_caption,
                                'parse_mode':'HTML',
                                'reply_markup':admin_kb
                            },
                            timeout=20
                        )
                        if cr.ok:
                            admin_delivered=True
                        else:
                            admin_error=f'copyMessage {cr.status_code}: {cr.text[:180]}'
                            print('Admin copyMessage failed:',admin_error,flush=True)

                            # Fallback: forward original proof + separate approval card.
                            fr=requests.post(
                                f'{API}/forwardMessage',
                                json={
                                    'chat_id':str(ADMIN_CHAT_ID),
                                    'from_chat_id':str(cid),
                                    'message_id':m['message_id']
                                },
                                timeout=20
                            )
                            if fr.ok:
                                try:
                                    rr=send(
                                        ADMIN_CHAT_ID,
                                        admin_caption,
                                        [[
                                            {'text':'✅ Approve','callback_data':f'admin_approve|{req_id}'},
                                            {'text':'❌ Reject','callback_data':f'admin_reject|{req_id}'}
                                         ],
                                         [
                                            {'text':'🧾 Semua Pending','callback_data':'admin_pending_all'}
                                         ]]
                                    )
                                    admin_delivered=True
                                except Exception as e:
                                    admin_error=f'approval card: {e!r}'
                            else:
                                admin_error += f' | forwardMessage {fr.status_code}: {fr.text[:180]}'
                                print('Admin forwardMessage failed:',admin_error,flush=True)
                    else:
                        admin_error='ADMIN_CHAT_ID tidak ditetapkan.'

                    if admin_delivered:
                        _set_payment_note(req_id,'proof_received_admin_notified')

                        # Only tell customer "sent to admin" AFTER Telegram confirms delivery.
                        send(
                            cid,
                            '✅ <b>BUKTI BAYARAN DITERIMA</b>\n\n'
                            f'🧾 Payment ID: <b>{req_id}</b>\n'
                            '📦 Pakej: <b>AKSES 30 HARI</b>\n'
                            '💰 Jumlah: <b>RM5.00</b>\n\n'
                            '⌛ <b>STATUS:</b>\n'
                            'Bukti telah dihantar terus kepada admin.\n'
                            'Menunggu pengesahan admin.\n\n'
                            'Cikgu akan menerima mesej sebaik sahaja akses diaktifkan.',
                            [[{'text':'🎓 Jana Bahan','callback_data':'quick'}],
                             [{'text':'👤 Akaun Saya','callback_data':'account'}],
                             [{'text':'🏠 Menu Utama','callback_data':'home'}]]
                        )
                    else:
                        _set_payment_note(req_id,'proof_received_admin_delivery_failed')
                        print('PAYMENT ADMIN DELIVERY FAILED:',
                              f'req={req_id} user={cid} admin={ADMIN_CHAT_ID!r} error={admin_error}',
                              flush=True)
                        send(
                            cid,
                            '⚠️ <b>Bukti bayaran telah diterima tetapi belum berjaya dihantar kepada admin.</b>\n\n'
                            f'Payment ID: <b>{req_id}</b>\n'
                            'Sila tekan <b>Hantar Semula Bukti</b> dan hantar gambar/resit sekali lagi.',
                            [[{'text':'🔄 Hantar Semula Bukti','callback_data':'subscribe_500'}],
                             [{'text':'🏠 Menu Utama','callback_data':'home'}]]
                        )

                except Exception as e:
                    print('Payment proof handling error:',repr(e),flush=True)
                    send(cid,'⚠️ Bukti bayaran diterima tetapi berlaku ralat semasa menghantar kepada admin. Sila hantar semula bukti.')
            else:
                send(cid,'✅ Bahan diterima.')
    return jsonify({'ok':True})

@app.route('/setup-webhook')
def setup_webhook():
    if not BOT_TOKEN or not WEBHOOK_URL:
        return jsonify({'ok':False,'error':'Tetapkan BOT_TOKEN dan WEBHOOK_URL dahulu'}),500
    url = WEBHOOK_URL.rstrip('/') + '/webhook'
    r = requests.post(f'{API}/setWebhook',json={'url':url},timeout=20)
    requests.post(f'{API}/setMyCommands', json={'commands':[
        {'command':'start','description':'Buka CikguLaju AI'},
        {'command':'menu','description':'Menu utama'},
        {'command':'access','description':'Semak status akses'},
        {'command':'myid','description':'Lihat Telegram ID'}
    ]}, timeout=20)
    requests.post(f'{API}/setChatMenuButton', json={'menu_button':{'type':'commands'}}, timeout=20)
    return jsonify({'webhook':url,'telegram':r.json(),'menu_button':'commands'})


