def _unit_order_from_title(title, fallback):
 t=str(title or '').strip()
 if t.lower().startswith(('starter','welcome')): return 0
 m=re.match(r'^Unit\s+(\d+)',t,re.I)
 return int(m.group(1)) if m else int(fallback)

def _ensure_textbook_bridge():
 con=_db()
 try:
  con.execute("CREATE TABLE IF NOT EXISTS textbook_units(id INTEGER PRIMARY KEY AUTOINCREMENT,year_label TEXT NOT NULL,subject TEXT NOT NULL,textbook_title TEXT NOT NULL DEFAULT '',unit_order INTEGER NOT NULL,unit_title TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 1,UNIQUE(year_label,subject,unit_title))")
  con.execute("CREATE TABLE IF NOT EXISTS textbook_unit_sp_map(id INTEGER PRIMARY KEY AUTOINCREMENT,year_label TEXT NOT NULL,subject TEXT NOT NULL,unit_title TEXT NOT NULL,sp_code TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 1,UNIQUE(year_label,subject,unit_title,sp_code))")
  con.execute("""CREATE TABLE IF NOT EXISTS textbook_unit_sp_evidence(
      year_label TEXT NOT NULL, subject TEXT NOT NULL, unit_title TEXT NOT NULL,
      sp_code TEXT NOT NULL, source_key TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 1,
      notes TEXT NOT NULL DEFAULT '', checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      PRIMARY KEY(year_label,subject,unit_title,sp_code,source_key))""")
  source_rows={
   'SOW_ENGLISH_Y1_SK':('Primary Year 1 SK Scheme of Work','Kementerian Pendidikan Malaysia / BPK','KSSR English Year 1 Scheme of Work; verified unit-level Learning Standards coverage'),
   'SOW_ENGLISH_Y2_SK':('Primary Year 2 SK Scheme of Work','Kementerian Pendidikan Malaysia / BPK','KSSR English Year 2 Scheme of Work; verified lesson-level Learning Standards coverage'),
   'SOW_ENGLISH_Y3_SK':('Primary Year 3 SK Scheme of Work','Kementerian Pendidikan Malaysia / BPK','KSSR English Year 3 Scheme of Work; verified module-level Learning Standards coverage'),
   'SOW_ENGLISH_Y4_SK':('Primary Year 4 SK Scheme of Work','Kementerian Pendidikan Malaysia / BPK','KSSR English Year 4 Scheme of Work'),
   'SOW_ENGLISH_Y5_SK':('Primary Year 5 SK Scheme of Work','Kementerian Pendidikan Malaysia / BPK','KSSR English Year 5 Scheme of Work; Appendix 1 Learning Standards mapping'),
   'SOW_ENGLISH_Y6_SK':('Primary Year 6 SK Scheme of Work','Kementerian Pendidikan Malaysia / BPK','KSSR English Year 6 Scheme of Work; Appendix 1 Learning Standards mapping'),
  }
  for key,(title,authority,notes) in source_rows.items():
   con.execute("""INSERT INTO curriculum_sources(source_key,title,authority,source_url,curriculum_version,verified,notes,source_type,checked_at)
       VALUES(?,?,?,?,?,1,?,'Scheme of Work',CURRENT_TIMESTAMP)
       ON CONFLICT(source_key) DO UPDATE SET title=excluded.title,authority=excluded.authority,
       curriculum_version=excluded.curriculum_version,verified=1,notes=excluded.notes,
       source_type='Scheme of Work',checked_at=CURRENT_TIMESTAMP""",
       (key,title,authority,'','KSSR (Semakan 2017)',notes))
  for (yr,sub),units in _TEXTBOOK_UNIT_SEED.items():
   textbook_title,source_key=_ENGLISH_TEXTBOOK_META.get((yr,sub),('', ''))
   for n,(title,codes) in enumerate(units,1):
    unit_order=_unit_order_from_title(title,n)
    con.execute('INSERT INTO textbook_units(year_label,subject,textbook_title,unit_order,unit_title,verified) VALUES(?,?,?,?,?,1) ON CONFLICT(year_label,subject,unit_title) DO UPDATE SET textbook_title=excluded.textbook_title,unit_order=excluded.unit_order,verified=1',(yr,sub,textbook_title,unit_order,title))
    for code in codes:
     ok=con.execute('SELECT 1 FROM curriculum_standards WHERE year_label=? AND subject=? AND sp_code=? AND verified=1 LIMIT 1',(yr,sub,code)).fetchone()
     if not ok: continue
     con.execute('INSERT OR IGNORE INTO textbook_unit_sp_map(year_label,subject,unit_title,sp_code,verified) VALUES(?,?,?,?,1)',(yr,sub,title,code))
     if source_key:
      con.execute("""INSERT INTO textbook_unit_sp_evidence(year_label,subject,unit_title,sp_code,source_key,verified,notes)
          VALUES(?,?,?,?,?,1,'Learning Standard assigned to this unit in verified Scheme of Work coverage')
          ON CONFLICT(year_label,subject,unit_title,sp_code,source_key) DO UPDATE SET verified=1,checked_at=CURRENT_TIMESTAMP""",
          (yr,sub,title,code,source_key))
  con.commit()
 finally: con.close()

def _textbook_units(year_label,subject):
 try:
  _ensure_textbook_bridge(); con=_db()
  try: return [r['unit_title'] for r in con.execute('SELECT unit_title FROM textbook_units WHERE year_label=? AND subject=? AND verified=1 ORDER BY unit_order,id',(year_label,subject)).fetchall()]
  finally: con.close()
 except Exception as e:
  print('Textbook bridge error:',repr(e),flush=True); return []

def curriculum_topic_options(year_label,subject):
 units=_textbook_units(year_label,subject)
 if units: return units
 con=_db()
 try:
  rows=con.execute('SELECT topic,MIN(id) AS id FROM curriculum_standards WHERE year_label=? AND subject=? AND verified=1 GROUP BY topic ORDER BY MIN(id)',(year_label,subject)).fetchall()
  topics=[r['topic'] for r in rows]
  if topics: return topics
  rows=con.execute('SELECT topic,MIN(id) AS id FROM curriculum_topics WHERE year_label=? AND subject=? GROUP BY topic ORDER BY MIN(id)',(year_label,subject)).fetchall()
  topics=[r['topic'] for r in rows]
  if topics: return topics
 except Exception as e:
  print('curriculum_topic_options warning:',repr(e),flush=True)
 finally: con.close()
 try: return list((TOPICS.get(year_label,{}) or {}).get(subject,[]) or [])
 except Exception: return []

def _mapped_sp_codes(s,unit_title=None):
 unit_title=unit_title or s.get('topic',''); _ensure_textbook_bridge(); con=_db()
 try: return [r['sp_code'] for r in con.execute('SELECT sp_code FROM textbook_unit_sp_map WHERE year_label=? AND subject=? AND unit_title=? AND verified=1 ORDER BY id',(s.get('year',''),s.get('subject',''),unit_title)).fetchall()]
 finally: con.close()

def curriculum_sk_options(s):
 codes=_mapped_sp_codes(s); con=_db()
 try:
  if codes:
   q=','.join('?'*len(codes)); rows=con.execute(f'SELECT sk_code,sk_text,MIN(id) AS id FROM curriculum_standards WHERE year_label=? AND subject=? AND verified=1 AND sp_code IN ({q}) GROUP BY sk_code,sk_text ORDER BY MIN(id)',[s.get('year',''),s.get('subject','')]+codes).fetchall()
  else: rows=con.execute('SELECT sk_code,sk_text,MIN(id) AS id FROM curriculum_standards WHERE year_label=? AND subject=? AND topic=? AND verified=1 GROUP BY sk_code,sk_text ORDER BY MIN(id)',(s.get('year',''),s.get('subject',''),s.get('topic',''))).fetchall()
  return [dict(r) for r in rows]
 finally: con.close()

def curriculum_sp_options(s,sk_code):
 codes=_mapped_sp_codes(s); con=_db()
 try:
  if codes:
   q=','.join('?'*len(codes)); rows=con.execute(f'SELECT sp_code,sp_text,sk_code,sk_text,id FROM curriculum_standards WHERE year_label=? AND subject=? AND sk_code=? AND verified=1 AND sp_code IN ({q}) ORDER BY id',[s.get('year',''),s.get('subject',''),sk_code]+codes).fetchall()
  else: rows=con.execute('SELECT sp_code,sp_text,sk_code,sk_text,id FROM curriculum_standards WHERE year_label=? AND subject=? AND topic=? AND sk_code=? AND verified=1 ORDER BY id',(s.get('year',''),s.get('subject',''),s.get('topic',''),sk_code)).fetchall()
  return [dict(r) for r in rows]
 finally: con.close()

def _summative_curriculum_scope(s):
 topics=list(s.get('summative_topics') or [])
 if not topics: return []
 con=_db(); collected=[]; seen=set()
 try:
  for unit in topics:
   tmp=dict(s); tmp['topic']=unit; codes=_mapped_sp_codes(tmp,unit)
   if codes:
    q=','.join('?'*len(codes)); rows=con.execute(f'SELECT ? AS topic,sk_code,sk_text,sp_code,sp_text FROM curriculum_standards WHERE year_label=? AND subject=? AND verified=1 AND sp_code IN ({q}) ORDER BY id',[unit,s.get('year',''),s.get('subject','')]+codes).fetchall()
   else: rows=con.execute('SELECT topic,sk_code,sk_text,sp_code,sp_text FROM curriculum_standards WHERE year_label=? AND subject=? AND verified=1 AND topic=? ORDER BY id',(s.get('year',''),s.get('subject',''),unit)).fetchall()
   for r in rows:
    k=(r['sk_code'],r['sp_code'])
    if k not in seen: seen.add(k); collected.append(dict(r))
  return collected
 finally: con.close()
try: _ensure_textbook_bridge()
except Exception as _e: print('Textbook bridge init:',repr(_e),flush=True)



# ============================================================
# v22.53 — ENGLISH TEXTBOOK-FIRST SELECTION
# English flow: Tajuk/Unit buku teks -> SK -> SP.
# The textbook title is used as lesson context; DSKP standards remain
# selected explicitly afterwards so the teacher controls SK/SP.
# ============================================================
_ENGLISH_SKILL_LABELS = {
    'listening','speaking','reading','writing','language arts',
    'grammar','vocabulary','grammar and vocabulary',
    'listening and speaking'
}

def _english_textbook_topics(year_label):
    """Return only verified English textbook units already stored in the DB.

    Legacy TOPICS labels remain available as historical theme hints elsewhere,
    but are not promoted to textbook units and never create assumed Unit→SP maps.
    """
    return _textbook_units(year_label,'Bahasa Inggeris')

def curriculum_topic_options(year_label,subject):
    # English primary is normally taught according to textbook/theme title first,
    # not by choosing Listening/Speaking/Reading/Writing as the topic.
    if str(subject).strip() == 'Bahasa Inggeris' and str(year_label).startswith('Tahun '):
        eng=_english_textbook_topics(year_label)
        if eng:
            return eng
    units=_textbook_units(year_label,subject)
    if units:
        return units
    con=_db()
    try:
        rows=con.execute('SELECT topic,MIN(id) AS id FROM curriculum_standards WHERE year_label=? AND subject=? AND verified=1 GROUP BY topic ORDER BY MIN(id)',(year_label,subject)).fetchall()
        topics=[r['topic'] for r in rows]
        if topics: return topics
        rows=con.execute('SELECT topic,MIN(id) AS id FROM curriculum_topics WHERE year_label=? AND subject=? GROUP BY topic ORDER BY MIN(id)',(year_label,subject)).fetchall()
        topics=[r['topic'] for r in rows]
        if topics: return topics
    except Exception as e:
        print('curriculum_topic_options warning:',repr(e),flush=True)
    finally:
        con.close()
    try: return list((TOPICS.get(year_label,{}) or {}).get(subject,[]) or [])
    except Exception: return []

def curriculum_sk_options(s):
    codes=_mapped_sp_codes(s)
    con=_db()
    try:
        if codes:
            q=','.join('?'*len(codes))
            rows=con.execute(f'SELECT sk_code,sk_text,MIN(id) AS id FROM curriculum_standards WHERE year_label=? AND subject=? AND verified=1 AND sp_code IN ({q}) GROUP BY sk_code,sk_text ORDER BY MIN(id)',[s.get('year',''),s.get('subject','')]+codes).fetchall()
        else:
            # Strict topic routing: never show the whole year's SK list for a textbook title.
            rows=con.execute('SELECT sk_code,sk_text,MIN(id) AS id FROM curriculum_standards WHERE year_label=? AND subject=? AND topic=? AND verified=1 GROUP BY sk_code,sk_text ORDER BY MIN(id)',(s.get('year',''),s.get('subject',''),s.get('topic',''))).fetchall()
        return [dict(r) for r in rows]
    finally:
        con.close()

def curriculum_sp_options(s,sk_code):
    codes=_mapped_sp_codes(s)
    con=_db()
    try:
        if codes:
            q=','.join('?'*len(codes))
            rows=con.execute(f'SELECT sp_code,sp_text,sk_code,sk_text,id FROM curriculum_standards WHERE year_label=? AND subject=? AND sk_code=? AND verified=1 AND sp_code IN ({q}) ORDER BY id',[s.get('year',''),s.get('subject',''),sk_code]+codes).fetchall()
        else:
            rows=con.execute('SELECT sp_code,sp_text,sk_code,sk_text,id FROM curriculum_standards WHERE year_label=? AND subject=? AND topic=? AND sk_code=? AND verified=1 ORDER BY id',(s.get('year',''),s.get('subject',''),s.get('topic',''),sk_code)).fetchall()
        return [dict(r) for r in rows]
    finally:
        con.close()

# Override the active SK selector so English follows the same explicit
# textbook title -> SK -> SP hierarchy as other subjects.
def show_curriculum_sk(cid, s):
    # HARD GUARD: exact textbook mapping owns SK/SP selection.
    state[cid]=s
    if _textbook_auto_standards_ready(s):
        return _rph_session_question(cid)
    if str(s.get('rph_mode') or '').startswith('fast_textbook'):
        return send(cid,'⚠️ Muka surat ini belum mempunyai mapping SK/SP verified. Sila pilih muka surat lain.',[[{'text':'📖 Masukkan Muka Surat Lain','callback_data':'fast_use_textbook'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    opts=curriculum_sk_options(s)
    if not opts:
        return send(cid,'📘 <b>Topik tersedia, tetapi SK/SP disahkan untuk pilihan ini masih belum dimasukkan ke database.</b>\n\nIni bukan ralat aplikasi. Sila cuba topik/subjek lain untuk ujian sementara.',[[{'text':'⬅️ Pilih Topik Lain','callback_data':'sub_'+str(s.get('subject',''))}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    state[cid]['curr_sk_options']=opts
    if s.get('task') in ('rph','both','worksheet','bbm'):
        return show_rph_sk(cid, s)
    kb=[[{'text':f"{o['sk_code']} — {o['sk_text']}"[:60],'callback_data':f'csk_{i}'}] for i,o in enumerate(opts[:40])]
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    title='📘 <b>Pilih Standard Kandungan (SK)</b>'
    if _is_english_subject(s):
        title=f"🇬🇧 <b>{html.escape(str(s.get('topic','')))}</b>\n\n📘 Pilih Standard Kandungan (SK):"
    send(cid,title,kb)

# Make topic screen wording clearer for English.
_old_show_topics = show_topics
def show_topics(cid, page=0):
    s=state.setdefault(cid,{})
    if _is_english_subject(s) and str(s.get('year','')).startswith('Tahun '):
        year_label=s.get('year',''); sub=s.get('subject','')
        topics=curriculum_topic_options(year_label,sub)
        if not topics:
            return _old_show_topics(cid,page)
        s['topic_list']=topics; per_page=8; start=page*per_page; end=min(start+per_page,len(topics)); kb=[]
        for idx in range(start,end):
            kb.append([{'text':f'📖 {topics[idx]}','callback_data':f'topic_{idx}'}])
        nav=[]
        if page>0: nav.append({'text':'⬅️ Sebelum','callback_data':f'tpage_{page-1}'})
        if end<len(topics): nav.append({'text':'Seterusnya ➡️','callback_data':f'tpage_{page+1}'})
        if nav: kb.append(nav)
        kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
        pages=(len(topics)+per_page-1)//per_page
        verified_units=_textbook_units(year_label,sub)
        if verified_units:
            intro='Pilih <b>unit buku teks yang telah disahkan</b>. Selepas itu cikgu akan pilih <b>SK</b> dan <b>SP</b> yang dipetakan kepada unit tersebut.'
        else:
            intro='Bridge <b>unit buku teks → SP</b> untuk tahun ini belum disahkan dalam database. Buat masa ini CikguLaju hanya memaparkan <b>fokus DSKP yang memang wujud</b>; sistem tidak akan mereka mapping unit buku teks.'
        return send(cid,f'🇬🇧 <b>Bahasa Inggeris — {year_label}</b>\n\n{intro}\n<i>Halaman {page+1}/{pages}</i>',kb)
    return _old_show_topics(cid,page)

# ============================================================
# CikguLaju v10 — LOCAL-FIRST / LOW-AI
# Cuba jana worksheet secara lokal dahulu. AI hanya fallback.
