def _ws_image_asset_for_state(state, level=1):
    """Choose a deterministic verified local image asset mapped to the exact SP."""
    year=str(state.get('year') or state.get('year_label') or '')
    subject=str(state.get('subject') or '')
    sp=str(state.get('sp_code') or '')
    if not (year and subject and sp) or subject=='Matematik':
        return None
    try:
        with _db() as con:
            rows=con.execute("""
                SELECT a.asset_key,a.relative_path,a.alt_text,a.scene_category,m.match_score
                FROM curriculum_standards cs
                JOIN worksheet_sp_image_map m ON m.curriculum_standard_id=cs.id AND m.verified=1
                JOIN worksheet_image_asset_bank a ON a.id=m.asset_id AND a.verified=1
                WHERE cs.year_label=? AND cs.subject=? AND cs.sp_code=? AND cs.verified=1
                ORDER BY m.match_score DESC,a.asset_key
            """,(year,subject,sp)).fetchall()
        if not rows: return None
        seed='|'.join([year,subject,sp,str(level),str(state.get('variation_seed') or '')])
        idx=_ws_stable_index(seed+'|image-asset',min(len(rows),8))
        row=rows[idx]
        return {'asset_key':row['asset_key'],'relative_path':row['relative_path'],
                'alt_text':row['alt_text'],'scene_category':row['scene_category']}
    except Exception:
        return None

def _find_advanced_visual_token(lines):
    text=' '.join(str(x or '') for x in lines)
    m=re.search(r'\[IMAGE_ASSET:\s*([A-Za-z0-9_.-]+)\s*\]',text,re.I)
    if m:
        key=m.group(1)
        try:
            with _db() as con:
                row=con.execute('SELECT asset_key,relative_path,alt_text,scene_category FROM worksheet_image_asset_bank WHERE asset_key=? AND verified=1',(key,)).fetchone()
            if row:
                path=os.path.join(_WORKSHEET_IMAGE_BASE,str(row['relative_path']).replace('/',os.sep))
                if os.path.exists(path):
                    return ('image_asset',{'asset_key':row['asset_key'],'path':path,'alt_text':row['alt_text'],'scene_category':row['scene_category']})
        except Exception:
            pass
    return _find_advanced_visual_token_v2293(lines)

class AdvancedWorksheetVisual(_AdvancedWorksheetVisual_v2293):
    def wrap(self,aw,ah):
        if self.spec and self.spec[0]=='image_asset':
            h=68*mm
            self.height=h
            return min(self.width,aw),h
        return super().wrap(aw,ah)
    def draw(self):
        if self.spec and self.spec[0]=='image_asset':
            from reportlab.lib.utils import ImageReader
            kind,p=self.spec; c=self.canv; W=self.width; H=self.height
            try:
                from PIL import Image as PILImage
                im=PILImage.open(p['path']); iw,ih=im.size
                margin=2*mm; maxw=W-2*margin; maxh=H-2*margin
                scale=min(maxw/iw,maxh/ih); rw=iw*scale; rh=ih*scale
                x=(W-rw)/2; y=(H-rh)/2
                c.drawImage(ImageReader(p['path']),x,y,width=rw,height=rh,preserveAspectRatio=True,anchor='c',mask='auto')
                c.setLineWidth(.6); c.rect(x,y,rw,rh,stroke=1,fill=0)
            except Exception:
                c.setFont('Helvetica',8); c.drawCentredString(W/2,H/2,'Visual tidak dapat dipaparkan')
            return
        return super().draw()

def _word_advanced_visual_image(spec):
    if spec and spec[0]=='image_asset':
        from PIL import Image as PILImage
        from io import BytesIO
        img=PILImage.open(spec[1]['path']).convert('RGB')
        img.thumbnail((1200,760))
        stream=BytesIO(); img.save(stream,format='PNG',dpi=(150,150)); stream.seek(0); return stream
    return _word_advanced_visual_image_v2293(spec)

def _db_first_generate_one_level(state, level, qcount):
    text=_db_first_generate_one_level_v2293(state,level,qcount)
    asset=_ws_image_asset_for_state(state,level)
    if not asset: return text
    token=f"[IMAGE_ASSET: {asset['asset_key']}]"
    if token in text: return text
    lines=str(text).splitlines()
    insert_at=min(3,len(lines))
    lines[insert_at:insert_at]=['STIMULUS VISUAL',token]
    return '\n'.join(lines)

