def _norm_route_text_v2298(value):
    value=str(value or '').strip().casefold()
    value=re.sub(r'\s+',' ',value)
    value=value.replace('–','-').replace('—','-')
    return value

def _mapped_sp_codes_v2298(s):
    """Resolve verified textbook-unit -> SP mappings robustly, including spacing/case variations."""
    year=str(s.get('year') or s.get('year_label') or '').strip()
    subject=str(s.get('subject') or '').strip()
    topic=str(s.get('topic') or s.get('textbook_unit_title') or '').strip()
    if not (year and subject and topic):
        return []
    try:
        codes=_mapped_sp_codes(s)
        if codes:
            return list(dict.fromkeys(codes))
    except Exception:
        pass
    nt=_norm_route_text_v2298(topic)
    con=_db()
    try:
        rows=con.execute("""
            SELECT unit_title,sp_code
            FROM textbook_unit_sp_map
            WHERE year_label=? AND subject=? AND verified=1
            ORDER BY id
        """,(year,subject)).fetchall()
        out=[r['sp_code'] for r in rows if _norm_route_text_v2298(r['unit_title'])==nt]
        return list(dict.fromkeys(out))
    finally:
        con.close()

def _canonical_curriculum_topic_v2298(s):
    """Return a verified curriculum topic only when the match is exact/normalized or confidently unique."""
    import difflib
    year=str(s.get('year') or s.get('year_label') or '').strip()
    subject=str(s.get('subject') or '').strip()
    topic=str(s.get('topic') or '').strip()
    if not (year and subject and topic):
        return topic
    con=_db()
    try:
        rows=con.execute("""
            SELECT topic,MIN(id) id
            FROM curriculum_standards
            WHERE year_label=? AND subject=? AND verified=1
            GROUP BY topic ORDER BY MIN(id)
        """,(year,subject)).fetchall()
    finally:
        con.close()
    topics=[str(r['topic']) for r in rows]
    nt=_norm_route_text_v2298(topic)
    for t in topics:
        if _norm_route_text_v2298(t)==nt:
            return t
    if not topics:
        return topic
    scored=sorted(((difflib.SequenceMatcher(None,nt,_norm_route_text_v2298(t)).ratio(),t) for t in topics),reverse=True)
    if scored and scored[0][0]>=0.78 and (len(scored)==1 or scored[0][0]-scored[1][0]>=0.08):
        return scored[0][1]
    return topic

def curriculum_sk_options(s):
    """Final v22.98 SK resolver: textbook mapping first, verified curriculum topic second."""
    year=str(s.get('year') or s.get('year_label') or '').strip()
    subject=str(s.get('subject') or '').strip()
    codes=_mapped_sp_codes_v2298(s)
    con=_db()
    try:
        if codes:
            q=','.join('?'*len(codes))
            rows=con.execute(
                f"""SELECT sk_code,sk_text,MIN(id) id
                    FROM curriculum_standards
                    WHERE year_label=? AND subject=? AND verified=1
                      AND sp_code IN ({q})
                    GROUP BY sk_code,sk_text ORDER BY MIN(id)""",
                [year,subject]+codes).fetchall()
        else:
            topic=_canonical_curriculum_topic_v2298(s)
            if topic and topic!=s.get('topic'):
                s['topic']=topic
            rows=con.execute("""
                SELECT sk_code,sk_text,MIN(id) id
                FROM curriculum_standards
                WHERE year_label=? AND subject=? AND topic=? AND verified=1
                GROUP BY sk_code,sk_text ORDER BY MIN(id)
            """,(year,subject,topic)).fetchall()
        return [dict(r) for r in rows]
    finally:
        con.close()

