    try:
        if codes:
            q=','.join('?'*len(codes))
            rows=con.execute(
                f"""SELECT sp_code,sp_text,sk_code,sk_text,id
                    FROM curriculum_standards
                    WHERE year_label=? AND subject=? AND sk_code=? AND verified=1
                      AND sp_code IN ({q})
                    ORDER BY id""",
                [year,subject,sk_code]+codes).fetchall()
        else:
            topic=_canonical_curriculum_topic_v2298(s)
            rows=con.execute("""
                SELECT sp_code,sp_text,sk_code,sk_text,id
                FROM curriculum_standards
                WHERE year_label=? AND subject=? AND topic=? AND sk_code=? AND verified=1
                ORDER BY id
            """,(year,subject,topic,sk_code)).fetchall()
        return [dict(r) for r in rows]
    finally:
        con.close()

