APP_VERSION = 'v23.42-RUNTIME-MAP-DISCOVERY'

_ws_image_asset_for_state_v2299 = _ws_image_asset_for_state

def _ws_image_asset_for_state(state, level=1):
    year=str(state.get('year') or state.get('year_label') or '')
    subject=str(state.get('subject') or '')
    sp=str(state.get('sp_code') or '')
    if not (year and subject and sp) or subject=='Matematik':
        return None
    seed='|'.join([year,subject,sp,str(level),str(state.get('variation_seed') or '')])
    try:
        with _db() as con:
            rows=con.execute("""
                SELECT v.asset_key,v.visual_role,v.visual_family,m.question_function,m.match_score
                FROM curriculum_standards cs
                JOIN worksheet_sp_assessment_visual_map m
                  ON m.curriculum_standard_id=cs.id AND m.verified=1
                JOIN worksheet_assessment_visual_bank v
                  ON v.id=m.visual_id AND v.verified=1
                WHERE cs.year_label=? AND cs.subject=? AND cs.sp_code=? AND cs.verified=1
                ORDER BY m.match_score DESC,v.asset_key
            """,(year,subject,sp)).fetchall()
        if rows:
            # Prefer the strongest relevant group; variation only among close top matches.
            top=float(rows[0]['match_score'] or 0)
            pool=[r for r in rows if float(r['match_score'] or 0)>=max(1,top-10)]
            pool=pool[:4] or rows[:1]
            row=pool[_ws_stable_index(seed+'|hq-assessment-visual',len(pool))]
            return {
                'asset_key':row['asset_key'],
                'relative_path':'',
                'alt_text':str(row['visual_family'] or ''),
                'scene_category':str(row['visual_family'] or ''),
                'visual_role':str(row['visual_role'] or ''),
                'quality_tier':'assessment_hq'
            }
    except Exception as e:
        print('v23.00 HQ visual selector warning:',repr(e),flush=True)
    return _ws_image_asset_for_state_v2299(state,level)

