def _complete_word_validate_v2320(answer, rendered_pattern):
    answer=''.join(ch for ch in str(answer or '').strip() if ch.isalpha())
    if not answer: return False
    tokens=str(rendered_pattern or '').split()
    if len(tokens)!=len(answer): return False
    blanks=sum(1 for x in tokens if x=='_')
    revealed=sum(1 for x in tokens if x!='_')
    return blanks+revealed==len(answer)

def _response_geometry_validate_v2320(task_type, expected_count, response_count):
    if _worksheet_response_geometry_rule_v2320(task_type) is None:
        return True
    return int(expected_count)==int(response_count)

