# v23.25 — single authoritative app/main-DB/visual-DB release guard.
def _assert_release_pair_v2325():
    """v23.56 hotfix: structural runtime guard; tolerate legacy DBs without app_release_meta."""
    required_files = [
        (DB_PATH, 'main database'),
        (VISUAL_DB_PATH, 'visual database'),
        (WORKSHEET_CONTENT_DB_PATH, 'worksheet content database'),
    ]
    for path, label in required_files:
        if not os.path.exists(path):
            raise RuntimeError(f'CikguLaju {label} is missing: {path}')

    # Do not crash merely because an older compatible main DB has no release metadata.
    with _db() as con:
        main_tables = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        # Create metadata table non-destructively for future releases.
        con.execute("CREATE TABLE IF NOT EXISTS app_release_meta(meta_key TEXT PRIMARY KEY, meta_value TEXT NOT NULL)")
        con.execute("INSERT OR IGNORE INTO app_release_meta(meta_key,meta_value) VALUES('release_version','v23.56-PUBLIC-BETA-HOTFIX')")
        con.commit()

    with _visual_db() as con:
        vtables = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        if 'worksheet_visual_blob_store' not in vtables:
            raise RuntimeError('CikguLaju visual database is incompatible: worksheet_visual_blob_store missing.')
        actual_count = con.execute("SELECT COUNT(*) FROM worksheet_visual_blob_store WHERE verified=1").fetchone()[0]

    with _worksheet_content_db() as con:
        ctables = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        missing = {'worksheet_item_templates','worksheet_blueprints'} - ctables
        if missing:
            raise RuntimeError('CikguLaju worksheet content database is incompatible: missing '+', '.join(sorted(missing)))
        tcount=con.execute("SELECT COUNT(*) FROM worksheet_item_templates").fetchone()[0]
        bcount=con.execute("SELECT COUNT(*) FROM worksheet_blueprints").fetchone()[0]

    if actual_count <= 0 or tcount <= 0 or bcount <= 0:
        raise RuntimeError(f'CikguLaju runtime database incomplete: visuals={actual_count}, templates={tcount}, blueprints={bcount}')
    return True

_assert_release_pair_v2325()

# v23.26 — deterministic worksheet response-geometry QA.
def _worksheet_v2326_rule(key, default=None):
    try:
        with _db() as con:
            r=con.execute("SELECT rule_value FROM worksheet_v2326_runtime_rules WHERE rule_key=? AND mandatory=1",(key,)).fetchone()
        return r[0] if r else default
    except Exception:
        return default

def _worksheet_complete_word_slots_v2326(answer, shown=''):
    answer=''.join(ch for ch in str(answer or '').upper() if ch.isalpha())
    shown=''.join(ch for ch in str(shown or '').upper() if ch.isalpha())
    if not answer:
        return []
    slots=[]
    for i,ch in enumerate(answer):
        keep = i < len(shown) and shown[i] == ch
        slots.append(ch if keep else '_')
    return slots

def _worksheet_response_geometry_v2326(task_type, *, answer=None, shown=None,
                                      source_count=None, target_count=None,
                                      missing_count=None, response_count=None,
                                      visual_count=None):
    t=str(task_type or '').strip().lower()
    if t=='complete_word':
        slots=_worksheet_complete_word_slots_v2326(answer,shown)
        missing=sum(1 for x in slots if x=='_')
        if response_count is not None and int(response_count)!=missing:
            raise RuntimeError(f'Worksheet QA complete_word: response={response_count}, missing={missing}')
        return slots
    if t=='matching' and source_count is not None and target_count is not None:
        if int(source_count)!=int(target_count):
            raise RuntimeError(f'Worksheet QA matching: source={source_count}, target={target_count}')
    if t=='sequence_numbers' and missing_count is not None and response_count is not None:
        if int(missing_count)!=int(response_count):
            raise RuntimeError(f'Worksheet QA sequence: missing={missing_count}, response={response_count}')
    if t in ('visual_mcq','visual_classification','visual_label','count_visual'):
        if visual_count is not None and response_count is not None and int(visual_count)!=int(response_count):
            raise RuntimeError(f'Worksheet QA visual response: visual={visual_count}, response={response_count}')
    return True

