# ===== v23.88 CURRICULUM-FIRST TEMPLATE ELIGIBILITY =====
def _verified_template_candidates_v2388(subject, year_num, unit='', topic='', sk='', sp='',
                                         skill='', objective='', textbook='', page='', surface='bbm'):
    """Return only templates with VERIFIED curriculum eligibility. Topic-only fallback is forbidden."""
    import os, sqlite3
    p=os.path.join(os.path.dirname(__file__),'CikguLaju_Templates_02.db')
    if not os.path.exists(p) or not str(sp or '').strip():
        return []
    con=sqlite3.connect(p); con.row_factory=sqlite3.Row
    try:
        q="""SELECT e.*,m.family_key,m.variant_no,m.layout_json,m.render_rules_json,
                    f.activity_type,f.answer_policy,f.default_palette
             FROM template_eligibility_rule e
             JOIN template_master m ON m.template_key=e.template_key AND m.approved=1
             JOIN template_family f ON f.family_key=m.family_key AND f.approved=1
             WHERE e.verified=1 AND e.subject=? AND ? BETWEEN e.year_min AND e.year_max
               AND f.surface=? AND (e.sp_pattern='' OR lower(?) LIKE '%'||lower(e.sp_pattern)||'%')
             ORDER BY e.priority DESC,m.variant_no ASC"""
        rows=[dict(r) for r in con.execute(q,(subject,int(year_num or 1),surface,str(sp))).fetchall()]
        def match(pattern,value):
            if not pattern: return True
            val=str(value or '').lower()
            return any(x.strip().lower() in val for x in str(pattern).split('|') if x.strip())
        out=[]
        for r in rows:
            if not match(r.get('unit_pattern'),unit): continue
            if not match(r.get('topic_pattern'),topic): continue
            if not match(r.get('sk_pattern'),sk): continue
            # Skill/objective evidence is required when the rule declares it.
            if r.get('skill_pattern') and not (match(r['skill_pattern'],skill) or match(r['skill_pattern'],objective)):
                continue
            out.append(r)
        return out
    finally:
        con.close()

def _curriculum_template_or_fail_v2388(**ctx):
    rows=_verified_template_candidates_v2388(**ctx)
    if rows:
        return rows[0], None
    return None, ("CikguLaju belum mempunyai pemetaan template yang disahkan untuk kombinasi "
                  "Tahun/Tingkatan + Subjek + SK/SP + kemahiran ini. Bahan tidak dijana untuk "
                  "mengelakkan worksheet/BBM yang cantik tetapi tidak tepat kurikulum.")
# ===== END v23.88 CURRICULUM-FIRST TEMPLATE ELIGIBILITY =====


