# ===== v23.102 PHYSICAL TEMPLATE SHARD COMPATIBILITY =====
def _template_union_con_v23102():
    import os,glob,sqlite3,re
    root=os.path.dirname(__file__)
    paths=sorted(glob.glob(os.path.join(root,'CikguLaju_Templates_[0-9][0-9].db')))
    con=sqlite3.connect(':memory:'); con.row_factory=sqlite3.Row
    attached=[]
    for i,p in enumerate(paths):
        alias='ts'+str(i)
        con.execute("ATTACH DATABASE ? AS "+alias,(p,))
        attached.append(alias)
    names={}
    for alias in attached:
        for r in con.execute("SELECT name FROM "+alias+".sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"):
            names.setdefault(r[0],[]).append(alias)
    for name,aliases in names.items():
        if name in ('cikgulaju_shard_manifest','cikgulaju_shard_tables'): continue
        safe=name.replace('"','""')
        parts=['SELECT * FROM '+a+'."'+safe+'"' for a in aliases]
        con.execute('CREATE TEMP VIEW "'+safe+'" AS '+' UNION ALL '.join(parts))
    return con

