def _quick_rpt_commit_v2388(cid,idx):
    ss=state.setdefault(cid,{})
    rows=ss.get('_quick_rpt_rows_v2388') or []
    if idx<0 or idx>=len(rows): return _quick_rpt_menu_v2388(cid)
    r=rows[idx]
    ss['task']='quick_material'; ss['quick_material_flow']=True; ss['rph_mode']='fast_rpt'
    ss['topic']=str(r.get('unit_title') or r.get('topic') or r.get('theme') or '').strip()
    ss['subtopic']=str(r.get('topic') or r.get('unit_title') or '').strip()
    # Reuse verified RPT→standard resolver already used by RPH Pantas.
    try:
        _apply_rpt_structure_context_v2384(ss,r)
        sk_full=(r.get('sk') or [''])[0] if (r.get('sk') or []) else ''
        m=re.match(r'^([^\s]+)\s*(.*)$',str(sk_full).strip())
        sk_code=(m.group(1) if m else str(sk_full)).strip(); sk_text=(m.group(2) if m else '').strip()
        sp_rows=[]
        for x in (r.get('sp_rows') or []):
            sp_rows.append({'sk_code':sk_code,'sk_text':sk_text,'sp_code':str(x.get('sp_code') or '').strip(),'sp_text':str(x.get('sp_text') or '').strip()})
        ok=bool(sp_rows)
        if ok:
            _commit_multi_sp(ss,sp_rows[:4])
    except Exception as e:
        print('v23.88 quick RPT mapping:',repr(e),flush=True); ok=False
    if not ok or not str(ss.get('sp_code') or '').strip():
        return send(cid,'🚧 <b>Pemetaan SK/SP untuk lesson RPT/SOW ini masih dalam pembinaan.</b>\
\
Bahan tidak direka secara rawak.',[[{'text':'⬅️ Pilih Lesson Lain','callback_data':'quick_rpt'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    return _temporary_auto_pack_v2386(cid)

