def _rpt_unit_groups_v2390(rows):
    groups=[]; pos={}
    for r in rows or []:
        key=_rpt_unit_key_v2390(r) or 'Fokus RPT/SOW'
        if key not in pos:
            pos[key]=len(groups); groups.append({'title':key,'rows':[]})
        groups[pos[key]]['rows'].append(r)
    return groups

