def _quick_rpt_lessons_v2390(cid,unit_idx):
    ss=state.setdefault(cid,{})
    groups=ss.get('_quick_rpt_unit_groups_v2390') or []
    if unit_idx<0 or unit_idx>=len(groups): return _quick_rpt_units_v2390(cid)
    g=groups[unit_idx]; ss['_quick_rpt_unit_idx_v2390']=unit_idx
    rows=g.get('rows') or []
    kb=[]
    for j,r in enumerate(rows[:50]):
        # Use source sequence/week/focus only; never invent a lesson number.
        seq=str(r.get('sequence_no') or '').strip()
        wk=str(r.get('week_from') or '').strip()
        focus=str(r.get('subtopic') or r.get('skill_focus') or '').strip()
