def _quick_content_options_v2391(year_label, subject):
    """Verified source-backed Tema/Unit/Tajuk options. No synthetic curriculum labels."""
    out=[]; seen=set()
    for r in (_rpt_rows(year_label,subject) or []):
        x=str(r.get('unit_title') or r.get('topic') or r.get('theme') or '').strip()
        if x and x.casefold() not in seen:
            seen.add(x.casefold()); out.append(x)
    for r in (_textbook_page_rows(year_label,subject) or []):
        x=str(r.get('topic') or '').strip()
        if x and x.casefold() not in seen:
            seen.add(x.casefold()); out.append(x)
    return out

def _quick_content_menu_v2391(cid,page=0):
    ss=state.setdefault(cid,{})
    opts=_quick_content_options_v2391(ss.get('year',''),ss.get('subject',''))
    if not opts:
        return send(cid,'🚧 <b>Tema / Unit / Tajuk verified untuk pilihan ini masih dalam pembinaan.</b>',[[{'text':'⬅️ Tukar Subjek','callback_data':'choose_grade'},{'text':'🏠 Menu Utama','callback_data':'home'}]])
    ss['_quick_content_opts_v2391']=opts
    per=10; start=max(0,page)*per; end=min(start+per,len(opts)); kb=[]
    for i in range(start,end):
        kb.append([{'text':('📘 '+opts[i])[:60],'callback_data':f'qctx91_{i}'}])
    nav=[]
    if start>0: nav.append({'text':'⬅️ Sebelum','callback_data':f'qctxp91_{page-1}'})
    if end<len(opts): nav.append({'text':'Seterusnya ➡️','callback_data':f'qctxp91_{page+1}'})
    if nav: kb.append(nav)
    kb.append([{'text':'⬅️ Tukar Subjek','callback_data':'choose_grade'},{'text':'🏠 Menu Utama','callback_data':'home'}])
    return send(cid,f"📚 <b>{html.escape(str(ss.get('subject','')))} • {html.escape(str(ss.get('year','')))}</b>\n\nPilih <b>Tema / Unit / Tajuk</b> dahulu. Selepas itu pilih sama ada mahu ikut <b>Buku Teks</b> atau <b>RPT/SOW</b>.",kb)

def _same_content_v2391(value, selected):
    a=str(value or '').strip().casefold(); b=str(selected or '').strip().casefold()
    return bool(a and b and (a==b or a in b or b in a))

