# ===== v23.94 PROFILE CLASS-SUBJECT LINKING + SMART CLASS FILTER =====
APP_VERSION = 'v23.94-PROFILE-CLASS-SUBJECT-LINK'

# Preserve subject links inside class_profiles JSON.
_clean_profile_class_records_v2394_base = _clean_profile_class_records
def _clean_profile_class_records(records):
    base = _clean_profile_class_records_v2394_base(records)
    src = []
    for x in records or []:
        src.append(x if isinstance(x,dict) else {'name':x})
    byname = {str(x.get('name') or x.get('class_name') or '').strip().casefold():x for x in src if isinstance(x,dict)}
    for r in base:
        old = byname.get(str(r.get('name') or '').casefold()) or {}
        yl = str(old.get('year_label') or '').strip()[:30]
        if yl: r['year_label'] = yl
        subjects=[]
        for sub in (old.get('subjects') or []):
            sub=' '.join(str(sub or '').strip().split())[:80]
            if sub and sub.casefold() not in [x.casefold() for x in subjects]: subjects.append(sub)
        if subjects: r['subjects']=subjects
    return base


def _profile_class_records_for_context_v2394(cid, year_label, subject):
    """Filter by level; when subject links have been configured, also filter by subject.
    Backward compatible: profiles not yet configured with subject links still show level-matched classes.
    """
    level_rows=_profile_class_records_for_year_v2393(cid,year_label)
    if not level_rows: return []
    configured=any(bool(r.get('subjects')) for r in level_rows)
    if not configured: return level_rows
    want=_norm_subject_v2393(subject)
    out=[]
    for r in level_rows:
        if any(_norm_subject_v2393(x)==want for x in (r.get('subjects') or [])):
            out.append(r)
    return out


