def _profile_class_subject_menu_v2394(cid):
    ss=state.setdefault(cid,{})
    try: idx=int(ss.get('profile_class_idx'))
    except Exception: return _profile_class_manage_menu(cid)
    rows=_profile_class_records(cid)
    if idx<0 or idx>=len(rows): return _profile_class_manage_menu(cid)
    row=rows[idx]; yl=str(row.get('year_label') or '').strip()
    if not yl:
        return send(cid,'🎓 Tetapkan Tahun/Tingkatan kelas dahulu sebelum memilih subjek.',[[{'text':'🎓 Tetapkan Tahun/Tingkatan','callback_data':'profclass_level93'}],[{'text':'⬅️ Kembali','callback_data':'profclass_manage'}]])
    opts=list(SUBJECTS_BY_GRADE.get(yl,[]) or [])
    if not opts:
        return send(cid,'🚧 Senarai subjek untuk tahap ini masih dalam pembinaan.',[[{'text':'⬅️ Kembali','callback_data':'profclass_manage'}]])
    ss['_profsub94_opts']=opts
    selected={_norm_subject_v2393(x) for x in (row.get('subjects') or [])}
    kb=[]
    for i,sub in enumerate(opts):
        mark='✅ ' if _norm_subject_v2393(sub) in selected else '☐ '
        kb.append([{'text':(mark+SUBJECT_LABEL.get(sub,sub))[:60],'callback_data':f'profsub94_{i}'}])
    kb.append([{'text':'💾 Selesai','callback_data':'profsub94_done'}])
    kb.append([{'text':'⬅️ Kembali','callback_data':'profclass_manage'}])
    return send(cid,f"📚 <b>Subjek • {html.escape(row.get('name',''))}</b>\n\nPilih semua subjek yang anda ajar untuk kelas ini. Tekan sekali untuk pilih/buang.",kb)

_callback_dispatch_v2394_base=callback
def callback(cid,d):
    ss=state.setdefault(cid,{})
    if d=='profclass_subject94':
        return _profile_class_subject_menu_v2394(cid)
    if d.startswith('profsub94_') and d!='profsub94_done':
        try:
            j=int(d.rsplit('_',1)[1]); sub=(ss.get('_profsub94_opts') or [])[j]; idx=int(ss.get('profile_class_idx'))
        except Exception: return _profile_class_manage_menu(cid)
        rows=_profile_class_records(cid)
        if not (0<=idx<len(rows)): return _profile_class_manage_menu(cid)
        cur=list(rows[idx].get('subjects') or [])
        norm=_norm_subject_v2393(sub)
        if any(_norm_subject_v2393(x)==norm for x in cur):
            cur=[x for x in cur if _norm_subject_v2393(x)!=norm]
        else: cur.append(sub)
        rows[idx]['subjects']=cur; _save_profile_class_records(cid,rows)
        return _profile_class_subject_menu_v2394(cid)
    if d=='profsub94_done':
        try: idx=int(ss.get('profile_class_idx'))
        except Exception: return _profile_class_manage_menu(cid)
        return _profile_class_item_menu(cid,idx)
    return _callback_dispatch_v2394_base(cid,d)

