# Class setup remains level-first and suffix-only. Duplicate detection is level-aware and case-insensitive.
def _canonical_class_name_v2401(year_label, raw):
    yl=str(year_label or '').strip(); num=_year_number_v2393(yl) or ''
    suffix=' '.join(str(raw or '').strip().split())[:50]
    if num:
        suffix=re.sub(r'^\s*(?:tahun|tingkatan)?\s*'+re.escape(num)+r'\s*[-–:]?\s*','',suffix,flags=re.I).strip()
    return (f'{num} {suffix}'.strip())[:60], suffix

# Better timetable save: prevent exact duplicates and warn on overlapping slots for the same class/day.
def _tt_save_buttons_v2395(cid,dur):
    ss=state.setdefault(cid,{})
    rows=_profile_class_records(cid)
    try:
        ci=int(ss.get('tt_class_idx')); row=rows[ci]
        start=ss['_tt_start95']; subject=ss['_tt_subject95']; day=ss['tt_day']
        h,m=map(int,start.split(':')); sm=h*60+m; total=sm+int(dur); end=f'{total//60:02d}:{total%60:02d}'
    except Exception:
        return _timetable_menu(cid,'⚠️ Maklumat jadual tidak lengkap.')
    entries=list(row.get('timetable') or [])
    new={'day':day,'start':start,'end':end,'subject':subject}
    exact=False; overlaps=[]
    for e in entries:
        if str(e.get('day') or '')!=day: continue
        try:
            ah,am=map(int,str(e.get('start')).split(':')); bh,bm=map(int,str(e.get('end')).split(':'))
            a=ah*60+am; b=bh*60+bm
        except Exception: continue
        if str(e.get('start'))==start and str(e.get('end'))==end and _norm_subject_v2393(e.get('subject'))==_norm_subject_v2393(subject):
            exact=True
        elif max(sm,a) < min(total,b):
            overlaps.append(e)
    if exact:
        note='ℹ️ Waktu ini sudah ada dalam jadual.'
    elif overlaps:
        e=overlaps[0]
        return send(cid,
            f"⚠️ <b>Waktu bertindih</b>\n\n{html.escape(str(row.get('name') or 'Kelas'))} sudah mempunyai {html.escape(str(e.get('subject') or 'subjek'))} pada {html.escape(str(e.get('start') or ''))}–{html.escape(str(e.get('end') or ''))}.\n\nPilih masa lain supaya jadual profil kekal konsisten.",
            [[{'text':'🕐 Pilih Masa Lain','callback_data':'ttbackstart95'}],[{'text':'⬅️ Jadual Waktu','callback_data':'timetable'}]])
    else:
        entries.append(new); row['timetable']=entries; rows[ci]=row; _save_profile_class_records(cid,rows)
        note='✅ Waktu berjaya disimpan.'
    for k in ['_tt_subject_opts95','_tt_subject95','_tt_start_opts95','_tt_start95']:
        ss.pop(k,None)
    return _timetable_menu(cid,note)

# Package status vocabulary: worksheet is mandatory; media can genuinely be unrelated.
def _package_component_status_v2401(kind, delivered=False, required=None, available=None):
    if kind=='worksheet':
        return 'dihantar' if delivered else '🚧 Dalam pembinaan'
    if kind=='media':
        if required is False: return 'Tidak berkaitan'
        if delivered or available is True: return 'dihantar'
        return '🚧 Dalam pembinaan'
    return 'dihantar' if delivered else '🚧 Dalam pembinaan'

