# More practical date picker: two weeks ahead, still button-only.
def _pdp_pick_date_v2393(cid):
    """Monthly Sunday-first calendar; replaces the historical linear 7/14-day picker."""
    fn=globals().get('_calendar_v2437') or globals().get('_pdp_calendar_month_v2429')
    if callable(fn):
        return fn(cid)
    raise RuntimeError('Monthly calendar handler is unavailable')

def _pdp_time_options_v2393(cid):
    ss=state.setdefault(cid,{})
    cname=str(ss.get('rph_class') or ''); subject=str(ss.get('subject') or ''); day=str(ss.get('rph_day') or '')
    rec=_profile_class_record(cid,cname) or {}; slots=[]; seen=set()
    for e in rec.get('timetable') or []:
        if str(e.get('day') or '')!=day: continue
        a=_norm_subject_v2393(e.get('subject')); b=_norm_subject_v2393(subject)
        if not (a and b and (a==b or a in b or b in a)): continue
        key=(str(e.get('start') or ''),str(e.get('end') or ''))
        if key in seen: continue
        seen.add(key); slots.append(e)
    slots.sort(key=lambda e:str(e.get('start') or ''))
    ss['_pdp_slots_v2393']=slots
    kb=[]
    for i,e in enumerate(slots[:10]):
        kb.append([{'text':f"🕐 {e.get('start','')}–{e.get('end','')} ⭐ Ikut Jadual",'callback_data':f'pdptime93_{i}'}])
