# Validate timetable against the teacher's WHOLE timetable, not just one class.
# A teacher cannot normally be scheduled in two classes at overlapping times.
def _tt_save_buttons_v2395(cid,dur):
    ss=state.setdefault(cid,{}); rows=_profile_class_records(cid)
    try:
        ci=int(ss.get('tt_class_idx')); row=rows[ci]
        start=ss['_tt_start95']; subject=ss['_tt_subject95']; day=ss['tt_day']
        h,m=map(int,start.split(':')); sm=h*60+m; total=sm+int(dur); end=f'{total//60:02d}:{total%60:02d}'
    except Exception:
        return _timetable_menu(cid,'⚠️ Maklumat jadual tidak lengkap.')
    entries=list(row.get('timetable') or []); exact=False; conflict=None
    # Exact duplicate in selected class.
    for e in entries:
        if str(e.get('day') or '')==day and str(e.get('start') or '')==start and str(e.get('end') or '')==end and _norm_subject_v2393(e.get('subject'))==_norm_subject_v2393(subject):
            exact=True; break
    # Cross-class and same-class overlap check.
    if not exact:
        for ri,other in enumerate(rows):
            for e in other.get('timetable') or []:
                if str(e.get('day') or '')!=day: continue
                try:
                    ah,am=map(int,str(e.get('start')).split(':')); bh,bm=map(int,str(e.get('end')).split(':'))
                    a=ah*60+am; b=bh*60+bm
                except Exception: continue
                if max(sm,a) < min(total,b):
                    conflict=(other,e); break
            if conflict: break
    if exact:
        note='ℹ️ Waktu ini sudah ada dalam jadual.'
    elif conflict:
        other,e=conflict
        return send(cid,
            f"⚠️ <b>Waktu bertindih</b>\n\nPada {html.escape(day)}, jadual guru sudah mempunyai <b>{html.escape(str(other.get('name') or 'kelas'))}</b> • {html.escape(str(e.get('subject') or 'subjek'))} • {html.escape(str(e.get('start') or ''))}–{html.escape(str(e.get('end') or ''))}.\n\nPilih masa lain supaya jadual guru kekal konsisten.",
            [[{'text':'🕐 Pilih Masa Lain','callback_data':'ttbackstart95'}],[{'text':'⬅️ Jadual Waktu','callback_data':'timetable'}]])
    else:
        entries.append({'day':day,'start':start,'end':end,'subject':subject}); row['timetable']=entries; rows[ci]=row
        _save_profile_class_records(cid,rows); note='✅ Waktu berjaya disimpan.'
    for k in ['_tt_subject_opts95','_tt_subject95','_tt_start_opts95','_tt_start95']:
        ss.pop(k,None)
    return _timetable_menu(cid,note)

