    selected=str(ss.get('quick_content_v2391') or '').strip(); yr=ss.get('year',''); sub=ss.get('subject','')
    tb=[r for r in (_textbook_page_rows(yr,sub) or []) if _same_content_v2391(r.get('topic'),selected)]
    coarse=[r for r in (_rpt_rows(yr,sub) or []) if _same_content_v2391(_rpt_unit_key_v2390(r),selected)]
