APP_VERSION = 'v24.06-VERIFIED-STANDARDS-PACKAGE-GATE'

def _apply_textbook_page_sp_context(ss, page_no, lesson_no='', focus=''):
    """Hydrate exact verified SK/SP for the selected page + lesson/focus.

    Never falls back to broad unit standards. Returns the committed verified rows.
    """
    rows=_textbook_exact_page_standards(ss.get('year',''),ss.get('subject',''),page_no,ss.get('textbook_book_title',''))
    if not rows:
        return []
    lesson=str(lesson_no or ss.get('textbook_lesson_no') or '').strip()
    focus0=str(focus or ss.get('textbook_page_focus') or '').strip().casefold()
    exact=[]
    for r in rows:
        rl=str(r.get('lesson_no') or '').strip(); rf=str(r.get('focus') or '').strip().casefold()
        if lesson and rl and rl!=lesson: continue
        if focus0 and rf and rf!=focus0: continue
        exact.append(r)
    if not exact:
        return []
    if not _commit_textbook_page_standards(ss,exact):
        return []
    ss['_verified_standard_rows_v2406']=[dict(r) for r in exact]
    ss['_verified_standard_source_v2406']='textbook_page_sp_map'
    return exact


def _lesson_context_trace_v2405(ss):
    r=ss.get('_verified_lesson_row_v2404') or {}
    standards=ss.get('_verified_standard_rows_v2406') or []
    sp=[]; sk=[]
    for x in standards:
        a=str(x.get('sp_code') or '').strip(); b=str(x.get('sk_code') or '').strip()
        if a and a not in sp: sp.append(a)
        if b and b not in sk: sk.append(b)
    return {
        'year':ss.get('year',''),'subject':ss.get('subject',''),
        'content':ss.get('quick_content_v2391',''),'source':'RPT/SOW',
        'lesson_no':r.get('lesson_no') or ss.get('textbook_lesson_no',''),
        'focus':r.get('focus') or ss.get('textbook_page_focus',''),
        'page_start':r.get('page_start') if r else ss.get('textbook_page_start'),
        'page_end':r.get('page_end') if r else ss.get('textbook_page_end'),
        'content_topic':r.get('content_topic') or ss.get('textbook_content_topic',''),
        'language_focus':r.get('language_focus') or ss.get('textbook_language_focus',''),
        'activity_ref':r.get('activity_ref') or ss.get('textbook_activity_ref',''),
        'sk_codes':sk,'sp_codes':sp,
        'lesson_verified':bool(r and r.get('verified')),
        'standards_verified':bool(standards),
        'verified':bool(r and r.get('verified') and standards),
    }


def _lesson_material_gate_v2406(ss):
    """Return factual readiness for a selected lesson without inventing missing mappings."""
    trace=ss.get('_pdp_source_trace_v2405') or _lesson_context_trace_v2405(ss)
    page=trace.get('page_start') or ss.get('textbook_page') or ss.get('page')
    lesson_ok=bool(trace.get('lesson_verified'))
    standards_ok=bool(trace.get('standards_verified'))
    return {
        'lesson_verified':lesson_ok,
        'standards_verified':standards_ok,
        'page_verified':bool(page),
        'worksheet_required':True,
        # Activity-book bank is currently empty; unknown is not treated as unrelated.
        'activity_book':None,
        # Media requirement must be source-mapped later; unknown is never guessed False.
        'media_required':None,
        'ready_for_generation':bool(lesson_ok and standards_ok),
    }


def _commit_verified_lesson_v2404(cid,idx):
    ss=state.setdefault(cid,{})
    rows=ss.get('_quick_verified_lesson_rows_v2404') or []
    if idx<0 or idx>=len(rows): return _quick_rpt_for_content_v2391(cid)
    r=rows[idx]
    ss['rph_mode']='fast_rpt'; ss['textbook_lesson_no']=str(r.get('lesson_no') or ''); ss['textbook_page_focus']=str(r.get('focus') or '')
    ss['textbook_content_topic']=str(r.get('content_topic') or ''); ss['textbook_language_focus']=str(r.get('language_focus') or '')
    ss['textbook_activity_ref']=str(r.get('activity_ref') or ''); ss['textbook_book_title']=str(r.get('book_title') or '')
    ss['textbook_page_start']=r.get('page_start'); ss['textbook_page_end']=r.get('page_end'); ss['textbook_page']=r.get('page_start'); ss['book_page']=r.get('page_start'); ss['page']=r.get('page_start')
    ss['_verified_lesson_row_v2404']=dict(r)
    try: _apply_textbook_page_lesson_context(ss,r.get('page_start'),r.get('lesson_no'),r.get('focus'))
    except Exception: pass
    try: _apply_textbook_page_sp_context(ss,r.get('page_start'),r.get('lesson_no'),r.get('focus'))
    except Exception as e: print('v24.06 standard hydration:',repr(e),flush=True)
    ss['_pdp_source_trace_v2405']=_lesson_context_trace_v2405(ss)
    ss['_lesson_material_gate_v2406']=_lesson_material_gate_v2406(ss)
