    if '_pdp_choose_class_v2393' in globals(): return _pdp_choose_class_v2393(cid)
    if '_pdp_pick_class_v2393' in globals(): return _pdp_pick_class_v2393(cid)
    if '_quick_context_class_v2393' in globals(): return _quick_context_class_v2393(cid)
    return send(cid,'✅ Lesson dan SK/SP verified telah dipilih.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])


