# ===== v24.07 LARGE BATCH: LESSON MATERIAL REQUIREMENTS + MEDIA/ACTIVITY LOOKUP =====
APP_VERSION = 'v24.07-LESSON-MATERIAL-REQUIREMENTS'

def _lesson_material_requirement_v2407(ss):
    """Read only verified lesson requirement metadata. Unknown stays None; never infer media need."""
    r=ss.get('_verified_lesson_row_v2404') or {}
    vals=(ss.get('year',''),ss.get('subject',''),str(r.get('unit_title') or ss.get('quick_content_v2391') or ''),str(r.get('lesson_no') or ss.get('textbook_lesson_no') or ''))
    con=_db()
    try:
        try:
            row=con.execute("""SELECT * FROM lesson_material_requirements
                WHERE year_label=? AND subject=? AND unit_title=? AND lesson_no=? AND verified=1
                ORDER BY id DESC LIMIT 1""",vals).fetchone()
        except Exception:
            row=None
        return dict(row) if row else None
    finally: con.close()

def _lesson_activity_book_rows_v2407(ss):
    """Return only verified/official activity-book mappings compatible with selected lesson context."""
    r=ss.get('_verified_lesson_row_v2404') or {}; year=ss.get('year',''); subject=ss.get('subject','')
    unit=str(r.get('unit_title') or ss.get('quick_content_v2391') or '')
    lesson=str(r.get('lesson_no') or ss.get('textbook_lesson_no') or '')
    con=_db()
    try:
        try:
            cols={x[1] for x in con.execute('PRAGMA table_info(activity_book_mappings)').fetchall()}
            if not cols: return []
            sql="SELECT * FROM activity_book_mappings WHERE year_label=? AND subject=?"
            args=[year,subject]
            if 'unit_title' in cols and unit: sql += " AND unit_title=?"; args.append(unit)
            if 'lesson_title' in cols and lesson: sql += " AND (lesson_title=? OR lesson_title='')"; args.append(lesson)
            if 'mapping_status' in cols: sql += " AND lower(mapping_status) IN ('verified','official_verified','textbook_verified','sow_rpt_verified')"
            sql += " ORDER BY id"
            return [dict(x) for x in con.execute(sql,args).fetchall()]
        except Exception: return []
    finally: con.close()

def _lesson_media_rows_v2407(ss):
    r=ss.get('_verified_lesson_row_v2404') or {}; year=ss.get('year',''); subject=ss.get('subject','')
    unit=str(r.get('unit_title') or ss.get('quick_content_v2391') or ''); lesson=str(r.get('lesson_no') or ss.get('textbook_lesson_no') or '')
    con=_db()
    try:
        try:
            return [dict(x) for x in con.execute("""SELECT * FROM lesson_media_map
              WHERE year_label=? AND subject=? AND unit_title=? AND lesson_no=? AND verified=1 ORDER BY id""",
              (year,subject,unit,lesson)).fetchall()]
        except Exception: return []
    finally: con.close()

def _lesson_material_gate_v2406(ss):
    trace=ss.get('_pdp_source_trace_v2405') or _lesson_context_trace_v2405(ss)
    req=_lesson_material_requirement_v2407(ss); activity=_lesson_activity_book_rows_v2407(ss); media=_lesson_media_rows_v2407(ss)
    media_required=(None if req is None or req.get('media_required') is None else bool(req.get('media_required')))
    if media: media_required=True
    return {
        'lesson_verified':bool(trace.get('lesson_verified')),
        'standards_verified':bool(trace.get('standards_verified')),
        'page_verified':bool(trace.get('page_start') or ss.get('textbook_page') or ss.get('page')),
        'worksheet_required':True,
        'bbm_required':True if req is None else bool(req.get('bbm_required',1)),
        'activity_book': True if activity else None,
        'activity_book_rows':activity,
        'media_required':media_required,
        'media_rows':media,
        'requirements_verified':bool(req),
        'ready_for_generation':bool(trace.get('lesson_verified') and trace.get('standards_verified')),
    }

