# ===== v24.11 LESSON RESOLUTION DIAGNOSTICS =====
def _lesson_resolution_status_v2411(ss):
    trace=ss.get('_pdp_source_trace_v2405') or _lesson_context_trace_v2405(ss)
    if trace.get('standards_verified'):
        return 'verified_standards'
    if trace.get('standards_not_applicable'):
        return 'not_applicable_explicit_source'
    return 'open_gap'

def _lesson_resolution_label_v2411(ss):
    st=_lesson_resolution_status_v2411(ss)
    if st=='verified_standards': return '✅ SK/SP disahkan'
    if st=='not_applicable_explicit_source': return 'ℹ️ SK/SP khusus tidak berkaitan untuk Lesson ini berdasarkan sumber'
    return '🚧 Status SK/SP masih dalam pembinaan'

def _lesson_package_readiness_v2409(ss):
    diag=_lesson_package_diagnostic_v2408(ss); cov=diag.get('coverage') or {}; manifest=diag.get('manifest') or {}; blockers=[]
    resolution=_lesson_resolution_status_v2411(ss)
    if not cov.get('lesson'): blockers.append('Lesson RPT/SOW belum verified')
    if resolution=='open_gap': blockers.append('status SK/SP Lesson belum disahkan')
    # Missing textbook page is reported as a coverage gap but does not destroy partial-success core if lesson+standards are resolved.
    coverage_notes=[]
    if not cov.get('textbook_page'): coverage_notes.append('🚧 Halaman Buku Teks masih dalam pembinaan')
    if not cov.get('activity_book'): coverage_notes.append('🚧 Pemetaan Buku Aktiviti masih dalam pembinaan')
    if not cov.get('media_requirement_known'): coverage_notes.append('🚧 Keperluan Audio/Media masih dalam pembinaan')
    return {'can_process_core':bool(cov.get('lesson') and resolution!='open_gap'),
      'mandatory_components':('RPH','Worksheet','BBM'),'blockers':blockers,'coverage_notes':coverage_notes,
      'standard_resolution':resolution,'standard_resolution_label':_lesson_resolution_label_v2411(ss),
      'manifest':manifest,'coverage':cov,'mapping_key':_lesson_mapping_key_v2409(ss)}

