def _mvp_true_ready_v2421(row):
    """A lesson is READY only when exact source content and all three teacher deliverables are verified."""
    if not row:
        return False
    def _g(k, default=0):
        try:
            return row[k]
        except Exception:
            return default
    return bool(_g("standards_verified") and _g("textbook_content_verified") and _g("rph_ready") and _g("worksheet_ready") and _g("bbm_ready"))

# ===== v24.25 SMALL-DEPLOY BM1 MIGRATION + LESSON AUTO-SP SAFETY =====
# Upload app.py together with migration_bm1_v24_24.sql. The runtime DB is upgraded
# in place; the large curriculum DB file does not need to be replaced.
def _apply_bm1_small_migration_v2425():
    import os as _os
    sql_path = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), 'migration_bm1_v24_24.sql')
    if not _os.path.exists(sql_path):
        return False
    con = _db()
    try:
        # Fast idempotency check.
        r = con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='bm1_dbfirst_package_v2424'").fetchone()
        if r:
            n = con.execute("SELECT COUNT(*) FROM bm1_dbfirst_package_v2424").fetchone()[0]
            if int(n or 0) >= 29:
                return True
        with open(sql_path, 'r', encoding='utf-8') as f:
            con.executescript(f.read())
        return True
    except Exception as e:
        print('v24.25 BM1 migration:', repr(e), flush=True)
        return False
    finally:
        con.close()

try:
    _apply_bm1_small_migration_v2425()
except Exception as _e:
    print('v24.25 startup migration:', repr(_e), flush=True)

