# ===== v24.27 QUICK CONTENT DB-READ HOTFIX =====
# Hotfix for deployments rebuilt from split DB parts: read verified curriculum
# options directly from the runtime SQLite file if a layered/sharded lookup
# unexpectedly returns no rows. No curriculum content is synthesized.
def _quick_content_options_v2427(year_label, subject):
    yr = str(year_label or '').strip()
    sub = str(subject or '').strip()
    out=[]; seen=set()
    def add(v):
        v=str(v or '').strip()
        if v and v.casefold() not in seen:
            seen.add(v.casefold()); out.append(v)
    # First use the normal verified readers.
    try:
        for r in (_rpt_rows(yr,sub) or []):
            add(r.get('unit_title') or r.get('topic') or r.get('theme'))
        for r in (_textbook_page_rows(yr,sub) or []):
            add(r.get('topic'))
    except Exception as e:
        print('v24.27 normal content lookup:',repr(e),flush=True)
    if out:
        return out
    # Pendidikan Islam primary: when a verified RPT/textbook content layer is
    # not present for a year, use the verified curriculum topic labels as the
    # source-backed selection layer. This does not invent curriculum labels;
    # the labels come directly from verified curriculum_standards.
    if sub == 'Pendidikan Islam' and yr.startswith('Tahun '):
        try:
            con=sqlite3.connect(DB_PATH, timeout=15)
            con.row_factory=sqlite3.Row
            try:
                rows=con.execute("""SELECT topic, MIN(id) AS id
                                    FROM curriculum_standards
                                    WHERE year_label=? AND subject=? AND verified=1
                                      AND COALESCE(TRIM(topic),'') <> ''
                                    GROUP BY topic ORDER BY MIN(id)""",(yr,sub)).fetchall()
                for r in rows: add(r['topic'])
            finally:
                con.close()
        except Exception as e:
            print('v24.27 PI curriculum topic fallback:',repr(e),flush=True)
        if out:
            return out
    # Deployment-safe fallback: same verified tables, direct SQLite connection.
    try:
        con=sqlite3.connect(DB_PATH, timeout=15)
        con.row_factory=sqlite3.Row
        try:
            rows=con.execute("""SELECT unit_title,topic,theme FROM rpt_entries
                                WHERE year_label=? AND subject=? AND verified=1
                                  AND lower(COALESCE(notes,'')) NOT LIKE '%superseded%'
                                ORDER BY CASE WHEN week_from IS NULL THEN 999 ELSE week_from END,
                                         sequence_no,id""",(yr,sub)).fetchall()
            for r in rows:
                add(r['unit_title'] or r['topic'] or r['theme'])
            rows=con.execute("""SELECT topic FROM textbook_references
                                WHERE year_label=? AND subject=? AND verified=1
                                ORDER BY page_start,id""",(yr,sub)).fetchall()
            for r in rows: add(r['topic'])
        finally:
            con.close()
    except Exception as e:
        print('v24.27 direct content lookup:',repr(e),flush=True)
    return out

def _quick_content_menu_v2427(cid,page=0):
    ss=state.setdefault(cid,{})
    yr=str(ss.get('year') or '').strip(); sub=str(ss.get('subject') or '').strip()
    opts=_quick_content_options_v2427(yr,sub)
    if not opts:
        print('v24.27 no verified content:',repr(yr),repr(sub),'DB=',DB_PATH,flush=True)
        return send(cid,'🚧 <b>Tema / Unit / Tajuk verified untuk pilihan ini masih dalam pembinaan.</b>',[[{'text':'⬅️ Tukar Subjek','callback_data':'choose_grade'},{'text':'🏠 Menu Utama','callback_data':'home'}]])
    ss['_quick_content_opts_v2391']=opts
    per=10; page=max(0,int(page or 0)); start=page*per; end=min(start+per,len(opts)); kb=[]
    for i in range(start,end):
        kb.append([{'text':('📘 '+opts[i])[:60],'callback_data':f'qctx91_{i}'}])
    nav=[]
    if start>0: nav.append({'text':'⬅️ Sebelum','callback_data':f'qctxp27_{page-1}'})
    if end<len(opts): nav.append({'text':'Seterusnya ➡️','callback_data':f'qctxp27_{page+1}'})
    if nav: kb.append(nav)
    kb.append([{'text':'⬅️ Tukar Subjek','callback_data':'choose_grade'},{'text':'🏠 Menu Utama','callback_data':'home'}])
    return send(cid,f"📚 <b>{html.escape(sub)} • {html.escape(yr)}</b>\n\nPilih <b>Tema / Unit / Tajuk</b> dahulu. Selepas itu pilih sama ada mahu ikut <b>Buku Teks</b> atau <b>RPT/SOW</b>.",kb)

