def _is_quick_pdp_v2428(ss):
    return bool(ss.get('task') == 'quick_material' or ss.get('quick_material_flow'))

def callback(cid, d):
    ss = state.setdefault(cid, {})
    ds = str(d or '')

    # Subject selection in the main PdP flow always opens verified content-first menu.
    if ds.startswith('sub_') and _is_quick_pdp_v2428(ss):
        ss['task'] = 'quick_material'
        ss['quick_material_flow'] = True
        ss['subject'] = ds[4:]
        ss['assessment_mode'] = 'formative'
        for k in ('topic','subtopic','selected_topic_index','topic_list','quick_content_v2391',
                  '_quick_tb_rows_v2391','_quick_rpt_rows_content_v2391','selected_sk','selected_sp'):
            ss.pop(k, None)
        return _quick_content_menu_v2427(cid, 0)

    # Defensive compatibility for already-open legacy Telegram messages: if a teacher
    # taps an old topic button while in Sediakan Bahan PdP, redirect to source-first
    # content selection instead of opening SK/SP.
    if ds.startswith('topic_') and _is_quick_pdp_v2428(ss) and ss.get('rph_mode') != 'fast_custom':
        ss['task'] = 'quick_material'
        ss['quick_material_flow'] = True
        return _quick_content_menu_v2427(cid, 0)

    # Likewise, block legacy SK/SP callbacks from the main route. They are valid only
    # for the explicit Pilih Sendiri/fast_custom branch.
    if _is_quick_pdp_v2428(ss) and ss.get('rph_mode') != 'fast_custom':
        if ds.startswith(('sk_', 'csk|', 'sp_', 'csp|', 'skpage_', 'sppage_')):
            return _quick_content_menu_v2427(cid, 0)

    return _callback_dispatch_v2428_base(cid, d)

