# BM Tahun 1-6: Kemahiran is metadata only. Buku Teks/RPT are internal sources only.
_callback_dispatch_v2496_base = callback

def _bm96_rows(year_label):
    con=_db()
    try:
        rs=con.execute("""SELECT * FROM verified_pdp_sequence
            WHERE year_label=? AND subject='Bahasa Melayu'
              AND COALESCE(verification_status,'') NOT IN ('REJECT_NON_SK','SOURCE_NONCORE')
            ORDER BY CASE WHEN week_no IS NULL THEN 999 ELSE week_no END, id""",
            (str(year_label or '').strip(),)).fetchall()
        return [dict(r) for r in rs]
    finally:
        con.close()

def _bm96_unique(values):
    out=[]; seen=set()
    for value in values:
        v=str(value or '').strip()
        if v and v.casefold() not in seen:
            seen.add(v.casefold()); out.append(v)
    return out

def _bm96_theme_menu(cid,page=0):
    ss=state.setdefault(cid,{})
    rows=_bm96_rows(ss.get('year',''))
    themes=_bm96_unique(r.get('theme') for r in rows)
    ss['_bm96_rows']=rows; ss['_bm96_themes']=themes
    if not themes:
        return send(cid,'🚧 <b>Tema Bahasa Melayu yang disahkan belum tersedia untuk tahun ini.</b>',
                    [[{'text':'⬅️ Tukar Subjek','callback_data':'choose_grade'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    per=10; page=max(0,int(page or 0)); start=page*per; end=min(start+per,len(themes)); kb=[]
    for i in range(start,end):
        kb.append([{'text':('🟦 '+themes[i])[:60],'callback_data':f'bm96_theme_{i}'}])
    nav=[]
    if start: nav.append({'text':'⬅️ Sebelum','callback_data':f'bm96_tp_{page-1}'})
    if end<len(themes): nav.append({'text':'Seterusnya ➡️','callback_data':f'bm96_tp_{page+1}'})
    if nav: kb.append(nav)
    kb.append([{'text':'⬅️ Tukar Subjek','callback_data':'choose_grade'},{'text':'🏠 Menu Utama','callback_data':'home'}])
    return send(cid,f"🇲🇾 <b>Bahasa Melayu • {html.escape(str(ss.get('year') or ''))}</b>\n\nPilih <b>Tema</b>.",kb)

def _bm96_unit_menu(cid,theme_idx):
    ss=state.setdefault(cid,{})
    themes=ss.get('_bm96_themes') or []
    if theme_idx<0 or theme_idx>=len(themes): return _bm96_theme_menu(cid)
    theme=themes[theme_idx]; units=[]; seen=set()
    for r in ss.get('_bm96_rows') or []:
        if str(r.get('theme') or '').strip()!=theme: continue
        key=(str(r.get('unit_code') or '').strip(),str(r.get('unit_title') or '').strip())
        if key[1] and key not in seen: seen.add(key); units.append(key)
    ss['_bm96_theme']=theme; ss['_bm96_units']=units
    kb=[]
    for i,(code,title) in enumerate(units):
        label=(f'Unit {code} • ' if code else '')+title
        kb.append([{'text':('📘 '+label)[:60],'callback_data':f'bm96_unit_{i}'}])
    kb.append([{'text':'⬅️ Tukar Tema','callback_data':'bm96_tp_0'}])
    return send(cid,f"🟦 <b>{html.escape(theme)}</b>\n\nPilih <b>Unit</b>.",kb)

def _bm96_pdp_menu(cid,unit_idx):
    ss=state.setdefault(cid,{})
    units=ss.get('_bm96_units') or []
    if unit_idx<0 or unit_idx>=len(units): return _bm96_theme_menu(cid)
    code,title=units[unit_idx]; theme=ss.get('_bm96_theme','')
    rows=[r for r in (ss.get('_bm96_rows') or [])
          if str(r.get('theme') or '').strip()==theme
          and str(r.get('unit_code') or '').strip()==code
          and str(r.get('unit_title') or '').strip()==title]
    pdps=_bm96_unique(r.get('pdp_title') for r in rows)
    ss['_bm96_unit']=(code,title); ss['_bm96_pdp_rows']=rows; ss['_bm96_pdps']=pdps
    kb=[[{'text':('▶️ '+p)[:60],'callback_data':f'bm96_pdp_{i}'}] for i,p in enumerate(pdps)]
    kb.append([{'text':'⬅️ Tukar Unit','callback_data':f'bm96_theme_{(ss.get("_bm96_themes") or []).index(theme)}'}])
    return send(cid,f"📘 <b>{html.escape((f'Unit {code} • ' if code else '')+title)}</b>\n\nPilih <b>Tajuk PdP</b>.",kb)

def _bm96_commit_pdp(cid,pdp_idx):
    ss=state.setdefault(cid,{})
    pdps=ss.get('_bm96_pdps') or []
    if pdp_idx<0 or pdp_idx>=len(pdps): return _bm96_theme_menu(cid)
    pdp=pdps[pdp_idx]
    rows=[r for r in (ss.get('_bm96_pdp_rows') or []) if str(r.get('pdp_title') or '').strip()==pdp]
    if not rows: return _bm96_theme_menu(cid)
    code,unit=ss.get('_bm96_unit') or ('','')
    r0=rows[0]
    mapped=[]
    seen=set()
    for r in rows:
        sk=str(r.get('sk_code') or '').strip(); sp=str(r.get('sp_code') or '').strip()
        key=(sk,sp)
        if sp and key not in seen:
            seen.add(key); mapped.append({'sk_code':sk,'sk_text':'','sp_code':sp,'sp_text':''})
    if not mapped:
        return send(cid,'🚧 <b>SK/SP yang disahkan untuk PdP ini belum lengkap.</b>',
                    [[{'text':'⬅️ Pilih PdP Lain','callback_data':'bm96_unit_0'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    ss.update({
        'task':'quick_material','quick_material_flow':True,'assessment_mode':'formative',
        'topic':unit,'subtopic':pdp,'pdp_title':pdp,'rpt_theme':str(r0.get('theme') or ''),
        'rpt_unit_title':unit,'rpt_topic':pdp,'skill_metadata':str(r0.get('skill_metadata') or ''),
        'textbook_ref':str(r0.get('textbook_ref') or ''),'activitybook_ref':str(r0.get('activitybook_ref') or '')
    })
    _commit_multi_sp(ss,mapped[:8])
    # After PdP, continue to class -> calendar -> time -> material package.
    fn=globals().get('_lesson_to_class_v2439') or globals().get('_pdp_pick_class_v2393')
    if callable(fn): return fn(cid)
    return _temporary_auto_pack_v2386(cid)

