def _eng12_year_label(ss):
    raw=str(ss.get("year") or ss.get("grade") or ss.get("level") or "").strip().lower()
    if raw in ("tahun 1","1","year 1","year1","y1"): return "Tahun 1"
    if raw in ("tahun 2","2","year 2","year2","y2"): return "Tahun 2"
    return ""

def _eng12_is_english_subject_callback(ds):
    x=str(ds or "").strip().lower().replace("%20"," ")
    return ("bahasa inggeris" in x or "english" in x) and (x.startswith("sub_") or x.startswith("subject_") or x.startswith("subjek_") or x in ("bahasa inggeris","english"))

def _eng12_db_path():
    import os, requests
    # v25.04: audited v15 is authoritative for English Y1/Y2.
    # Legacy/env DBs are fallback only; never let an older Render env path
    # silently override the remapped v15 curriculum/audio data.
    local_v15=os.path.join(os.path.dirname(__file__),"CikguLaju_English_Primary_Year1_Year2_MASTER_320_v15_Y2_UNIT5_AUDIO_COMPLETE.db")
    cached="/tmp/CikguLaju_English_Primary_Year1_Year2_MASTER_320_v15.db"
    fallback=os.path.join(os.path.dirname(__file__),"CikguLaju_English_Primary_Year1_Year2_BOT_READY_v1.db")
    env_path=os.environ.get("CIKGULAJU_ENGLISH_Y1Y2_DB_PATH","").strip()

    if os.path.exists(local_v15) and os.path.getsize(local_v15)>100000:
        return local_v15

    drive_id=os.environ.get("CIKGULAJU_ENGLISH_Y1Y2_V15_DRIVE_ID","1O7UHbE9VpKrCQ7z-74zDQ3VUOB3RbuwA").strip()
    if drive_id:
        try:
            rr=requests.get("https://drive.usercontent.google.com/download",
                params={"id":drive_id,"export":"download","confirm":"t"},
                timeout=60,allow_redirects=True)
            if rr.ok and rr.content[:16].startswith(b"SQLite format 3") and len(rr.content)>100000:
                with open(cached+".tmp","wb") as fh: fh.write(rr.content)
                os.replace(cached+".tmp",cached)
                return cached
            print("English v15 DB download rejected:",rr.status_code,rr.headers.get("content-type"),len(rr.content),flush=True)
        except Exception as e:
            print("English v15 DB download error:",repr(e),flush=True)

    # Use an existing cache only if a fresh v15 download is temporarily unavailable.
    if os.path.exists(cached) and os.path.getsize(cached)>100000:
        print("English runtime using cached v15 after refresh failure",flush=True)
        return cached

    # Non-destructive emergency fallbacks only.
    for x in (env_path,fallback):
        if x and os.path.exists(x) and os.path.getsize(x)>100000:
            print("English runtime using legacy fallback:",x,flush=True)
            return x
    return ""

def _eng12_rows(year_label):
    import sqlite3, json, os
    path=_eng12_db_path()
    verified={}
    master=[]
    if path:
        con=sqlite3.connect(path); con.row_factory=sqlite3.Row
        try:
            try:
                rs=con.execute("""SELECT year_label,subject,lesson_no,unit_title,topic,textbook_title,
                    textbook_page_start,textbook_page_end,workbook_page_start,workbook_page_end,
                    workbook_status,audio_status,audio_reference,ready_for_bot,notes
                    FROM bot_lesson_index WHERE year_label=? AND ready_for_bot=1
                    ORDER BY CAST(lesson_no AS INTEGER)""",(year_label,)).fetchall()
                verified={int(r["lesson_no"]):dict(r) for r in rs}
                # v25.05: merge only explicit audio tracks from VERIFIED Teacher Book
                # guidance. This closes gaps where bot_lesson_index contains SB audio
                # but the verified WB track is stored in audio_procedure (e.g. Y1 L19).
                try:
                    gs=con.execute("""SELECT lesson_no,audio_procedure,verification_status
                        FROM teacher_book_lesson_guidance
                        WHERE year_label=? AND verification_status LIKE 'VERIFIED%'""",(year_label,)).fetchall()
                    for g in gs:
                        ln=int(g["lesson_no"])
                        if ln not in verified: continue
                        proc=str(g["audio_procedure"] or "")
                        explicit=[]
                        for cd,tr in re.findall(r"CD\\s*([123])(?:\\s*[-–:]?\\s*(?:Tracks?|Track)?)?\\s*(\\d{1,2})",proc,re.I):
                            ref=f"CD{int(cd)}-{int(tr):02d}"
                            if ref not in explicit: explicit.append(ref)
                        # Handle ranges such as "CD1 Tracks 14–15" without guessing:
                        # both endpoints are explicitly printed in verified guidance.
                        for cd,a,z in re.findall(r"CD\\s*([123])\\s*(?:Tracks?|Track)?\\s*(\\d{1,2})\\s*[–-]\\s*(\\d{1,2})",proc,re.I):
                            for tr in (a,z):
                                ref=f"CD{int(cd)}-{int(tr):02d}"
                                if ref not in explicit: explicit.append(ref)
                        current=[x.strip() for x in str(verified[ln].get("audio_reference") or "").replace(",", ";").split(";") if x.strip()]
                        for ref in explicit:
                            if ref not in current: current.append(ref)
                        if current:
                            verified[ln]["audio_reference"]="; ".join(current)
                            verified[ln]["audio_status"]="VERIFIED_AUDIO"
                except sqlite3.Error as e:
                    print("English verified TB audio merge:",repr(e),flush=True)
            except sqlite3.Error: verified={}
            try:
                master=con.execute("""SELECT lesson_no,skill_lesson,unit_title,main_content_standard,
                    main_learning_standard,complementary_content_standard,
                    complementary_learning_standard,source_mode
                    FROM sow_master_320 WHERE year_label=? ORDER BY lesson_no""",(year_label,)).fetchall()
            except sqlite3.Error: master=[]
        finally: con.close()
    if len(master)!=160:
        # Primary source is the checked-in canonical JSON. Resolve from several
        # deployment roots because Render/Gunicorn may start with a different CWD.
        roots=[os.path.dirname(os.path.abspath(__file__)), os.getcwd()]
        paths=[]
        for root in roots:
            paths.extend([
                os.path.join(root,"data","english_y1y2_sow_master_320.json"),
                os.path.join(root,"english_y1y2_sow_master_320.json"),
            ])
        payload=None
        for jp in paths:
            try:
                if os.path.exists(jp):
                    with open(jp,"r",encoding="utf-8") as fh: payload=json.load(fh)
                    break
            except Exception as e:
                print("English Y1Y2 canonical master load error:",jp,repr(e),flush=True)
        if isinstance(payload,dict):
            aliases={"Tahun 1":["Tahun 1","Year 1","1"],"Tahun 2":["Tahun 2","Year 2","2"]}
            keys=aliases.get(year_label,[year_label])
            master=next((payload.get(k,[]) for k in keys if isinstance(payload.get(k),list) and len(payload.get(k))==160),[])
        if len(master)!=160:
            # Last-resort embedded master from the stable English runtime block.
            try:
                emb=globals().get("_ENG12_SOW_MASTER") or {}
                master=emb.get(year_label,[]) if isinstance(emb,dict) else []
            except Exception: master=[]
    if len(master)!=160: return list(verified.values())
    out=[]
    for r in master:
        vals=list(r); ln,skill,unit,mcs,mls,ccs,cls=vals[:7]
        item=dict(verified.get(int(ln),{}))
        item.update({"year_label":year_label,"subject":"Bahasa Inggeris","lesson_no":int(ln),
                     "unit_title":unit,"topic":unit,"ready_for_bot":1,
                     "_sow_skill":skill,"_sow_main_cs":mcs,"_sow_main_ls":mls,
                     "_sow_comp_cs":ccs,"_sow_comp_ls":cls})
        out.append(item)
    return out

def _eng12_standards(year_label,lesson_no):
    rows=_eng12_rows(year_label)
    for r in rows:
        if int(r.get("lesson_no") or 0)==int(lesson_no):
            if r.get("_sow_main_cs"):
                return [{"role":"MAIN","content_standard":r["_sow_main_cs"],"learning_standard":r["_sow_main_ls"]},
                        {"role":"COMPLEMENTARY","content_standard":r["_sow_comp_cs"],"learning_standard":r["_sow_comp_ls"]}]
    return []

def _eng12_unit_catalog(year_label,rows):
    # Canonical textbook units. Aliases prevent duplicate buttons caused by
    # punctuation/capitalisation/review labels in SOW rows.
    maps={
        "Tahun 1":{
            "friends":(0,"Friends"), "at school":(1,"At School"),
            "let's play":(2,"Let's Play!"), "lets play":(2,"Let's Play!"),
            "pet show":(3,"Pet Show"), "lunchtime":(4,"Lunchtime"),
        },
        "Tahun 2":{
            "free time":(5,"Free Time"), "the old house":(6,"The Old House"),
            "get dressed":(7,"Get Dressed!"), "the robot":(8,"The Robot"),
            "at the beach":(9,"At The Beach"),
        },
    }.get(year_label,{})
    units=[]; bykey={}
    for r in rows:
        raw=str(r.get("topic") or r.get("unit_title") or "").strip()
        norm=" ".join(raw.lower().replace("’","'").replace("!","").split())
        # SOW review rows belong to the same textbook unit.
        if norm.endswith(" review"): norm=norm[:-7].strip()
        if norm in ("year 1 revision","year 2 revision","revision"):
            key=("extra",norm); title=raw; uno=None
        elif norm in maps:
            uno,title=maps[norm]; key=("unit",uno)
        else:
            key=("extra",norm); title=raw; uno=None
        if key not in bykey:
            bykey[key]={"title":title,"unit_no":uno,"keys":set()}
            units.append(bykey[key])
        bykey[key]["keys"].add(norm)
    return units

def _eng12_unit_menu(cid,page=0):
    ss=state.setdefault(cid,{})
    rows=_eng12_rows(_eng12_year_label(ss))
    if not rows:
        return send(cid,"🚧 <b>Master English Tahun 1–2 gagal dimuatkan pada runtime.</b>",
                    [[{"text":"🏠 Menu Utama","callback_data":"home"}]])
    units=_eng12_unit_catalog(_eng12_year_label(ss),rows)
    ss["_eng12_rows"]=rows; ss["_eng12_units"]=units
    per=10; page=max(0,int(page or 0)); a=page*per; b=min(a+per,len(units)); kb=[]
    for i in range(a,b):
        u=units[i]; uno=u.get("unit_no"); title=u.get("title") or f"Unit {i}"
        label=(f"📘 Unit {uno} - {title}" if uno is not None else f"📚 {title}")
        kb.append([{"text":label[:60],"callback_data":f"eng12_lsnunit_{i}"}])
    nav=[]
    if a: nav.append({"text":"⬅️ Sebelum","callback_data":f"eng12_up_{page-1}"})
    if b<len(units): nav.append({"text":"Seterusnya ➡️","callback_data":f"eng12_up_{page+1}"})
    if nav: kb.append(nav)
    kb.append([{"text":"⬅️ Tukar Subjek","callback_data":"choose_grade"},{"text":"🏠 Menu Utama","callback_data":"home"}])
    return send(cid,f"🇬🇧 <b>Bahasa Inggeris • {ss.get('year','')}</b>\n\nPilih <b>Unit/Tajuk</b>. Selepas itu pilih Lesson; SK/SP dipadankan automatik.",kb)

def _eng12_lesson_menu(cid,ui,page=0):
    ss=state.setdefault(cid,{})
    units=ss.get("_eng12_units") or []
    if ui<0 or ui>=len(units): return _eng12_unit_menu(cid,0)
    unit=units[ui]; keys=set(unit.get("keys") or [])
    def _norm(r):
        raw=str(r.get("topic") or r.get("unit_title") or "").strip()
        n=" ".join(raw.lower().replace("’","'").replace("!","").split())
        if n.endswith(" review"): n=n[:-7].strip()
        return n
    rows=[r for r in (ss.get("_eng12_rows") or []) if _norm(r) in keys]
    rows=sorted(rows,key=lambda r:int(str(r.get("lesson_no") or "0").strip() or 0))
    ss["_eng12_unit_index"]=ui; ss["_eng12_lesson_rows"]=rows
    per=10; page=max(0,int(page or 0)); a=page*per; b=min(a+per,len(rows)); kb=[]
    for i in range(a,b):
        r=rows[i]; ln=str(r.get("lesson_no") or "")
        ps=r.get("textbook_page_start"); pe=r.get("textbook_page_end")
        label=f"📚 Lesson {ln}"
        if ps not in (None,""):
            pg=str(ps) if pe in (None,"",ps) else f"{ps}–{pe}"
            label+=f" · m/s {pg}"
        kb.append([{"text":label[:60],"callback_data":f"eng12_lesson_{i}"}])
    nav=[]
    if a: nav.append({"text":"⬅️ Sebelum","callback_data":f"eng12_lp_{ui}_{page-1}"})
    if b<len(rows): nav.append({"text":"Seterusnya ➡️","callback_data":f"eng12_lp_{ui}_{page+1}"})
    if nav: kb.append(nav)
    kb.append([{"text":"⬅️ Unit/Tajuk","callback_data":"eng12_units"},{"text":"🏠 Menu Utama","callback_data":"home"}])
    uno=unit.get("unit_no"); title=unit.get("title","")
    heading=(f"Unit {uno} - {title}" if uno is not None else title)
    return send(cid,f"📖 <b>{heading}</b>\n\nPilih <b>Lesson</b>. SK/SP tidak perlu dipilih kali kedua.",kb)

def _eng12_audio_zip_path():
    import os,requests,re
    candidates=[
        os.environ.get("CIKGULAJU_SUPERMINDS_AUDIO_ZIP","").strip(),
        os.path.join(os.path.dirname(__file__),"super_minds_1_audio_cds.zip"),
        os.path.join("/tmp","super_minds_1_audio_cds.zip"),
    ]
    for x in candidates:
        if x and os.path.exists(x) and os.path.getsize(x)>1000000:
            return x
    drive_id=os.environ.get("CIKGULAJU_SUPERMINDS_AUDIO_DRIVE_ID","1zN35ALOo0-1N9BYkkZ53_c4t_movwHar").strip()
    if not drive_id:return ""
    out="/tmp/super_minds_1_audio_cds.zip"
    try:
        s=requests.Session()
        # Use Drive's current usercontent endpoint first. Its large-file warning
        # page contains a form whose hidden fields must ALL be replayed.
        url="https://drive.usercontent.google.com/download"
        rr=s.get(url,params={"id":drive_id,"export":"download","confirm":"t"},timeout=60,allow_redirects=True)
        ctype=(rr.headers.get("content-type") or "").lower()
        if "text/html" in ctype:
            html=rr.text
            action=re.search(r'<form[^>]+action="([^"]+)"',html,re.I)
            params={}
            for name,val in re.findall(r'<input[^>]+name="([^"]+)"[^>]+value="([^"]*)"',html,re.I):
                params[name]=val.replace("&amp;","&")
            if not params:
                for name,val in re.findall(r'<input[^>]+value="([^"]*)"[^>]+name="([^"]+)"',html,re.I):
                    params[val]=name
            dl=(action.group(1).replace("&amp;","&") if action else url)
            if params:
                rr=s.get(dl,params=params,timeout=240,stream=True,allow_redirects=True)
        with open(out,"wb") as fh:
            for chunk in rr.iter_content(1024*1024):
                if chunk:fh.write(chunk)
        if rr.ok and os.path.getsize(out)>1000000:
            with open(out,"rb") as fh:
                if fh.read(2)==b"PK":return out
        try:os.unlink(out)
        except Exception:pass
        print("English Y1Y2 audio Drive ZIP download failed:",rr.status_code,(rr.headers.get("content-type") or ""),flush=True)
    except Exception as e:
        print("English Y1Y2 audio Drive ZIP download error:",repr(e),flush=True)
    return ""

def _eng12_audio_member_for_ref(ref,zpath=None):
    import zipfile,re,os
    zpath=zpath or _eng12_audio_zip_path()
    if not zpath: return None
    raw=str(ref or "").strip()
    m=re.search(r"CD\s*([123])\s*[-–:]?\s*(?:Track\s*)?(\d{1,2})",raw,re.I)
    if not m: return None
    cd=int(m.group(1)); track=int(m.group(2))
    with zipfile.ZipFile(zpath) as z:
        names=[n for n in z.namelist() if not n.endswith("/")]
        for n in names:
            low=n.lower()
            base=os.path.basename(n)
            if cd==1:
                cd_ok="/cd 1/" in low or "/cd1/" in low
            elif cd==2:
                cd_ok="/cd 2 " in low or "/cd2 " in low or "/cd 2/" in low or "/cd2/" in low
            else:
                cd_ok="/cd 3" in low or "/cd3" in low
            if cd_ok and re.match(rf"0*{track}(?:\D|$)",base):
                return n
    return None

