    if not bank: return r
    dur=_rph_duration_minutes_v25110(state) if '_rph_duration_minutes_v25110' in globals() else 60
    main=max(15,dur-10); a=max(5,round(main*.27)); b=max(5,round(main*.38)); c=max(5,main-a-b)
