    t=re.sub(r'\s+',' ',str(target or '')).strip()
    t=re.sub(r'^(?:dan\s+)?(?:membezakan|membandingkan|membanding|mengenal pasti|menentukan|menjelaskan|memerihalkan|menyatakan)\s+', '', t, flags=re.I)
    return a,t.strip(' ,;.')

