def _en187_skill_name(value):
    import re
    x=re.sub(r'\s+',' ',str(value or '')).strip()
    low=x.lower()
    for name in ('Listening','Speaking','Reading','Writing','Language Arts'):
        if name.lower() in low:
            return name
    return x

