    # Use only the leading existing label; do not invent a new unit.
    for key in ('skill_focus','topic'):
        v=str(r.get(key) or '').strip()
        if v:
            m=re.match(r'^\s*([^:|•\-–—]{2,40})\s*[:|•\-–—]\s*.+$',v)
            if m:
                return m.group(1).strip()
    return None

