    steps,title=_pi2634_existing_steps(s)
    if len(steps)<4:
        return s

    sizes=_pi2634_partition(len(steps))
    rendered=[]; pos=0
    for ai,size in enumerate(sizes,1):
        head=f"اکتيۏيتي {ai}"
        if ai==1 and title:
            head+=f" - {title}"
        rendered.append(head)
        for j,step in enumerate(steps[pos:pos+size],1):
            rendered.append(f"{j}. {step}")
        pos+=size
